INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016db7b6-f1f3-46c4-a60b-cc84b1ea8332', '河南王尹初到以詩代書先問之', '河南王尹初到以诗代书先问之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["別來王閣老，三歲似須臾。","鬢上斑多少，桮前興有無。","官從分緊慢，情莫問榮枯。","許入朱門否，籃輿一病夫。"]', '["別来王閣老，三歲似須臾。","鬢上斑多少，桮前兴有無。","官從分緊慢，情莫问榮枯。","許入朱门否，籃輿一病夫。"]', '诗', 'shi', '', NULL, '河南王尹初到以詩代書先問之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9176ba4e-b14b-44af-a878-38bfdda4aeab', '池西亭', '池西亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朱欄映晚樹，金魄落秋池。","還似錢唐夜，西樓月出時。"]', '["朱欄映晚樹，金魄落秋池。","還似錢唐夜，西楼月出时。"]', '诗', 'shi', '', NULL, '池西亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578fbe5b-aef5-40b7-96c5-6681d1b639e5', '臨池閑臥', '臨池闲臥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小竹圍庭匝，平池與砌連。","閑多臨水坐，老愛向陽眠。","營役拋身外，幽奇送枕前。","誰家臥牀脚，解繫釣魚船。"]', '["小竹圍庭匝，平池與砌連。","闲多臨水坐，老愛向陽眠。","營役拋身外，幽奇送枕前。","誰家臥牀脚，解繫釣鱼船。"]', '诗', 'shi', '', NULL, '臨池閑臥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38286129-e8db-4e54-a107-fdd78c1fbdbb', '吾廬', '吾廬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾廬不獨貯妻兒，自覺年侵身力衰。","眼下營求容足地，心中準擬挂冠時。","新昌小院松當戶，履道幽居竹遶池。","莫道兩都空有宅，林泉風月是家資。"]', '["吾廬不独貯妻兒，自覺年侵身力衰。","眼下營求容足地，心中準擬挂冠时。","新昌小院松當戶，履道幽居竹遶池。","莫道兩都空有宅，林泉风月是家資。"]', '诗', 'shi', '', NULL, '吾廬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e41161ca-0328-4cc3-b4a6-5861050bc736', '題新居寄宣州崔相公', '題新居寄宣州崔相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["門庭有水巷無塵，好稱閑官作主人。","冷似雀羅雖少客，寬於蝸舍足容身。","疎通竹徑將迎月，掃掠莎臺欲待春。","濟世料君歸未得，南園北曲謾爲鄰。"]', '["门庭有水巷無塵，好稱闲官作主人。","冷似雀羅雖少客，寬於蝸舍足容身。","疎通竹徑將迎月，掃掠莎台欲待春。","濟世料君归未得，南园北曲謾爲鄰。"]', '诗', 'shi', '', NULL, '題新居寄宣州崔相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2247b3d2-8476-4f8a-be6e-d3f8276751d3', '憶杭州梅花因敘舊遊寄蕭協律', '憶杭州梅花因敘旧游寄蕭協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三年閑悶在餘杭，曾爲梅花醉幾場。","伍相廟邊繁似雪，孤山園裏麗如妝。","蹋隨遊騎心長惜，折贈佳人手亦香。","賞自初開直至落，歡因小飲便成狂。","薛劉相次埋新壠，沈謝雙飛出故鄉。","歌伴酒徒零散盡，唯殘頭白老蕭郎。"]', '["三年闲悶在餘杭，曾爲梅花醉幾場。","伍相廟邊繁似雪，孤山园裏丽如妝。","蹋隨游騎心长惜，折贈佳人手亦香。","賞自初开直至落，歡因小饮便成狂。","薛劉相次埋新壠，沈謝雙飞出故乡。","歌伴酒徒零散尽，唯殘头白老蕭郎。"]', '诗', 'shi', '', NULL, '憶杭州梅花因敘舊遊寄蕭協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ebf1cb9-a364-4a45-9980-3c1a662158a3', '病中辱張常侍題集賢院詩因以繼和', '病中辱張常侍題集賢院诗因以繼和', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天祿閣門開，甘泉侍從回。","圖書皆帝籍，寮友盡仙才。","騎省通中掖，龍樓隔上臺。","猶憐病宮相，詩寄洛陽來。"]', '["天祿閣门开，甘泉侍從回。","圖书皆帝籍，寮友尽仙才。","騎省通中掖，龙楼隔上台。","猶怜病宮相，诗寄洛陽来。"]', '诗', 'shi', '', NULL, '病中辱張常侍題集賢院詩因以繼和 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d73a384e-e07c-4d3b-ae1a-3a4b4b6343a9', '早春晚歸', '早春晚归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚歸騎馬過天津，沙白橋紅返照新。","草色連延多隙地，鼓聲閑緩少忙人。","還如南國饒溝水，不似西京足路塵。","金谷風光依舊在，無人管領石家春。"]', '["晚归騎马過天津，沙白橋紅返照新。","草色連延多隙地，鼓声闲緩少忙人。","還如南国饒溝水，不似西京足路塵。","金谷风光依旧在，無人管領石家春。"]', '诗', 'shi', '', NULL, '早春晚歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92527d47-0f5d-456d-991a-363e9845dea0', '贈楊使君', '贈楊使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曾嗟放逐同巴峽，且喜歸還會洛陽。","時命到來須作用，功名未立莫思量。","銀銜叱撥欺風雪，金屑琵琶費酒漿。","更待城東桃李發，共君沈醉兩三場。"]', '["曾嗟放逐同巴峽，且喜归還會洛陽。","时命到来須作用，功名未立莫思量。","銀銜叱撥欺风雪，金屑琵琶費酒漿。","更待城东桃李發，共君沈醉兩三場。"]', '诗', 'shi', '', NULL, '贈楊使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d72d45-26fd-44f6-821c-7f5c73c4ca00', '贈皇甫庶子', '贈皇甫庶子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何因散地共徘徊，人道君才我不才。","騎少馬蹄生易蹶，用稀印鏁澀難開。","妻知年老添衣絮，婢報天寒撥酒醅。","更媿小胥諮拜表，單衫衝雪夜深來。"]', '["何因散地共徘徊，人道君才我不才。","騎少马蹄生易蹶，用稀印鏁澀难开。","妻知年老添衣絮，婢報天寒撥酒醅。","更媿小胥諮拜表，單衫衝雪夜深来。"]', '诗', 'shi', '', NULL, '贈皇甫庶子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75a701ee-d905-4fea-be70-fa585a8ab428', '池上竹下作', '池上竹下作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["穿籬遶舍碧逶迤，十畮閑居半是池。","食飽窗間新睡後，脚輕林下獨行時。","水能性淡爲吾友，竹解心虛即我師。","何必悠悠人世上，勞心費目覓親知。"]', '["穿籬遶舍碧逶迤，十畮闲居半是池。","食飽窗间新睡後，脚轻林下独行时。","水能性淡爲吾友，竹解心虛即我師。","何必悠悠人世上，勞心費目覓親知。"]', '诗', 'shi', '', NULL, '池上竹下作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d35f833-1d08-4276-8524-11ac4828f19d', '閑出覓春戲贈諸郎官', '闲出覓春戲贈諸郎官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年來數出覓風光，亦不全閑亦不忙。","放鞚體安騎穩馬，隔袍身暖照晴陽。","迎春日日添詩思，送老時時放酒狂。","除却髭鬚白一色，其餘未伏少年郎。"]', '["年来數出覓风光，亦不全闲亦不忙。","放鞚體安騎穩马，隔袍身暖照晴陽。","迎春日日添诗思，送老时时放酒狂。","除却髭鬚白一色，其餘未伏少年郎。"]', '诗', 'shi', '', NULL, '閑出覓春戲贈諸郎官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01c67180-3672-49e4-b55d-f4ba7ef8e9c7', '別春爐', '別春爐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暖閣春初入，溫爐興稍闌。","晚風猶冷在，夜火且留看。","獨宿相依久，多情欲別難。","誰能共天語，長遣四時寒。"]', '["暖閣春初入，溫爐兴稍闌。","晚风猶冷在，夜火且留看。","独宿相依久，多情欲別难。","誰能共天語，长遣四时寒。"]', '诗', 'shi', '', NULL, '別春爐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5953a152-5427-4815-90ee-a218cb25f3e8', '汎小䑳二首 一', '汎小䑳二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水一塘，䑳一隻。","䑳頭漾漾知風起，䑳背蕭蕭聞雨滴。","醉臥船中欲醒時，忽疑身是江南客。"]', '["水一塘，䑳一隻。","䑳头漾漾知风起，䑳背蕭蕭闻雨滴。","醉臥船中欲醒时，忽疑身是江南客。"]', '诗', 'shi', '', NULL, '汎小䑳二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee808e4-bc44-4fe1-950a-a37a3717743c', '汎小䑳二首 二', '汎小䑳二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["船緩進，水平流。","一莖竹篙剔船尾，兩幅青幕覆船頭。","亞竹亂藤多照岸，如從鳳口向湖州。"]', '["船緩進，水平流。","一莖竹篙剔船尾，兩幅青幕覆船头。","亞竹亂藤多照岸，如從鳳口向湖州。"]', '诗', 'shi', '', NULL, '汎小䑳二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9641f8f-5104-4c98-99b4-05ea5cedd5c3', '夢行簡', '梦行簡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天氣妍和水色鮮，閑吟獨步小橋邊。","池塘草綠無佳句，虛臥春窗夢阿憐。"]', '["天氣妍和水色鲜，闲吟独步小橋邊。","池塘草綠無佳句，虛臥春窗梦阿怜。"]', '诗', 'shi', '', NULL, '夢行簡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e4c5f0e-591e-4f99-9bf4-957369f10590', '題新居呈王尹兼簡府中三掾', '題新居呈王尹兼簡府中三掾', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["弊宅須重葺，貧家乏羨財。","橋憑川守造，樹倩府僚栽。","朱板新猶濕，紅英暖漸開。","仍期更攜酒，倚檻看花來。"]', '["弊宅須重葺，貧家乏羨財。","橋憑川守造，樹倩府僚栽。","朱板新猶濕，紅英暖漸开。","仍期更携酒，倚檻看花来。"]', '诗', 'shi', '', NULL, '題新居呈王尹兼簡府中三掾 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00221140-783c-414f-bfa8-0fe25d7ea4d7', '雲和', '云和', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["非琴非瑟亦非箏，撥柱推弦調未成。","欲散白頭千萬恨，只消紅袖兩三聲。"]', '["非琴非瑟亦非箏，撥柱推弦調未成。","欲散白头千万恨，只消紅袖兩三声。"]', '诗', 'shi', '', NULL, '雲和 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a03b20-7cbc-4482-8acf-1d9c2e26fbdc', '春老', '春老', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲隨年少強遊春，自覺風光不屬身。","歌舞屏風花障上，幾時曾畫白頭人。"]', '["欲隨年少強游春，自覺风光不屬身。","歌舞屏风花障上，幾时曾畫白头人。"]', '诗', 'shi', '', NULL, '春老 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('071751cb-48a7-4cd7-8442-34f361ce87ee', '春雪過皇甫家', '春雪過皇甫家', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚來籃轝雪中回，喜遇君家門正開。","唯要主人青眼待，琴詩談笑自將來。"]', '["晚来籃轝雪中回，喜遇君家门正开。","唯要主人青眼待，琴诗談笑自將来。"]', '诗', 'shi', '', NULL, '春雪過皇甫家 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1216ebcc-fff9-40b6-b320-d74b06566f03', '崔侍御以孩子三日示其所生詩見示因以二絕句和之 一', '崔侍御以孩子三日示其所生诗见示因以二絕句和之 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洞房門上挂桑弧，香水盆中浴鳳雛。","還似初生三日魄，嫦娥滿月即成珠。"]', '["洞房门上挂桑弧，香水盆中浴鳳雛。","還似初生三日魄，嫦娥满月即成珠。"]', '诗', 'shi', '', NULL, '崔侍御以孩子三日示其所生詩見示因以二絕句和之 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a88e5f-4bcb-4835-9258-a07e4c39aa99', '崔侍御以孩子三日示其所生詩見示因以二絕句和之 二', '崔侍御以孩子三日示其所生诗见示因以二絕句和之 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["愛惜肯將同寶玉，喜歡應勝得王侯。","弄璋詩句多才思，愁殺無兒老鄧攸。"]', '["愛惜肯將同寶玉，喜歡應勝得王侯。","弄璋诗句多才思，愁殺無兒老鄧攸。"]', '诗', 'shi', '', NULL, '崔侍御以孩子三日示其所生詩見示因以二絕句和之 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91af54b-0586-42a0-a276-12dbd3acb52c', '與皇甫庶子同遊城東', '與皇甫庶子同游城东', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑遊何必多徒侶，相勸時時舉一桮。","博望苑中無職役，建春門外足池臺。","綠油剪葉蒲新長，紅蠟黏枝杏欲開。","白馬朱衣兩宮相，可憐天氣出城來。"]', '["闲游何必多徒侶，相勸时时舉一桮。","博望苑中無職役，建春门外足池台。","綠油剪葉蒲新长，紅蠟黏枝杏欲开。","白马朱衣兩宮相，可怜天氣出城来。"]', '诗', 'shi', '', NULL, '與皇甫庶子同遊城東 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0151f171-df14-42d0-8ff5-25219c2adcd1', '洛城東花下作', '洛城东花下作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["記得舊詩章，花多數洛陽及逢枝似雪，已是鬢成霜。","向後光陰促，從前事意忙。","無因重年少，何計駐時芳。","欲送愁離面，須傾酒入腸。","白頭無藉在，醉倒亦何妨。"]', '["記得旧诗章，花多數洛陽及逢枝似雪，已是鬢成霜。","向後光陰促，從前事意忙。","無因重年少，何計駐时芳。","欲送愁離面，須傾酒入腸。","白头無藉在，醉倒亦何妨。"]', '诗', 'shi', '', NULL, '洛城東花下作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9195b7c8-9bb4-4325-aee1-c42ecfd1f4b3', '晚春寄微之幷崔湖州', '晚春寄微之幷崔湖州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛陽陌上少交親，履道城邊欲暮春。","崔在吳興元在越，出門騎馬覓何人。"]', '["洛陽陌上少交親，履道城邊欲暮春。","崔在吳兴元在越，出门騎马覓何人。"]', '诗', 'shi', '', NULL, '晚春寄微之幷崔湖州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('032c5192-8eae-48c1-bce6-b9537e183dd8', '城東閑行因題尉遲司業水閣', '城东闲行因題尉遲司業水閣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑遶洛陽城，無人知姓名。","病乘籃轝出，老著茜衫行。","處處花相引，時時酒一傾。","借君溪閣上，醉詠兩三聲。"]', '["闲遶洛陽城，無人知姓名。","病乘籃轝出，老著茜衫行。","处处花相引，时时酒一傾。","借君溪閣上，醉詠兩三声。"]', '诗', 'shi', '', NULL, '城東閑行因題尉遲司業水閣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d22d297a-bf8f-4b9c-963e-4e08631ac4cb', '寄皇甫七', '寄皇甫七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["孟夏愛吾廬，陶潛語不虛。","花樽飄落酒，風案展開書。","鄰女偷新果，家僮漉小魚。","不知皇甫七，池上興何如。"]', '["孟夏愛吾廬，陶潛語不虛。","花樽飄落酒，风案展开书。","鄰女偷新果，家僮漉小鱼。","不知皇甫七，池上兴何如。"]', '诗', 'shi', '', NULL, '寄皇甫七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43330188-a882-4514-a8f3-7bd9bf00d8af', '訪皇甫七', '訪皇甫七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上馬行數里，逢花傾一桮。","更無停泊處，還是覓君來。"]', '["上马行數里，逢花傾一桮。","更無停泊处，還是覓君来。"]', '诗', 'shi', '', NULL, '訪皇甫七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5fc3052-99dd-403c-8be2-2fa025683f7b', '除蘇州刺史別洛城東花', '除蘇州刺史別洛城东花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亂雪千花落，新絲兩鬢生。","老除吳郡守，春別洛陽城。","江上今重去，城東更一行。","別花何用伴，勸酒有殘鶯。"]', '["亂雪千花落，新絲兩鬢生。","老除吳郡守，春別洛陽城。","江上今重去，城东更一行。","別花何用伴，勸酒有殘鶯。"]', '诗', 'shi', '', NULL, '除蘇州刺史別洛城東花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ffa5719-32e9-4966-bf36-3e369ddb7437', '奉和汴州令狐令公二十二韻', '奉和汴州令狐令公二十二韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["客有東征者，夷門一落帆。","二年方得到，五日未爲淹。","在浚旌重葺，遊梁館更添。","心因好善樂，貌爲禮賢謙。","俗阜知敦勸，民安見察廉。","仁風扇道路，陰雨膏閭閻。","文律操將柄，兵機釣得鈐。","碧幢油葉葉，紅斾火襜襜。","景象春加麗，威容曉助嚴。","槍森赤豹尾，纛吒黑龍髯。","門靜塵初歛，城昏日半銜。","選幽開後院，占勝坐前簷。","平展絲頭毯，高褰錦額簾。","雷搥柘枝鼓，雪擺胡騰衫。","髮滑歌釵墜，妝光舞汗霑。","回燈花簇簇，過酒玉纖纖。","饌盛盤心殢，醅濃盞底黏。","陸珍熊掌爛，海味蟹螯鹹。","福履千夫祝，形儀四座瞻。","羊公長在峴，傅說莫歸巖。","眷愛人人遍，風情事事兼。","猶嫌客不醉，同賦夜厭厭。"]', '["客有东征者，夷门一落帆。","二年方得到，五日未爲淹。","在浚旌重葺，游梁館更添。","心因好善乐，貌爲禮賢謙。","俗阜知敦勸，民安见察廉。","仁风扇道路，陰雨膏閭閻。","文律操將柄，兵機釣得鈐。","碧幢油葉葉，紅斾火襜襜。","景象春加丽，威容晓助嚴。","槍森赤豹尾，纛吒黑龙髯。","门静塵初歛，城昏日半銜。","選幽开後院，占勝坐前簷。","平展絲头毯，高褰錦額簾。","雷搥柘枝鼓，雪擺胡腾衫。","髮滑歌釵墜，妝光舞汗霑。","回灯花簇簇，過酒玉纖纖。","饌盛盤心殢，醅濃盞底黏。","陸珍熊掌爛，海味蟹螯鹹。","福履千夫祝，形儀四座瞻。","羊公长在峴，傅说莫归巖。","眷愛人人遍，风情事事兼。","猶嫌客不醉，同賦夜厭厭。"]', '诗', 'shi', '', NULL, '奉和汴州令狐令公二十二韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('284d7cd6-4607-4b81-9dda-746f2cd13c90', '船夜援琴', '船夜援琴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鳥棲魚不動，月照夜江深。","身外都無事，舟中只有琴。","七弦爲益友，兩耳是知音。","心靜即聲淡，其間無古今。"]', '["鸟棲鱼不动，月照夜江深。","身外都無事，舟中只有琴。","七弦爲益友，兩耳是知音。","心静即声淡，其间無古今。"]', '诗', 'shi', '', NULL, '船夜援琴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50646d2c-4782-421f-9a71-cd8d9c0e38b6', '荅劉和州禹錫', '荅劉和州禹錫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["換印雖頻命未通，歷陽湖上又秋風。","不教才展休明代，爲罰詩爭造化功。","我亦思歸田舍下，君應厭臥郡齋中。","好相收拾爲閑伴，年齒官班約略同。"]', '["換印雖頻命未通，歷陽湖上又秋风。","不教才展休明代，爲罰诗爭造化功。","我亦思归田舍下，君應厭臥郡斋中。","好相收拾爲闲伴，年齒官班約略同。"]', '诗', 'shi', '', NULL, '荅劉和州禹錫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d391dff9-a618-46b2-9e6c-84f942a87305', '渡淮', '渡淮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淮水東南闊，無風渡亦難。","孤煙生乍直，遠樹望多圓。","春浪櫂聲急，夕陽帆影殘。","清流宜映月，今夜重吟看。"]', '["淮水东南闊，無风渡亦难。","孤煙生乍直，远樹望多圓。","春浪櫂声急，夕陽帆影殘。","清流宜映月，今夜重吟看。"]', '诗', 'shi', '', NULL, '渡淮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('729c0c57-ccff-4d7d-8a32-92188244f8de', '赴蘇州至常州荅賈舍人', '赴蘇州至常州荅賈舍人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["杭城隔歲轉蘇臺，還擁前時五馬回。","厭見簿書先眼合，喜逢桮酒暫眉開。","未酬恩寵年空去，欲立功名命不來。","一別承明三領郡，甘從人道是粗才。"]', '["杭城隔歲轉蘇台，還擁前时五马回。","厭见簿书先眼合，喜逢桮酒暫眉开。","未酬恩寵年空去，欲立功名命不来。","一別承明三領郡，甘從人道是粗才。"]', '诗', 'shi', '', NULL, '赴蘇州至常州荅賈舍人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95a119ed-dbc2-4fd8-8be8-344f7bfc99d9', '去歲罷杭州今春領吳郡慙無善政聊寫鄙懷兼寄三相公', '去歲罷杭州今春領吳郡慙無善政聊寫鄙懷兼寄三相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爲問三丞相，如何秉國鈞。","那將最劇郡，付與苦慵人。","豈有吟詩客，堪爲持節臣。","不才空飽暖，無惠及飢貧。","昨臥南城月，今行北境春。","鉛刀磨欲盡，銀印換何頻。","杭老遮車轍，吳童掃路塵。","虛迎復虛送，慙見兩州民。"]', '["爲问三丞相，如何秉国鈞。","那將最劇郡，付與苦慵人。","豈有吟诗客，堪爲持節臣。","不才空飽暖，無惠及飢貧。","昨臥南城月，今行北境春。","鉛刀磨欲尽，銀印換何頻。","杭老遮车轍，吳童掃路塵。","虛迎复虛送，慙见兩州民。"]', '诗', 'shi', '', NULL, '去歲罷杭州今春領吳郡慙無善政聊寫鄙懷兼寄三相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70802095-82bb-44d5-812d-04ce5a10458b', '宣武令狐相公以詩寄贈傳播吳中聊奉短草用申酬謝', '宣武令狐相公以诗寄贈傳播吳中聊奉短草用申酬謝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新詩傳詠忽紛紛，楚老吳娃耳徧聞。","盡解呼爲好才子，不知官是上將軍。","辭人命薄多無位，戰將功高少有文。","謝朓篇章韓信鉞，一生雙得不如君。"]', '["新诗傳詠忽紛紛，楚老吳娃耳徧闻。","尽解呼爲好才子，不知官是上將軍。","辞人命薄多無位，戰將功高少有文。","謝朓篇章韓信鉞，一生雙得不如君。"]', '诗', 'shi', '', NULL, '宣武令狐相公以詩寄贈傳播吳中聊奉短草用申酬謝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74054002-6168-408d-a90d-5ab76cd5e7eb', '自詠', '自詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["形容瘦薄詩情苦，豈是人間有相人。","只合一生眠白屋，何因三度擁朱輪。","金章未佩雖非貴，銀榼常攜亦不貧。","唯是無兒頭早白，被天磨折恰平均。"]', '["形容瘦薄诗情苦，豈是人间有相人。","只合一生眠白屋，何因三度擁朱輪。","金章未佩雖非貴，銀榼常携亦不貧。","唯是無兒头早白，被天磨折恰平均。"]', '诗', 'shi', '', NULL, '自詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38579de-9748-4f5f-8459-9bc506ac35c1', '吟前篇因寄微之', '吟前篇因寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君顏貴茂不清羸，君句雄華不苦悲。","何事遣君還似我，髭鬚早白亦無兒。"]', '["君顏貴茂不清羸，君句雄华不苦悲。","何事遣君還似我，髭鬚早白亦無兒。"]', '诗', 'shi', '', NULL, '吟前篇因寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c81f8a-f36d-4d1d-bbf1-837cb43f8865', '紫薇花', '紫薇花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫薇花對紫微翁，名目雖同貌不同。","獨占芳菲當夏景，不將顏色託春風。","潯陽官舍雙高樹，興善僧庭一大叢。","何似蘇州安置處，花堂欄下月明中。"]', '["紫薇花对紫微翁，名目雖同貌不同。","独占芳菲當夏景，不將顏色託春风。","潯陽官舍雙高樹，兴善僧庭一大叢。","何似蘇州安置处，花堂欄下月明中。"]', '诗', 'shi', '', NULL, '紫薇花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d3e2fbc-94aa-44b7-9d01-84506da845ce', '自到郡齋僅經旬日方專公務未及宴遊偷閑走筆題二十四韻兼寄常州賈舍人湖州崔郎中仍呈吳中諸客', '自到郡斋僅經旬日方專公務未及宴游偷闲走笔題二十四韻兼寄常州賈舍人湖州崔郎中仍呈吳中諸客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["渭北離鄉客，江南守土臣。","涉途初改月，入境已經旬。","甲郡標天下，環封極海濱。","版圖十萬戶，兵籍五千人。","自顧才能少，何堪寵命頻。","冒榮慙印綬，虛獎負絲綸。","候病須通脈，防流要塞津。","救煩無若靜，補拙莫如勤。","削使科條簡，攤令賦役均。","以茲爲報効，安敢不躬親。","襦袴提於手，韋弦佩在紳。","敢辭稱俗吏，且願活疲民。","常未徵黃霸，湖猶借寇恂。","媿無鐺脚政，徒忝犬牙鄰。","制誥誇黃絹，詩篇占白蘋。","銅符拋不得，瓊樹見無因。","警寐鐘傳夜，催衙鼓報晨。","唯知對胥吏，未暇接親賓。","色變雲迎夏，聲殘鳥過春。","麥風非逐扇，梅[雨]異隨輪。","武寺山如故，王樓月自新。","池塘閑長草，絲竹廢生塵。","暑遣燒神酎，晴教曬舞茵。","待還公事了，亦擬樂吾身。"]', '["渭北離乡客，江南守土臣。","涉途初改月，入境已經旬。","甲郡標天下，环封極海濱。","版圖十万戶，兵籍五千人。","自顧才能少，何堪寵命頻。","冒榮慙印綬，虛獎負絲綸。","候病須通脈，防流要塞津。","救煩無若静，補拙莫如勤。","削使科條簡，攤令賦役均。","以茲爲報効，安敢不躬親。","襦袴提於手，韋弦佩在紳。","敢辞稱俗吏，且願活疲民。","常未徵黄霸，湖猶借寇恂。","媿無鐺脚政，徒忝犬牙鄰。","制誥誇黄絹，诗篇占白蘋。","銅符拋不得，瓊樹见無因。","警寐鐘傳夜，催衙鼓報晨。","唯知对胥吏，未暇接親賓。","色变云迎夏，声殘鸟過春。","麦风非逐扇，梅[雨]異隨輪。","武寺山如故，王楼月自新。","池塘闲长草，絲竹廢生塵。","暑遣燒神酎，晴教曬舞茵。","待還公事了，亦擬乐吾身。"]', '诗', 'shi', '', NULL, '自到郡齋僅經旬日方專公務未及宴遊偷閑走筆題二十四韻兼寄常州賈舍人湖州崔郎中仍呈吳中諸客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffdf7da6-4507-4659-a2ed-8a00917b4bd3', '題籠鶴', '題籠鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["經旬不飲酒，踰月未聞歌。","豈是風情少，其如塵事多。","虎丘慙客問，娃館妬人過。","莫笑籠中鶴，相看去幾何。"]', '["經旬不饮酒，踰月未闻歌。","豈是风情少，其如塵事多。","虎丘慙客问，娃館妬人過。","莫笑籠中鹤，相看去幾何。"]', '诗', 'shi', '', NULL, '題籠鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27958b7-f862-4304-ac02-3b5eaabe6833', '荅客問杭州', '荅客问杭州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爲我踟躕停酒盞，與君約略說杭州。","山名天竺堆青黛，湖號錢唐瀉綠油。","大屋簷多裝鴈齒，小航船亦畫龍頭。","所嗟水路無三百，官繫何因得再遊。"]', '["爲我踟躕停酒盞，與君約略说杭州。","山名天竺堆青黛，湖號錢唐瀉綠油。","大屋簷多裝鴈齒，小航船亦畫龙头。","所嗟水路無三百，官繫何因得再游。"]', '诗', 'shi', '', NULL, '荅客問杭州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11775c2d-6759-4bc4-bb18-2aafe019206a', '登閶門閑望', '登閶门闲望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閶門四望鬱蒼蒼，始覺州雄土俗強。","十萬夫家供課稅，五千子弟守封疆。","闔閭城碧鋪秋草，烏鵲橋紅帶夕陽。","處處樓前飄管吹，家家門外泊舟航。","雲埋虎寺山藏色，月耀娃宮水放光。","曾賞錢唐嫌茂苑，今來未敢苦誇張。"]', '["閶门四望鬱蒼蒼，始覺州雄土俗強。","十万夫家供課稅，五千子弟守封疆。","闔閭城碧鋪秋草，烏鵲橋紅带夕陽。","处处楼前飄管吹，家家门外泊舟航。","云埋虎寺山藏色，月耀娃宮水放光。","曾賞錢唐嫌茂苑，今来未敢苦誇張。"]', '诗', 'shi', '', NULL, '登閶門閑望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a311dc-e167-4017-b8bb-0b3599f60a59', '代諸妓贈送周判官', '代諸妓贈送周判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["妓筵今夜別姑蘇，客櫂明朝向鏡湖。","莫汎扁舟尋范蠡，且隨五馬覓羅敷。","蘭亭月破能迴否，娃館秋涼却到無。","好與使君爲老伴，歸來休染白髭鬚。"]', '["妓筵今夜別姑蘇，客櫂明朝向镜湖。","莫汎扁舟尋范蠡，且隨五马覓羅敷。","蘭亭月破能迴否，娃館秋涼却到無。","好與使君爲老伴，归来休染白髭鬚。"]', '诗', 'shi', '', NULL, '代諸妓贈送周判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1d02b56-b877-4295-a10c-6fc0cb49e2f1', '秋寄微之十二韻', '秋寄微之十二韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["娃館松江北，稽城浙水東。","屈君爲長吏，伴我作衰翁。","旌斾知非遠，煙雲望不通。","忙多對酒榼，興少閱詩筒。","淡白秋來日，疎涼雨後風。","餘霞數片綺，新月一張弓。","影滿衰桐樹，香凋晚蕙叢。","飢啼春穀鳥，寒怨絡絲蟲。","覽鏡頭雖白，聽歌耳未聾。","老愁從此遣，醉笑與誰同。","清旦方堆案，黃昏始退公。","可憐朝暮景，銷在兩衙中。"]', '["娃館松江北，稽城浙水东。","屈君爲长吏，伴我作衰翁。","旌斾知非远，煙云望不通。","忙多对酒榼，兴少閱诗筒。","淡白秋来日，疎涼雨後风。","餘霞數片綺，新月一張弓。","影满衰桐樹，香凋晚蕙叢。","飢啼春穀鸟，寒怨絡絲蟲。","覽镜头雖白，听歌耳未聾。","老愁從此遣，醉笑與誰同。","清旦方堆案，黄昏始退公。","可怜朝暮景，銷在兩衙中。"]', '诗', 'shi', '', NULL, '秋寄微之十二韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67f9c69a-6585-4948-b9a9-310503ce835e', '池上早秋', '池上早秋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["荷芰綠參差，新秋水滿池。","早涼生北檻，殘照下東籬。","露飽蟬聲嬾，風乾柳意衰。","過潘二十歲，何必更愁悲。"]', '["荷芰綠參差，新秋水满池。","早涼生北檻，殘照下东籬。","露飽蟬声嬾，风乾柳意衰。","過潘二十歲，何必更愁悲。"]', '诗', 'shi', '', NULL, '池上早秋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c00ab70-1d79-4249-a760-15a7c97e7485', '郡西亭偶詠', '郡西亭偶詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["常愛西亭面北林，公私塵事不能侵。","共閑作伴無如鶴，與老相宜只有琴。","莫遣是非分作界，須教吏隱合爲心。","可憐此道人皆見，但要修行功用深。"]', '["常愛西亭面北林，公私塵事不能侵。","共闲作伴無如鹤，與老相宜只有琴。","莫遣是非分作界，須教吏隐合爲心。","可怜此道人皆见，但要修行功用深。"]', '诗', 'shi', '', NULL, '郡西亭偶詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3248d69e-f5d2-4caf-ab2b-ee353ce68191', '故衫', '故衫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["闇淡緋衫稱老身，半披半曳出朱門。","袖中吳郡新詩本，襟上杭州舊酒痕。","殘色過梅看向盡，故香因洗嗅猶存。","曾經爛熳三年著，欲棄空箱似少恩。"]', '["闇淡緋衫稱老身，半披半曳出朱门。","袖中吳郡新诗本，襟上杭州旧酒痕。","殘色過梅看向尽，故香因洗嗅猶存。","曾經爛熳三年著，欲棄空箱似少恩。"]', '诗', 'shi', '', NULL, '故衫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed06eda-8098-4e73-9a80-0e6efd931429', '郡中夜聽李山人彈三樂', '郡中夜听李山人彈三乐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風琴秋拂匣，月戶夜開關。","榮啓先生樂，姑蘇太守閑。","傳聲千古後，得意一時間。","却怪鍾期耳，唯聽水與山。"]', '["风琴秋拂匣，月戶夜开关。","榮啓先生乐，姑蘇太守闲。","傳声千古後，得意一时间。","却怪鍾期耳，唯听水與山。"]', '诗', 'shi', '', NULL, '郡中夜聽李山人彈三樂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('090fe452-57a4-42dc-beb0-81174c375d84', '東城桂三首 一', '东城桂三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["子墮本從天竺寺，根盤今在闔閭城。","當時應逐南風落，落向人間取次生。"]', '["子墮本從天竺寺，根盤今在闔閭城。","當时應逐南风落，落向人间取次生。"]', '诗', 'shi', '', NULL, '東城桂三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cc52761-d00f-4944-b66b-c3c8cee78d43', '東城桂三首 二', '东城桂三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜雪壓多雖不死，荆榛長疾欲相埋。","長憂落在樵人手，賣作蘇州一束柴。"]', '["霜雪壓多雖不死，荆榛长疾欲相埋。","长憂落在樵人手，賣作蘇州一束柴。"]', '诗', 'shi', '', NULL, '東城桂三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1a7e39-a2a2-4990-9945-03e188054f51', '東城桂三首 三', '东城桂三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遙知天上桂花孤，試問嫦娥更要無。"]', '["遙知天上桂花孤，試问嫦娥更要無。"]', '诗', 'shi', '', NULL, '東城桂三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cea7180-20db-4b66-a509-95e6b77c01ac', '聞行簡恩賜章服喜成長句寄之', '闻行簡恩賜章服喜成长句寄之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾年五十加朝散，爾亦今年賜服章。","齒髮恰同知命歲，官銜俱是客曹郎。","榮傳錦帳花聯萼，彩動綾袍鴈趂行。","大抵著緋宜老大，莫嫌秋鬢數莖霜。"]', '["吾年五十加朝散，爾亦今年賜服章。","齒髮恰同知命歲，官銜俱是客曹郎。","榮傳錦帳花聯萼，彩动綾袍鴈趂行。","大抵著緋宜老大，莫嫌秋鬢數莖霜。"]', '诗', 'shi', '', NULL, '聞行簡恩賜章服喜成長句寄之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8952d8d5-41ea-4907-9c7e-7d52a1df2fc4', '喚笙歌', '喚笙歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["露墜萎花槿，風吹敗葉荷。","老心歡樂少，秋眼感傷多。","芳歲今如此，衰翁可奈何。","猶應不如醉，試遣喚笙歌。"]', '["露墜萎花槿，风吹敗葉荷。","老心歡乐少，秋眼感傷多。","芳歲今如此，衰翁可奈何。","猶應不如醉，試遣喚笙歌。"]', '诗', 'shi', '', NULL, '喚笙歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20c1c027-c94e-4373-a9f5-29c19eaae096', '對酒吟', '对酒吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一拋學士筆，三佩使君符。","未換銀青綬，唯添雪白鬚。","公門衙退掩，妓席客來鋪。","履舃從相近，謳吟任所須。","金銜嘶五馬，鈿帶舞雙姝。","不得當年有，猶勝到老無。","合聲歌漢月，齊手拍吳歈。","今夜還先醉，應煩紅袖扶。"]', '["一拋学士笔，三佩使君符。","未換銀青綬，唯添雪白鬚。","公门衙退掩，妓席客来鋪。","履舃從相近，謳吟任所須。","金銜嘶五马，鈿带舞雙姝。","不得當年有，猶勝到老無。","合声歌漢月，齊手拍吳歈。","今夜還先醉，應煩紅袖扶。"]', '诗', 'shi', '', NULL, '對酒吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a919f43f-d7b1-40b9-8c7d-603c8d7a1abc', '偶飲', '偶饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三盞醺醺四體融，妓亭簷下夕陽中。","千聲方響敲相續，一曲[雲]和戛未終。","今日心情如往日，秋風氣味似春風。","唯憎小吏樽前報，道去衙時水五筒。"]', '["三盞醺醺四體融，妓亭簷下夕陽中。","千声方响敲相續，一曲[云]和戛未終。","今日心情如往日，秋风氣味似春风。","唯憎小吏樽前報，道去衙时水五筒。"]', '诗', 'shi', '', NULL, '偶飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d4987f0-f02c-47aa-a37f-2ffb738367bf', '早發赴洞庭舟中作', '早發赴洞庭舟中作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閶門曙色欲蒼蒼，星月高低宿水光。","櫂舉影搖燈燭動，舟移聲拽管弦長。","漸看海樹紅生日，遙見包山白帶霜。","出郭已行十五里，唯消一曲慢霓裳。"]', '["閶门曙色欲蒼蒼，星月高低宿水光。","櫂舉影搖灯燭动，舟移声拽管弦长。","漸看海樹紅生日，遙见包山白带霜。","出郭已行十五里，唯消一曲慢霓裳。"]', '诗', 'shi', '', NULL, '早發赴洞庭舟中作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ac80e7-24c3-490c-9321-f8957d2d62ff', '宿湖中', '宿湖中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水天向晚碧沉沉，樹影霞光重疊深。","浸月冷波千頃練，苞霜新橘萬株金。","幸無案牘何妨醉，縱有笙歌不廢吟。","十隻畫船何處宿，洞庭山腳太湖心。"]', '["水天向晚碧沉沉，樹影霞光重叠深。","浸月冷波千頃練，苞霜新橘万株金。","幸無案牘何妨醉，縱有笙歌不廢吟。","十隻畫船何处宿，洞庭山腳太湖心。"]', '诗', 'shi', '', NULL, '宿湖中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a52e1c-6a5b-4386-ace5-6bab56e0974f', '揀貢橘書情', '揀貢橘书情', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洞庭貢橘揀宜精，太守勤王請自行。","珠顆形容隨日長，瓊漿氣味得霜成。","登山敢惜駑駘力，望闕難伸螻蟻情。","疎賤無由親跪獻，願憑朱實表丹誠。"]', '["洞庭貢橘揀宜精，太守勤王請自行。","珠顆形容隨日长，瓊漿氣味得霜成。","登山敢惜駑駘力，望闕难伸螻蟻情。","疎賤無由親跪獻，願憑朱實表丹誠。"]', '诗', 'shi', '', NULL, '揀貢橘書情 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42bdfb3b-d1cf-477e-b3fe-24b4dbc4bb00', '夜泛陽塢入明月灣即事寄崔湖州', '夜泛陽塢入明月灣即事寄崔湖州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湖山處處好淹留，最愛東灣北塢頭。","掩映橘林千點火，泓澄潭水一盆油。","龍頭畫舸銜明月，鵲脚紅旗蘸碧流。","爲報茶山崔太守，與君各是一家遊。"]', '["湖山处处好淹留，最愛东灣北塢头。","掩映橘林千点火，泓澄潭水一盆油。","龙头畫舸銜明月，鵲脚紅旗蘸碧流。","爲報茶山崔太守，與君各是一家游。"]', '诗', 'shi', '', NULL, '夜泛陽塢入明月灣即事寄崔湖州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcda8158-e93f-4818-8bb9-decef0430517', '泛太湖書事寄微之', '泛太湖书事寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙渚雲帆處處通，飄然舟似入虛空。","玉桮淺酌巡初匝，金管徐吹曲未終。","黃夾纈林寒有葉，碧琉璃水淨無風。","避旗飛鷺翩翻白，驚鼓跳魚撥剌紅。","澗雪壓多松偃蹇，巖泉滴久石玲瓏。","書爲故事留湖上，吟作新詩寄浙東。","軍府威容從道盛，江山氣色定知同。","報君一事君應羨，五宿澄波皓月中。"]', '["煙渚云帆处处通，飄然舟似入虛空。","玉桮淺酌巡初匝，金管徐吹曲未終。","黄夾纈林寒有葉，碧琉璃水淨無风。","避旗飞鷺翩翻白，驚鼓跳鱼撥剌紅。","澗雪壓多松偃蹇，巖泉滴久石玲瓏。","书爲故事留湖上，吟作新诗寄浙东。","軍府威容從道盛，江山氣色定知同。","報君一事君應羨，五宿澄波皓月中。"]', '诗', 'shi', '', NULL, '泛太湖書事寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d06421-854b-4335-a708-249bc7795b29', '題新館', '題新館', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曾爲白社羈遊子，今作朱門醉飽身。","十萬戶州尤覺貴，二千石祿敢言貧。","重裘每念單衣士，兼味嘗思旅食人。","新館寒來多少客，欲回歌酒暖風塵。"]', '["曾爲白社羈游子，今作朱门醉飽身。","十万戶州尤覺貴，二千石祿敢言貧。","重裘每念單衣士，兼味嘗思旅食人。","新館寒来多少客，欲回歌酒暖风塵。"]', '诗', 'shi', '', NULL, '題新館 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9270b2e-c8cf-4ae9-8b79-58bf7fac4fbb', '西樓喜雪命宴', '西楼喜雪命宴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宿雲黃慘澹，曉雪白飄颻。","散麪遮槐市，堆花壓柳橋。","四郊鋪縞素，萬室甃瓊瑤。","銀榼攜桑落，金爐上麗譙。","光迎舞妓動，寒近醉人銷。","歌樂雖盈耳，慙無五袴謠。"]', '["宿云黄慘澹，晓雪白飄颻。","散麪遮槐市，堆花壓柳橋。","四郊鋪縞素，万室甃瓊瑤。","銀榼携桑落，金爐上丽譙。","光迎舞妓动，寒近醉人銷。","歌乐雖盈耳，慙無五袴謠。"]', '诗', 'shi', '', NULL, '西樓喜雪命宴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48f5b2c1-37be-4114-9f50-6001f4abd841', '新栽梅', '新栽梅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池邊新種七株梅，欲到花時點檢來。","莫怕長洲桃李妬，今年好爲使君開。"]', '["池邊新種七株梅，欲到花时点檢来。","莫怕长洲桃李妬，今年好爲使君开。"]', '诗', 'shi', '', NULL, '新栽梅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad771777-63dd-41fc-b1c2-da11e8cf64cf', '酬劉和州戲贈', '酬劉和州戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["錢唐山水接蘇臺，兩地褰帷媿不才。","政事素無爭學得，風情舊有且將來。","雙蛾解珮啼相送，五馬鳴珂笑却回。","不似劉郎無景行，長拋春恨在天台。"]', '["錢唐山水接蘇台，兩地褰帷媿不才。","政事素無爭学得，风情旧有且將来。","雙蛾解珮啼相送，五马鳴珂笑却回。","不似劉郎無景行，长拋春恨在天台。"]', '诗', 'shi', '', NULL, '酬劉和州戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d627be42-d1d7-4c7e-b46b-dbf5fccd8cb2', '戲和賈常州醉中二絕句 一', '戲和賈常州醉中二絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞道毗陵詩酒興，近來積漸學姑蘇。","罨頭新令從偷去，刮骨清吟得似無。"]', '["闻道毗陵诗酒兴，近来積漸学姑蘇。","罨头新令從偷去，刮骨清吟得似無。"]', '诗', 'shi', '', NULL, '戲和賈常州醉中二絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d43b327-3341-43ac-808b-bd45596562c6', '戲和賈常州醉中二絕句 二', '戲和賈常州醉中二絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["越調管吹留客曲，吳吟詩送暖寒杯。","娃宮無限風流事，好遣孫心暫學來。"]', '["越調管吹留客曲，吳吟诗送暖寒杯。","娃宮無限风流事，好遣孫心暫学来。"]', '诗', 'shi', '', NULL, '戲和賈常州醉中二絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a6cfb43-177f-41eb-bd43-555f89544243', '歲暮寄微之三首 一', '歲暮寄微之三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["微之別久能無歎，知退書稀豈免愁。","甲子百年過半後，光陰一歲欲終頭。","池水曉合膠船底，樓雪晴銷露瓦溝。","自覺歡情隨日減，蘇州心不及杭州。"]', '["微之別久能無歎，知退书稀豈免愁。","甲子百年過半後，光陰一歲欲終头。","池水晓合膠船底，楼雪晴銷露瓦溝。","自覺歡情隨日減，蘇州心不及杭州。"]', '诗', 'shi', '', NULL, '歲暮寄微之三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64ac8751-6649-472d-ae40-374d236ed20a', '歲暮寄微之三首 二', '歲暮寄微之三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["榮進雖頻退亦頻，與君才命不調勻。","若不九重中掌事，即須千里外拋身。","紫垣南北廳曾對，滄海東西郡又鄰。","唯欠結廬嵩洛下，一時歸去作閑人。"]', '["榮進雖頻退亦頻，與君才命不調勻。","若不九重中掌事，即須千里外拋身。","紫垣南北廳曾对，滄海东西郡又鄰。","唯欠結廬嵩洛下，一时归去作闲人。"]', '诗', 'shi', '', NULL, '歲暮寄微之三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('220fa681-7e0f-44ed-a333-246ba98d1e48', '歲暮寄微之三首 三', '歲暮寄微之三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白頭歲暮苦相思，除却悲吟無可爲。","枕上從妨一夜睡，燈前讀盡十年詩。","龍鍾校正騎驢日，顦顇通江司馬時。","若並如今是全活，紆朱拖紫且開眉。"]', '["白头歲暮苦相思，除却悲吟無可爲。","枕上從妨一夜睡，灯前读尽十年诗。","龙鍾校正騎驢日，顦顇通江司马时。","若並如今是全活，紆朱拖紫且开眉。"]', '诗', 'shi', '', NULL, '歲暮寄微之三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bcf668e-711b-4008-b658-bae89c1920db', '歲日家宴戲示弟姪等兼呈張侍御二十八丈殷判官二十三兄', '歲日家宴戲示弟姪等兼呈張侍御二十八丈殷判官二十三兄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["弟妹妻孥小姪甥，嬌癡弄我助歡情。","歲盞後推藍尾酒，春盤先勸膠牙餳。","形骸潦到雖堪歎，骨肉團圓亦可榮。","猶有誇張少年處，笑呼張丈喚殷兄。"]', '["弟妹妻孥小姪甥，嬌癡弄我助歡情。","歲盞後推藍尾酒，春盤先勸膠牙餳。","形骸潦到雖堪歎，骨肉團圓亦可榮。","猶有誇張少年处，笑呼張丈喚殷兄。"]', '诗', 'shi', '', NULL, '歲日家宴戲示弟姪等兼呈張侍御二十八丈殷判官二十三兄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3705c324-e7be-4cb2-83e0-142d2cb0f321', '正月三日閑行', '正月三日闲行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃鸝巷口鶯欲語，烏鵲河頭冰欲銷。","綠浪東西南北水，紅欄三百九十橋。","鴛鴦蕩漾雙雙翅，楊柳交加萬萬條。","借問春風來早晚，只從前日到今朝。"]', '["黄鸝巷口鶯欲語，烏鵲河头冰欲銷。","綠浪东西南北水，紅欄三百九十橋。","鴛鴦蕩漾雙雙翅，楊柳交加万万條。","借问春风来早晚，只從前日到今朝。"]', '诗', 'shi', '', NULL, '正月三日閑行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6a56c52-ba9c-4b24-a351-2cf288e865fb', '夜歸', '夜归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["逐勝移朝宴，留歡放晚衙。","賓寮多謝客，騎從半吳娃。","到處銷春景，歸時及月華。","城陰一道直，燭焰兩行斜。","東吹先催柳，南霜不殺花。","臯橋夜沽酒，燈火是誰家。"]', '["逐勝移朝宴，留歡放晚衙。","賓寮多謝客，騎從半吳娃。","到处銷春景，归时及月华。","城陰一道直，燭焰兩行斜。","东吹先催柳，南霜不殺花。","臯橋夜沽酒，灯火是誰家。"]', '诗', 'shi', '', NULL, '夜歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b848c2-09cd-47dd-87b1-1514dde93ce7', '自歎', '自歎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豈獨年相迫，兼爲病所侵。","春來痰氣動，老去嗽聲深。","眼暗猶操筆，頭斑未挂簪。","因循過日月，真是俗人心。"]', '["豈独年相迫，兼爲病所侵。","春来痰氣动，老去嗽声深。","眼暗猶操笔，头斑未挂簪。","因循過日月，真是俗人心。"]', '诗', 'shi', '', NULL, '自歎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72ee1249-ecce-4760-8ac9-d803c9838535', '郡中閑獨寄微之及崔湖州', '郡中闲独寄微之及崔湖州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["少年賓旅非吾輩，晚歲簪纓束我身。","酒散更無同宿客，詩成長作獨吟人。","蘋洲會面知何日，鏡水離心又一春。","兩處也應相憶在，官高年長少情親。"]', '["少年賓旅非吾輩，晚歲簪纓束我身。","酒散更無同宿客，诗成长作独吟人。","蘋洲會面知何日，镜水離心又一春。","兩处也應相憶在，官高年长少情親。"]', '诗', 'shi', '', NULL, '郡中閑獨寄微之及崔湖州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de53824-9293-43d0-b5d1-95fdf5d0428d', '小舫', '小舫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小舫一艘新造了，輕裝梁柱庳安篷。","深坊靜岸遊應徧，淺水低橋去盡通。","黃柳影籠隨櫂月，白蘋香起打頭風。","慢牽欲傍櫻桃泊，借問誰家花最紅。"]', '["小舫一艘新造了，轻裝梁柱庳安篷。","深坊静岸游應徧，淺水低橋去尽通。","黄柳影籠隨櫂月，白蘋香起打头风。","慢牽欲傍櫻桃泊，借问誰家花最紅。"]', '诗', 'shi', '', NULL, '小舫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70a3a211-7842-404c-82d8-3f9a8d395a3c', '馬墜強出贈同座', '马墜強出贈同座', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["足傷遭馬墜，腰重倩人擡。","秪合窗間臥，何由花下來。","坐依桃葉枝，行呷地黃桮。","強出非他意，東風落盡梅。"]', '["足傷遭马墜，腰重倩人擡。","秪合窗间臥，何由花下来。","坐依桃葉枝，行呷地黄桮。","強出非他意，东风落尽梅。"]', '诗', 'shi', '', NULL, '馬墜強出贈同座 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb67b893-284e-4db0-9179-d1b930a1e316', '夜聞賈常州崔湖州茶山境會想羨歡宴因寄此詩', '夜闻賈常州崔湖州茶山境會想羨歡宴因寄此诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遙聞境會茶山夜，珠翠歌鐘俱遶身。","盤下中分兩州界，燈前合作一家春。","青娥遰舞應爭妙，紫笋齊嘗各鬬新。","自歎花時北窗下，蒲黃酒對病眠人。"]', '["遙闻境會茶山夜，珠翠歌鐘俱遶身。","盤下中分兩州界，灯前合作一家春。","青娥遰舞應爭妙，紫笋齊嘗各鬬新。","自歎花时北窗下，蒲黄酒对病眠人。"]', '诗', 'shi', '', NULL, '夜聞賈常州崔湖州茶山境會想羨歡宴因寄此詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0730fb32-2440-4438-9fc5-95fa7c02059b', '酬微之開拆新樓初畢相報末聯見戲之作', '酬微之开拆新楼初畢相報末聯见戲之作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海山鬱鬱石稜稜，新豁高居正好登。","南臨贍部三千界，東對蓬宮十二層。","報我樓成秋望月，把君詩讀夜回燈。","無妨却有他心眼，妝點亭臺即不能。"]', '["海山鬱鬱石稜稜，新豁高居正好登。","南臨贍部三千界，东对蓬宮十二層。","報我楼成秋望月，把君诗读夜回灯。","無妨却有他心眼，妝点亭台即不能。"]', '诗', 'shi', '', NULL, '酬微之開拆新樓初畢相報末聯見戲之作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da4834a4-014e-4281-b6d2-d626d4cae4ea', '病中多雨逢寒食', '病中多雨逢寒食', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水國多陰常嬾出，老夫饒病愛閑眠。","三旬臥度鶯花月，一半春銷風雨天。","薄暮何人吹觱篥，新晴幾處縛鞦韆。","綵繩芳樹長如舊，唯是年年換少年。"]', '["水国多陰常嬾出，老夫饒病愛闲眠。","三旬臥度鶯花月，一半春銷风雨天。","薄暮何人吹觱篥，新晴幾处縛鞦韆。","綵繩芳樹长如旧，唯是年年換少年。"]', '诗', 'shi', '', NULL, '病中多雨逢寒食 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4962e15-55b5-4797-8972-2d7aecca7f10', '清明夜', '清明夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["好風朧月清明夜，碧砌紅軒刺史家。","獨繞迴廊行復歇，遙聽弦管暗看花。"]', '["好风朧月清明夜，碧砌紅軒刺史家。","独繞迴廊行复歇，遙听弦管暗看花。"]', '诗', 'shi', '', NULL, '清明夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69a2e7f7-84d5-4cbe-9161-888e1fc0fe69', '蘇州柳', '蘇州柳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金谷園中黃嫋娜，曲江亭畔碧婆娑。","老來處處遊行徧，不似蘇州柳最多。","絮撲白頭條拂面，使君無計奈春何。"]', '["金谷园中黄嫋娜，曲江亭畔碧婆娑。","老来处处游行徧，不似蘇州柳最多。","絮撲白头條拂面，使君無計奈春何。"]', '诗', 'shi', '', NULL, '蘇州柳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c4a9ce7-50bc-4a25-9d38-645f4bc456c2', '三月二十八日贈周判官', '三月二十八日贈周判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一春惆悵殘三日，醉問周郎憶得無。","柳絮送人鶯勸酒，去年今日別東都。"]', '["一春惆悵殘三日，醉问周郎憶得無。","柳絮送人鶯勸酒，去年今日別东都。"]', '诗', 'shi', '', NULL, '三月二十八日贈周判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb5b068a-4016-4069-88a0-5eb16380e156', '偶作', '偶作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅杏初生葉，青梅已綴枝。","闌珊花落後，寂寞酒醒時。","坐悶低眉久，行慵舉足遲。","少年君莫怪，頭白自應知。"]', '["紅杏初生葉，青梅已綴枝。","闌珊花落後，寂寞酒醒时。","坐悶低眉久，行慵舉足遲。","少年君莫怪，头白自應知。"]', '诗', 'shi', '', NULL, '偶作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c9486c8-14af-4be8-b73e-20e06fcaa100', '重荅劉和州', '重荅劉和州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["分無佳麗敵西施，敢有文章替左司。","隨分笙歌聊自樂，等閑篇詠被人知。","花邊妓引尋香徑，月下僧留宿劒池。","可惜當時好風景，吳王應不解吟詩。"]', '["分無佳丽敵西施，敢有文章替左司。","隨分笙歌聊自乐，等闲篇詠被人知。","花邊妓引尋香徑，月下僧留宿劒池。","可惜當时好风景，吳王應不解吟诗。"]', '诗', 'shi', '', NULL, '重荅劉和州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d846c0ad-cf6e-4605-970f-19737f3f02c5', '奉送三兄', '奉送三兄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["少年曾管二千兵，晝聽笙歌夜斫營。","自反丘園頭盡白，每逢旗鼓眼猶明。","杭州暮醉連牀臥，吳郡春遊並馬行。","自媿阿連官職慢，只教兄作使君兄。"]', '["少年曾管二千兵，晝听笙歌夜斫營。","自反丘园头尽白，每逢旗鼓眼猶明。","杭州暮醉連牀臥，吳郡春游並马行。","自媿阿連官職慢，只教兄作使君兄。"]', '诗', 'shi', '', NULL, '奉送三兄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('735ba85e-5a21-4fe1-837d-dc9c4c197d98', '城上夜宴', '城上夜宴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["留春不住登城望，惜夜相將秉燭遊。","風月萬家河兩岸，笙歌一曲郡西樓。","詩聽越客吟何苦，酒被吳娃勸不休。","從道人生都是夢，夢中歡笑亦勝愁。"]', '["留春不住登城望，惜夜相將秉燭游。","风月万家河兩岸，笙歌一曲郡西楼。","诗听越客吟何苦，酒被吳娃勸不休。","從道人生都是梦，梦中歡笑亦勝愁。"]', '诗', 'shi', '', NULL, '城上夜宴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b45d8a0-3773-4495-afa8-ff48934fea92', '重題小舫贈周從事兼戲微之', '重題小舫贈周從事兼戲微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["細[篷]青篾織魚鱗，小眼紅窗襯麴塵。","闊狹纔容從事座，高低恰稱使君身。","舞筵須揀腰輕女，仙櫂難勝骨重人。","不似鏡湖廉使出，高檣大艑鬧驚春。"]', '["細[篷]青篾织鱼鱗，小眼紅窗襯麴塵。","闊狹纔容從事座，高低恰稱使君身。","舞筵須揀腰轻女，仙櫂难勝骨重人。","不似镜湖廉使出，高檣大艑鬧驚春。"]', '诗', 'shi', '', NULL, '重題小舫贈周從事兼戲微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9972acf-14e7-4ce0-9c3d-9a70144ea2f8', '吳櫻桃', '吳櫻桃', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["含桃最說出東吳，香色鮮穠氣味殊。","洽恰舉頭千萬顆，婆娑拂面兩三株。","鳥偷飛處銜將火，人摘爭時蹋破珠。","可惜風吹兼雨打，明朝後日即應無。"]', '["含桃最说出东吳，香色鲜穠氣味殊。","洽恰舉头千万顆，婆娑拂面兩三株。","鸟偷飞处銜將火，人摘爭时蹋破珠。","可惜风吹兼雨打，明朝後日即應無。"]', '诗', 'shi', '', NULL, '吳櫻桃 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5afc84e2-35d2-4add-bdaa-1f425408de87', '春盡勸客酒', '春尽勸客酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["林下春將盡，池邊日半斜。","櫻桃落砌顆，夜合隔簾花。","嘗酒留閑客，行茶使小娃。","殘杯勸不飲，留醉向誰家。"]', '["林下春將尽，池邊日半斜。","櫻桃落砌顆，夜合隔簾花。","嘗酒留闲客，行茶使小娃。","殘杯勸不饮，留醉向誰家。"]', '诗', 'shi', '', NULL, '春盡勸客酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397c4d28-1cff-48ce-b9ce-5fefcca6e077', '仲夏齋居偶題八韻寄微之及崔湖州', '仲夏斋居偶題八韻寄微之及崔湖州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["腥血與葷蔬，停來一月餘。","肌膚雖瘦損，方寸任清虛。","體適通宵坐，頭慵隔日梳。","眼前無俗物，身外即僧居。","水榭風來遠，松廊雨過初。","褰簾放巢燕，投食施池魚。","久別閑遊伴，頻勞問疾書。","不知湖與越，吏隱興何如。"]', '["腥血與葷蔬，停来一月餘。","肌膚雖瘦損，方寸任清虛。","體適通宵坐，头慵隔日梳。","眼前無俗物，身外即僧居。","水榭风来远，松廊雨過初。","褰簾放巢燕，投食施池鱼。","久別闲游伴，頻勞问疾书。","不知湖與越，吏隐兴何如。"]', '诗', 'shi', '', NULL, '仲夏齋居偶題八韻寄微之及崔湖州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ea81d7-5a35-47c8-af31-910085d8db11', '官宅', '官宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅紫共紛紛，祗承老使君。","移舟木蘭櫂，行酒石榴帬。","水色窗窗見，花香院院聞。","戀他官舍住，雙鬢白如雲。"]', '["紅紫共紛紛，祗承老使君。","移舟木蘭櫂，行酒石榴帬。","水色窗窗见，花香院院闻。","戀他官舍住，雙鬢白如云。"]', '诗', 'shi', '', NULL, '官宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4871bed-61c5-478c-8451-0b3023aa5ed0', '六月三日夜聞蟬', '六月三日夜闻蟬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["荷香清露墜，柳動好風生。","微月初三夜，新蟬第一聲。","乍聞愁北客，靜聽憶東京。","我有竹林宅，別來蟬再鳴。","不知池上月，誰撥小船行。"]', '["荷香清露墜，柳动好风生。","微月初三夜，新蟬第一声。","乍闻愁北客，静听憶东京。","我有竹林宅，別来蟬再鳴。","不知池上月，誰撥小船行。"]', '诗', 'shi', '', NULL, '六月三日夜聞蟬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4adc0a51-920f-4c4c-80ec-b8d0600d2c53', '蓮石', '蓮石', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青石一兩片，白蓮三四枝。","寄將東洛去，心與物相隨。","石倚風前樹，蓮栽月下池。","遙知安置處，預想發榮時。","領郡來何遠，還鄉去已遲。","莫言千里別，歲晚有心期。"]', '["青石一兩片，白蓮三四枝。","寄將东洛去，心與物相隨。","石倚风前樹，蓮栽月下池。","遙知安置处，預想發榮时。","領郡来何远，還乡去已遲。","莫言千里別，歲晚有心期。"]', '诗', 'shi', '', NULL, '蓮石 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99bbf157-b2fe-4428-84ce-05389ff936a8', '眼病二首 一', '眼病二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["散亂空中千片雪，蒙籠物上一重紗。","縱逢晴景如看霧，不是春天亦看花。","僧說客塵來眼界，醫言風眩在肝家。","兩頭治療何曾瘥，藥力微茫佛力賒。"]', '["散亂空中千片雪，蒙籠物上一重紗。","縱逢晴景如看霧，不是春天亦看花。","僧说客塵来眼界，醫言风眩在肝家。","兩头治療何曾瘥，藥力微茫佛力賒。"]', '诗', 'shi', '', NULL, '眼病二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32a240b5-73b1-4b1d-8a58-e93c2884bfb5', '眼病二首 二', '眼病二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["眼藏損傷來已久，病根牢固去應難。","醫師盡勸先停酒，道侶多教早罷官。","案上謾鋪龍樹論，盒中虛撚決明丸。","人間方藥應無益，爭得金箆試刮看。"]', '["眼藏損傷来已久，病根牢固去應难。","醫師尽勸先停酒，道侶多教早罷官。","案上謾鋪龙樹論，盒中虛撚決明丸。","人间方藥應無益，爭得金箆試刮看。"]', '诗', 'shi', '', NULL, '眼病二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f57ba9e-88e9-423e-b2ba-27a83e2d91a1', '題東武丘寺六韻', '題东武丘寺六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香剎看非遠，祇園入始深。","龍蟠松矯矯，玉立竹森森。","怪石千僧坐，靈池一劒沈。","海當亭兩面，山在寺中心。","酒熟憑花勸，詩成倩鳥吟。","寄言軒冕客，此地好抽簪。"]', '["香剎看非远，祇园入始深。","龙蟠松矯矯，玉立竹森森。","怪石千僧坐，靈池一劒沈。","海當亭兩面，山在寺中心。","酒熟憑花勸，诗成倩鸟吟。","寄言軒冕客，此地好抽簪。"]', '诗', 'shi', '', NULL, '題東武丘寺六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b6ad2e4-49f2-410a-88f0-99b678ed315a', '夜遊西武丘寺八韻', '夜游西武丘寺八韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不厭西丘寺，閑來即一過。","舟船轉雲島，樓閣出煙蘿。","路入青松影，門臨白月波。","魚跳驚秉燭，猨覰怪鳴珂。","搖曳雙紅斾，娉婷十翠娥。","香花助羅綺，鐘梵避笙歌。","領郡時將久，遊山數幾何。","一年十二度，非少亦非多。"]', '["不厭西丘寺，闲来即一過。","舟船轉云島，楼閣出煙蘿。","路入青松影，门臨白月波。","鱼跳驚秉燭，猨覰怪鳴珂。","搖曳雙紅斾，娉婷十翠娥。","香花助羅綺，鐘梵避笙歌。","領郡时將久，游山數幾何。","一年十二度，非少亦非多。"]', '诗', 'shi', '', NULL, '夜遊西武丘寺八韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4e1a13-ec72-4d1b-82d1-9370cbb9d835', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘇杭自昔稱名郡，牧守當今當好官。","兩地江山蹋得徧，五年風月詠將殘。","幾時酒醆曾拋却，何處花枝不把看？","白髮滿頭歸得也，詩情酒興漸闌珊。"]', '["蘇杭自昔稱名郡，牧守當今當好官。","兩地江山蹋得徧，五年风月詠將殘。","幾时酒醆曾拋却，何处花枝不把看？","白髮满头归得也，诗情酒兴漸闌珊。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81ff5a96-25fd-4e27-941c-25eee0552cb5', '重詠', '重詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日覺雙眸暗，年驚兩鬢蒼。","病應無處避，老更不宜忙。","徇俗心情少，休官道理長。","今秋歸去定，何必重思量。"]', '["日覺雙眸暗，年驚兩鬢蒼。","病應無处避，老更不宜忙。","徇俗心情少，休官道理长。","今秋归去定，何必重思量。"]', '诗', 'shi', '', NULL, '重詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('407b7038-fd7c-402d-bb36-20a3fe23d995', '百日假滿', '百日假满', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["心中久有歸田計，身上都無濟世才。","長告初從百日滿，故鄉元約一年回。","馬辭轅下頭高舉，鶴出籠中翅大開。","但拂衣行莫回顧，的無官職趁人來。"]', '["心中久有归田計，身上都無濟世才。","长告初從百日满，故乡元約一年回。","马辞轅下头高舉，鹤出籠中翅大开。","但拂衣行莫回顧，的無官職趁人来。"]', '诗', 'shi', '', NULL, '百日假滿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b4ab5ef-a6d2-4d81-a538-9e2bfc0129dd', '九日寄微之', '九日寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["眼闇頭風事事妨，遶籬新菊爲誰黃。","閑遊日久心慵倦，痛飲年深肺損傷。","吳郡兩回逢九月，越州四度見重陽。","怕飛杯酒多分數，厭聽笙歌舊曲章。","蟋蟀聲寒初過雨，茱萸色淺未經霜。","去秋共數登高會，又被今年減一場。"]', '["眼闇头风事事妨，遶籬新菊爲誰黄。","闲游日久心慵倦，痛饮年深肺損傷。","吳郡兩回逢九月，越州四度见重陽。","怕飞杯酒多分數，厭听笙歌旧曲章。","蟋蟀声寒初過雨，茱萸色淺未經霜。","去秋共數登高會，又被今年減一場。"]', '诗', 'shi', '', NULL, '九日寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed6c13dd-73fd-4528-b089-b71cbb2e2bb9', '題報恩寺', '題報恩寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["好是清涼地，都無繫絆身。","晚晴宜野寺，秋景屬閑人。","淨石堪敷坐，寒泉可濯巾。","自慙容鬢上，猶帶郡庭塵。"]', '["好是清涼地，都無繫絆身。","晚晴宜野寺，秋景屬闲人。","淨石堪敷坐，寒泉可濯巾。","自慙容鬢上，猶带郡庭塵。"]', '诗', 'shi', '', NULL, '題報恩寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6b1e472-ea33-45a1-abe7-3480de6a7250', '晚起', '晚起', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臥聽鼕鼕衙鼓聲，起遲睡足長心情。","華簪脫後頭雖白，堆案拋來眼校明。","閑上籃轝乘興出，醉回花舫信風行。","明朝更濯塵纓去，聞道松江水最清。"]', '["臥听鼕鼕衙鼓声，起遲睡足长心情。","华簪脫後头雖白，堆案拋来眼校明。","闲上籃轝乘兴出，醉回花舫信风行。","明朝更濯塵纓去，闻道松江水最清。"]', '诗', 'shi', '', NULL, '晚起 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('410ddbf7-7616-4230-a411-a8e6d5a995a4', '自思益寺次楞伽寺作', '自思益寺次楞伽寺作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝從思益峰遊後，晚到楞伽寺歇時。","照水姿容雖已老，上山筋力未全衰。","行逢禪客多相問，坐倚漁舟一自思。","猶去懸車十五載，休官非早亦非遲。"]', '["朝從思益峰游後，晚到楞伽寺歇时。","照水姿容雖已老，上山筋力未全衰。","行逢禪客多相问，坐倚漁舟一自思。","猶去懸车十五載，休官非早亦非遲。"]', '诗', 'shi', '', NULL, '自思益寺次楞伽寺作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63c7e0a-d361-4626-a4d2-49db01b48fbc', '松江亭攜樂觀漁宴宿', '松江亭携乐观漁宴宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["震澤平蕪岸，松江落葉波。","在官常夢想，爲客始經過。","水面排罾網，船頭簇綺羅。","朝盤鱠紅鯉，夜燭舞青娥。","雁斷知風急，潮平見月多。","繁絲與促管，不解和漁歌。"]', '["震澤平蕪岸，松江落葉波。","在官常梦想，爲客始經過。","水面排罾網，船头簇綺羅。","朝盤鱠紅鯉，夜燭舞青娥。","雁斷知风急，潮平见月多。","繁絲與促管，不解和漁歌。"]', '诗', 'shi', '', NULL, '松江亭攜樂觀漁宴宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c57737-1c2c-4d34-b9c9-5dc6e24394a9', '宿靈巖寺上院', '宿靈巖寺上院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高高白月上青林，客去僧歸獨夜深。","葷血屏除唯對酒，歌鐘放散只留琴。","更無俗物當人眼，但有泉聲洗我心。","最愛曉亭東望好，太湖煙水綠沈沈。"]', '["高高白月上青林，客去僧归独夜深。","葷血屏除唯对酒，歌鐘放散只留琴。","更無俗物當人眼，但有泉声洗我心。","最愛晓亭东望好，太湖煙水綠沈沈。"]', '诗', 'shi', '', NULL, '宿靈巖寺上院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0b3902c-6f2a-4b1d-b19a-845c9dfef2c9', '酬別周從事二首 一', '酬別周從事二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["腰痛拜迎人客倦，眼昏勾押簿書難。","辭官歸去緣衰病，莫作陶潛范蠡看。"]', '["腰痛拜迎人客倦，眼昏勾押簿书难。","辞官归去緣衰病，莫作陶潛范蠡看。"]', '诗', 'shi', '', NULL, '酬別周從事二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a622866-547e-4b15-82db-7d664b7133e3', '酬別周從事二首 二', '酬別周從事二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛下田園久拋擲，吳中歌酒莫留連。","嵩陽雲樹伊川月，已校歸遲四五年。"]', '["洛下田园久拋擲，吳中歌酒莫留連。","嵩陽云樹伊川月，已校归遲四五年。"]', '诗', 'shi', '', NULL, '酬別周從事二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159c2a24-3be3-4a3d-b975-17c337b915b5', '武丘寺路', '武丘寺路', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自開山寺路，水陸往來頻。","銀勒牽驕馬，花船載麗人。","芰荷生欲徧，桃李種仍新。","好住湖堤上，長留一道春。"]', '["自开山寺路，水陸往来頻。","銀勒牽驕马，花船載丽人。","芰荷生欲徧，桃李種仍新。","好住湖堤上，长留一道春。"]', '诗', 'shi', '', NULL, '武丘寺路 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b8b4672-b563-42ef-b2dd-811f1df5fadc', '齊雲樓晚望偶題十韻兼呈馮侍御周殷二協律', '齊云楼晚望偶題十韻兼呈馮侍御周殷二協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潦倒宦情盡，蕭條芳歲闌。","欲辭南國去，重上北城看。","複疊江山壯，平鋪井邑寬。","人稠過楊府，坊鬧半長安。","插霧峰頭沒，穿霞日脚殘。","水光紅漾漾，樹色綠漫漫。","約略留遺愛，殷勤念舊歡。","病拋官職易，老別友朋難。","九月全無熱，西風亦未寒。","齊雲樓北面，半日凭欄干。"]', '["潦倒宦情尽，蕭條芳歲闌。","欲辞南国去，重上北城看。","複叠江山壯，平鋪井邑寬。","人稠過楊府，坊鬧半长安。","插霧峰头沒，穿霞日脚殘。","水光紅漾漾，樹色綠漫漫。","約略留遺愛，殷勤念旧歡。","病拋官職易，老別友朋难。","九月全無熱，西风亦未寒。","齊云楼北面，半日凭欄干。"]', '诗', 'shi', '', NULL, '齊雲樓晚望偶題十韻兼呈馮侍御周殷二協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac5183a6-4d6f-4ae7-83bd-7f925d2e71af', '河亭晴望', '河亭晴望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風轉雲頭歛，煙銷水面開。","晴虹橋影出，秋雁櫓聲來。","郡靜官初罷，鄉遙信未迴。","明朝是重九，誰勸菊花桮。"]', '["风轉云头歛，煙銷水面开。","晴虹橋影出，秋雁櫓声来。","郡静官初罷，乡遙信未迴。","明朝是重九，誰勸菊花桮。"]', '诗', 'shi', '', NULL, '河亭晴望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dc8f53a-980e-40fa-b2c1-4c00638899d4', '留別微之', '留別微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["干時久與本心違，悟道深知前事非。","猶厭勞形辭郡印，那將趂伴著朝衣。","五千言裏教知足，三百篇中勸式微。","少室雲邊伊水畔，比君校老合先歸。"]', '["干时久與本心違，悟道深知前事非。","猶厭勞形辞郡印，那將趂伴著朝衣。","五千言裏教知足，三百篇中勸式微。","少室云邊伊水畔，比君校老合先归。"]', '诗', 'shi', '', NULL, '留別微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cae3a49-73b0-45a3-a68f-4db8695761ea', '自喜', '自喜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自喜天教我少緣，家徒行計兩翩翩。","身兼妻子都三口，鶴與琴書共一船。","僮僕減來無冗食，資糧算外有餘錢。","攜將貯作丘中費，猶免飢寒得數年。"]', '["自喜天教我少緣，家徒行計兩翩翩。","身兼妻子都三口，鹤與琴书共一船。","僮僕減来無冗食，資糧算外有餘錢。","携將貯作丘中費，猶免飢寒得數年。"]', '诗', 'shi', '', NULL, '自喜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd2f8c79-b10b-43fa-b4d7-b2cfc7171976', '武丘寺路宴留別諸妓', '武丘寺路宴留別諸妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["銀泥帬映錦障泥，畫舸停橈馬簇蹄。","清管曲終鸚鵡語，紅旗影動䮂䮧嘶。","漸消醉色朱顏淺，欲語離情翠黛低。","莫忘使君吟詠處，女墳湖北武丘西。"]', '["銀泥帬映錦障泥，畫舸停橈马簇蹄。","清管曲終鸚鵡語，紅旗影动䮂䮧嘶。","漸消醉色朱顏淺，欲語離情翠黛低。","莫忘使君吟詠处，女墳湖北武丘西。"]', '诗', 'shi', '', NULL, '武丘寺路宴留別諸妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7cf5cd4-a4f2-49c6-9bc8-49658ddfc2d7', '江上對酒二首 一', '江上对酒二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["酒助疎頑性，琴資緩慢情。","有慵將送老，無智可勞生。","忽忽忘機坐，倀倀任運行。","家鄉安處是，那獨在神京。"]', '["酒助疎頑性，琴資緩慢情。","有慵將送老，無智可勞生。","忽忽忘機坐，倀倀任運行。","家乡安处是，那独在神京。"]', '诗', 'shi', '', NULL, '江上對酒二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48159445-7697-4040-9746-a11162b31f96', '江上對酒二首 二', '江上对酒二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["久貯滄浪意，初辭桎梏身。","昏昏常帶酒，默默不應人。","坐穩便箕踞，眠多愛欠伸。","客來存禮數，始著白綸巾。"]', '["久貯滄浪意，初辞桎梏身。","昏昏常带酒，默默不應人。","坐穩便箕踞，眠多愛欠伸。","客来存禮數，始著白綸巾。"]', '诗', 'shi', '', NULL, '江上對酒二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2645ac88-2914-4384-8228-87b44434580c', '望亭驛酬別周判官', '望亭驛酬別周判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何事出長洲，連宵飲不休。","醒應難作別，歡漸少於愁。","燈火穿村市，笙歌上驛樓。","何言五十里，已不屬蘇州。"]', '["何事出长洲，連宵饮不休。","醒應难作別，歡漸少於愁。","灯火穿村市，笙歌上驛楼。","何言五十里，已不屬蘇州。"]', '诗', 'shi', '', NULL, '望亭驛酬別周判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbd1ac2f-cf20-40a5-817b-14924b06a285', '見小姪龜兒詠燈詩幷臘娘製衣因寄行簡', '见小姪龟兒詠灯诗幷臘娘製衣因寄行簡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["已知臘子能裁服，復報龜兒解詠燈。","巧婦才人常薄命，莫教男女苦多能。"]', '["已知臘子能裁服，复報龟兒解詠灯。","巧婦才人常薄命，莫教男女苦多能。"]', '诗', 'shi', '', NULL, '見小姪龜兒詠燈詩幷臘娘製衣因寄行簡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81823c73-63ae-460d-a801-19ae7f4d1fdb', '酒筵上荅張居士', '酒筵上荅張居士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["但要前塵減，無妨外相同。","雖過酒肆上，不離道場中。","弦管聲非實，花鈿色是空。","何人知此義，唯有淨名翁。"]', '["但要前塵減，無妨外相同。","雖過酒肆上，不離道場中。","弦管声非實，花鈿色是空。","何人知此義，唯有淨名翁。"]', '诗', 'shi', '', NULL, '酒筵上荅張居士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d70667b9-669e-462b-a815-96303acde962', '鸚鵡', '鸚鵡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隴西鸚鵡到江東，養得經年觜漸紅。","常恐思歸先剪翅，每因餧食暫開籠。","人憐巧語情雖重，鳥憶高飛意不同。","應似朱門歌舞妓，深藏牢閉後房中。"]', '["隴西鸚鵡到江东，養得經年觜漸紅。","常恐思归先剪翅，每因餧食暫开籠。","人怜巧語情雖重，鸟憶高飞意不同。","應似朱门歌舞妓，深藏牢閉後房中。"]', '诗', 'shi', '', NULL, '鸚鵡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a80a6513-bbe1-4f76-be73-2fb46f6e8b41', '聽琵琶妓彈略略', '听琵琶妓彈略略', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["腕軟撥頭輕，新教略略成。","四弦千遍語，一曲萬重情。","法向師邊得，能從意上生。","莫欺江外手，別是一家聲。"]', '["腕軟撥头轻，新教略略成。","四弦千遍語，一曲万重情。","法向師邊得，能從意上生。","莫欺江外手，別是一家声。"]', '诗', 'shi', '', NULL, '聽琵琶妓彈略略 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9aeb8a60-5162-4390-992c-46f379a53706', '寫新詩寄微之偶題卷後', '寫新诗寄微之偶題卷後', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寫了吟看滿卷愁，淺紅牋紙小銀鉤。","未容寄與微之去，已被人傳到越州。"]', '["寫了吟看满卷愁，淺紅牋紙小銀鉤。","未容寄與微之去，已被人傳到越州。"]', '诗', 'shi', '', NULL, '寫新詩寄微之偶題卷後 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d89bdc-6938-4848-8a1f-8c871fc00aa5', '寶曆二年八月三十日夜夢後作', '寶曆二年八月三十日夜梦後作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["塵纓忽解誠堪喜，世網重來未可知。","莫忘全吳館中夢，嶺南泥雨步行時。"]', '["塵纓忽解誠堪喜，世網重来未可知。","莫忘全吳館中梦，嶺南泥雨步行时。"]', '诗', 'shi', '', NULL, '寶曆二年八月三十日夜夢後作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae5d6fb-2f7b-4ecc-a439-b22bd39e8f23', '與夢得同登棲靈塔', '與梦得同登棲靈塔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["半月悠悠在廣陵，何樓何塔不同登。","共憐筋力猶堪在，上到棲靈第九層。"]', '["半月悠悠在廣陵，何楼何塔不同登。","共怜筋力猶堪在，上到棲靈第九層。"]', '诗', 'shi', '', NULL, '與夢得同登棲靈塔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1fa4545-fc30-4c04-878c-dd3d0b3c934e', '夢蘇州水閣寄馮侍御', '梦蘇州水閣寄馮侍御', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["揚州驛裏夢蘇州，夢到花橋水閣頭。","覺後不知馮侍御，此中昨夜共誰遊。"]', '["揚州驛裏梦蘇州，梦到花橋水閣头。","覺後不知馮侍御，此中昨夜共誰游。"]', '诗', 'shi', '', NULL, '夢蘇州水閣寄馮侍御 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a3b0891-a7f3-42b0-a2da-582cb19658f7', '喜罷郡', '喜罷郡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五年兩郡亦堪嗟，偷出遊山走看花。","自此光陰爲己有，從前日月屬官家。","樽前免被催迎使，枕上休聞報坐衙。","睡到午時歡到夜，回看官職是泥沙。"]', '["五年兩郡亦堪嗟，偷出游山走看花。","自此光陰爲己有，從前日月屬官家。","樽前免被催迎使，枕上休闻報坐衙。","睡到午时歡到夜，回看官職是泥沙。"]', '诗', 'shi', '', NULL, '喜罷郡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('213e51fd-6871-4d7f-a5a1-9bbf57fa272c', '荅次休上人', '荅次休上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["姓白使君無麗句，名休座主有新文。","禪心不合生分別，莫愛餘霞嫌碧雲。"]', '["姓白使君無丽句，名休座主有新文。","禪心不合生分別，莫愛餘霞嫌碧云。"]', '诗', 'shi', '', NULL, '荅次休上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82d15471-a8d9-441b-9df0-fd44c38f1c26', '感悟妄緣題如上人壁', '感悟妄緣題如上人壁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自從爲騃童，直至作衰翁。","所好隨年異，爲忙終日同。","弄沙成佛塔，鏘玉謁王宮。","彼此皆兒戲，須臾即色空。","有營非了義，無著是真宗。","兼恐勤修道，猶應在妄中。"]', '["自從爲騃童，直至作衰翁。","所好隨年異，爲忙終日同。","弄沙成佛塔，鏘玉謁王宮。","彼此皆兒戲，須臾即色空。","有營非了義，無著是真宗。","兼恐勤修道，猶應在妄中。"]', '诗', 'shi', '', NULL, '感悟妄緣題如上人壁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a75fb8c-f4f3-4b74-a9bc-0e04dd914c02', '思子臺有感二首 一', '思子台有感二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曾家機上聞投杼，尹氏園中見掇蜂。","但以恩情生隙罅，何人不解作江充。"]', '["曾家機上闻投杼，尹氏园中见掇蜂。","但以恩情生隙罅，何人不解作江充。"]', '诗', 'shi', '', NULL, '思子臺有感二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6017dfa6-a221-4bef-8838-55e7cbaa4a33', '思子臺有感二首 二', '思子台有感二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["闇生魑魅蠹生蟲，何異讒生疑阻中。","但使武皇心似燭，江充不敢作江充。"]', '["闇生魑魅蠹生蟲，何異讒生疑阻中。","但使武皇心似燭，江充不敢作江充。"]', '诗', 'shi', '', NULL, '思子臺有感二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b49097d6-8b02-479c-8aa6-8b871dc827b4', '賦得邊城角', '賦得邊城角', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["邊角兩三枝，霜天隴上兒。","望鄉相並立，向月一時吹。","戰馬頭皆舉，征人手盡垂。","嗚嗚三奏罷，城上展旌旗。"]', '["邊角兩三枝，霜天隴上兒。","望乡相並立，向月一时吹。","戰马头皆舉，征人手尽垂。","嗚嗚三奏罷，城上展旌旗。"]', '诗', 'shi', '', NULL, '賦得邊城角 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56ff271-9f32-4f56-a08a-fbd69dde4736', '憶洛中所居', '憶洛中所居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽憶東都宅，春來事宛然。","雪銷行徑裏，水上臥房前。","厭綠栽黃竹，嫌紅種白蓮。","醉教鸎送酒，閑遣鶴看船。","幸是林園主，慙爲食祿牽。","宦情薄似紙，鄉思急於弦。","豈合姑蘇守，歸休更待年。"]', '["忽憶东都宅，春来事宛然。","雪銷行徑裏，水上臥房前。","厭綠栽黄竹，嫌紅種白蓮。","醉教鸎送酒，闲遣鹤看船。","幸是林园主，慙爲食祿牽。","宦情薄似紙，乡思急於弦。","豈合姑蘇守，归休更待年。"]', '诗', 'shi', '', NULL, '憶洛中所居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e50b3fa5-cbed-40a3-a54b-86c25a2c9d43', '想歸田園', '想归田园', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["戀他朝市求何事，想取丘園樂此身。","千首惡詩吟過日，一壺好酒醉消春。","歸鄉年亦非全老，罷郡家仍未苦貧。","快活不知如我者，人間能有幾多人。"]', '["戀他朝市求何事，想取丘园乐此身。","千首惡诗吟過日，一壺好酒醉消春。","归乡年亦非全老，罷郡家仍未苦貧。","快活不知如我者，人间能有幾多人。"]', '诗', 'shi', '', NULL, '想歸田園 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('785ddb64-8fd9-402b-b4fc-8cb50e1469ed', '琴茶', '琴茶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["兀兀寄形羣動內，陶陶任性一生間。","自拋官後春多醉，不讀書來老更閑。","琴裏知聞唯淥水，茶中故舊是蒙山。","窮通行止長相伴，誰道吾今無往還。"]', '["兀兀寄形羣动內，陶陶任性一生间。","自拋官後春多醉，不读书来老更闲。","琴裏知闻唯淥水，茶中故旧是蒙山。","窮通行止长相伴，誰道吾今無往還。"]', '诗', 'shi', '', NULL, '琴茶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e72edc33-55dd-4ec2-8e17-432c3b8e70ea', '贈楚州郭使君', '贈楚州郭使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淮水東南第一州，山圍雉堞月當樓。","黃金印綬懸腰底，白雪歌詩落筆頭。","笑看兒童騎竹馬，醉攜賓客上仙舟。","當家美事堆身上，何啻林宗與細侯。"]', '["淮水东南第一州，山圍雉堞月當楼。","黄金印綬懸腰底，白雪歌诗落笔头。","笑看兒童騎竹马，醉携賓客上仙舟。","當家美事堆身上，何啻林宗與細侯。"]', '诗', 'shi', '', NULL, '贈楚州郭使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15e79aa0-f66b-4029-8040-cf0d273a2346', '和郭使君題枸杞', '和郭使君題枸杞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山陽太守政嚴明，吏靜人安無犬驚。","不知靈藥根成狗，怪得時聞吠夜聲。"]', '["山陽太守政嚴明，吏静人安無犬驚。","不知靈藥根成狗，怪得时闻吠夜声。"]', '诗', 'shi', '', NULL, '和郭使君題枸杞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e0cbe7-12cb-460f-89fc-74e68c8f220e', '初到洛下閑遊', '初到洛下闲游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漢庭重少身宜退，洛下閑居迹可逃。","趂伴入朝應老醜，尋春放醉尚粗豪。","詩攜綵紙新裝卷，酒典緋花舊賜袍。","曾在東方千騎上，至今躞蹀馬頭高。"]', '["漢庭重少身宜退，洛下闲居迹可逃。","趂伴入朝應老醜，尋春放醉尚粗豪。","诗携綵紙新裝卷，酒典緋花旧賜袍。","曾在东方千騎上，至今躞蹀马头高。"]', '诗', 'shi', '', NULL, '初到洛下閑遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7faa59ad-1cd2-45af-8b4a-90d7fb3d6b5e', '醉贈劉二十八使君', '醉贈劉二十八使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爲我引桮添酒飲，與君把箸擊盤歌。","詩稱國手徒爲爾，命壓人頭不奈何。","舉眼風光長寂寞，滿朝官職獨蹉跎。","亦知合被才名折，二十三年折太多。"]', '["爲我引桮添酒饮，與君把箸擊盤歌。","诗稱国手徒爲爾，命壓人头不奈何。","舉眼风光长寂寞，满朝官職独蹉跎。","亦知合被才名折，二十三年折太多。"]', '诗', 'shi', '', NULL, '醉贈劉二十八使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fc8638d-63e2-40c6-85b6-47187c4f3920', '太湖石', '太湖石', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙翠三秋色，波濤萬古痕。","削成青玉片，截斷碧雲根。","風氣通巖穴，苔文護洞門。","三峰具體小，應是華山孫。"]', '["煙翠三秋色，波濤万古痕。","削成青玉片，截斷碧云根。","风氣通巖穴，苔文護洞门。","三峰具體小，應是华山孫。"]', '诗', 'shi', '', NULL, '太湖石 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84dbbb20-092f-4c3e-b2a6-02bf679895bb', '過敷水', '過敷水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["垂鞭欲渡羅敷水，處分鳴騶且緩驅。","秦氏雙蛾久冥漠，蘇臺五馬尚踟躕。","村童店女仰頭笑，今日使君真是愚。"]', '["垂鞭欲渡羅敷水，处分鳴騶且緩驱。","秦氏雙蛾久冥漠，蘇台五马尚踟躕。","村童店女仰头笑，今日使君真是愚。"]', '诗', 'shi', '', NULL, '過敷水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c44a5f-e66a-46a7-9085-e82845005c3a', '南院', '南院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["林院無情緒，經春不一開。","楊花飛作穗，榆莢落成堆。","壯氣從中減，流年逐後催。","只應如過客，病去老迎來。"]', '["林院無情緒，經春不一开。","楊花飞作穗，榆莢落成堆。","壯氣從中減，流年逐後催。","只應如過客，病去老迎来。"]', '诗', 'shi', '', NULL, '南院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('803526d9-c6e4-4554-a31f-f5dd186c0fdc', '閑詠', '闲詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["步月憐清景，眠松愛綠陰。","早年詩思苦，晚歲道情深。","夜學禪多坐，秋牽興暫吟。","悠然兩事外，無處更留心。"]', '["步月怜清景，眠松愛綠陰。","早年诗思苦，晚歲道情深。","夜学禪多坐，秋牽兴暫吟。","悠然兩事外，無处更留心。"]', '诗', 'shi', '', NULL, '閑詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d467148-f86d-4284-b6d8-1e9179276490', '初授祕監拜賜金紫閑吟小酌偶寫所懷', '初授祕監拜賜金紫闲吟小酌偶寫所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫袍新祕監，白首舊書生。","鬢雪人間壽，腰金世上榮。","子孫無可念，產業不能營。","酒引眼前興，詩留身後名。","閑傾三數酌，醉詠十餘聲。","便是羲皇代，先從心太平。"]', '["紫袍新祕監，白首旧书生。","鬢雪人间壽，腰金世上榮。","子孫無可念，產業不能營。","酒引眼前兴，诗留身後名。","闲傾三數酌，醉詠十餘声。","便是羲皇代，先從心太平。"]', '诗', 'shi', '', NULL, '初授祕監拜賜金紫閑吟小酌偶寫所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d056283-9fea-4573-83ae-e70205d683b0', '新昌閑居招楊郎中兄弟', '新昌闲居招楊郎中兄弟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紗巾角枕病眠翁，忙少閑多誰與同。","但有雙松當砌下，更無一事到心中。","金章紫綬堪如夢，皂蓋朱輪別似空。","暑月貧家何所有，客來唯贈北窗風。"]', '["紗巾角枕病眠翁，忙少闲多誰與同。","但有雙松當砌下，更無一事到心中。","金章紫綬堪如梦，皂蓋朱輪別似空。","暑月貧家何所有，客来唯贈北窗风。"]', '诗', 'shi', '', NULL, '新昌閑居招楊郎中兄弟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c30a404-2221-46e5-9c57-2d0943d205be', '祕省後廳', '祕省後廳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["槐花雨潤新秋地，桐葉風翻欲夜天。","盡日後廳無一事，白頭老監枕書眠。"]', '["槐花雨潤新秋地，桐葉风翻欲夜天。","尽日後廳無一事，白头老監枕书眠。"]', '诗', 'shi', '', NULL, '祕省後廳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7359627-a02c-4f97-a53a-65ff5b203f7f', '松齋偶興', '松斋偶兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["置心思慮外，滅跡是非間。","約俸爲生計，隨官換往還。","耳煩聞曉角，眼醒見秋山。","賴此松簷下，朝回半日閑。"]', '["置心思慮外，滅跡是非间。","約俸爲生計，隨官換往還。","耳煩闻晓角，眼醒见秋山。","賴此松簷下，朝回半日闲。"]', '诗', 'shi', '', NULL, '松齋偶興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9973b5a9-2259-428d-8d11-9bf2368a32e9', '和楊郎中賀楊僕射致仕後楊侍郎門生合宴席上作', '和楊郎中賀楊僕射致仕後楊侍郎门生合宴席上作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["業重關西繼大名，恩深闕下遂高情。","祥鱣降伴趨庭鯉，賀燕飛和出谷鶯。","范蠡舟中無子弟，疏家席上欠門生。","可憐玉樹連桃李，從古無如此會榮。"]', '["業重关西繼大名，恩深闕下遂高情。","祥鱣降伴趨庭鯉，賀燕飞和出谷鶯。","范蠡舟中無子弟，疏家席上欠门生。","可怜玉樹連桃李，從古無如此會榮。"]', '诗', 'shi', '', NULL, '和楊郎中賀楊僕射致仕後楊侍郎門生合宴席上作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef85d9e5-cbed-49aa-985e-9480b353bd50', '松下琴贈客', '松下琴贈客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["松寂風初定，琴清夜欲闌。","偶因羣動息，試撥一聲看。","寡鶴當徽怨，秋泉應指寒。","慙君此傾聽，本不爲君彈。"]', '["松寂风初定，琴清夜欲闌。","偶因羣动息，試撥一声看。","寡鹤當徽怨，秋泉應指寒。","慙君此傾听，本不爲君彈。"]', '诗', 'shi', '', NULL, '松下琴贈客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5efa7d4e-3180-4887-8aa1-8da52f29a26a', '秋齋', '秋斋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晨起秋齋冷，蕭條稱病容。","清風兩窗竹，白露一庭松。","阮籍謀身拙，嵇康向事慵。","生涯別有處，浩氣在心胸。"]', '["晨起秋斋冷，蕭條稱病容。","清风兩窗竹，白露一庭松。","阮籍謀身拙，嵇康向事慵。","生涯別有处，浩氣在心胸。"]', '诗', 'shi', '', NULL, '秋齋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56a74c85-c6ad-4130-9f96-89636456321b', '塗山寺獨遊', '塗山寺独游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["野徑行無伴，僧房宿有期。","塗山來去熟，唯是馬蹄知。"]', '["野徑行無伴，僧房宿有期。","塗山来去熟，唯是马蹄知。"]', '诗', 'shi', '', NULL, '塗山寺獨遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca944a08-1785-4bfb-b2da-fde0d7409057', '登觀音臺望城', '登观音台望城', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百千家似圍棊局，十二街如種菜畦。","遙認微微入朝火，一條星宿五門西。"]', '["百千家似圍棊局，十二街如種菜畦。","遙認微微入朝火，一條星宿五门西。"]', '诗', 'shi', '', NULL, '登觀音臺望城 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcf9d915-4c5e-4abc-8999-82681aa05704', '登靈應臺北望', '登靈應台北望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臨高始見人寰小，對遠方知色界空。","回首却歸朝市去，一稊米落太倉中。"]', '["臨高始见人寰小，对远方知色界空。","回首却归朝市去，一稊米落太倉中。"]', '诗', 'shi', '', NULL, '登靈應臺北望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('586543b7-3cd8-4f80-a0a6-a73f9f5e600d', '酬裴相公題興化小池見招長句', '酬裴相公題兴化小池见招长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爲愛小塘招散客，不嫌老監與新詩。","山公倒載無妨學，范蠡扁舟未要追。","蓬斷偶飄桃李徑，鷗驚誤拂鳳皇池。","敢辭課拙詶高韻，一勺爭禁萬頃陂。"]', '["爲愛小塘招散客，不嫌老監與新诗。","山公倒載無妨学，范蠡扁舟未要追。","蓬斷偶飄桃李徑，鷗驚誤拂鳳皇池。","敢辞課拙詶高韻，一勺爭禁万頃陂。"]', '诗', 'shi', '', NULL, '酬裴相公題興化小池見招長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56a12f40-2367-4944-8517-cdb25e866824', '閑行', '闲行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五十年來思慮熟，忙人應未勝閑人。","林園傲逸真成貴，衣食單疎不是貧。","專掌圖書無過地，遍尋山水自由身。","儻年七十猶強健，尚得閑行十五春。"]', '["五十年来思慮熟，忙人應未勝闲人。","林园傲逸真成貴，衣食單疎不是貧。","專掌圖书無過地，遍尋山水自由身。","儻年七十猶強健，尚得闲行十五春。"]', '诗', 'shi', '', NULL, '閑行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ad301dc-138a-4f6f-94b8-cc8a72153869', '閑出', '闲出', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["兀兀出門何處去，新昌街晚樹陰斜。","馬蹄知意緣行熟，不向楊家即庾家。"]', '["兀兀出门何处去，新昌街晚樹陰斜。","马蹄知意緣行熟，不向楊家即庾家。"]', '诗', 'shi', '', NULL, '閑出 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb1b2bc7-a921-4bc8-a82a-db73e4ebba43', '與僧智如夜話', '與僧智如夜話', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嬾鈍尤知命，幽棲漸得朋。","門閑無謁客，室靜有禪僧。","爐向初冬火，籠停半夜燈。","憂勞緣智巧，自喜百無能。"]', '["嬾鈍尤知命，幽棲漸得朋。","门闲無謁客，室静有禪僧。","爐向初冬火，籠停半夜灯。","憂勞緣智巧，自喜百無能。"]', '诗', 'shi', '', NULL, '與僧智如夜話 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('218851e4-3dfa-4718-ab14-441c5ea4bab5', '憶廬山舊隱及洛下新居', '憶廬山旧隐及洛下新居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["形骸僶俛班行內，骨肉句留俸祿中。","無奈攀緣隨手長，亦知恩愛到頭空。","草堂久閉廬山下，竹院新拋洛水東。","自是未能歸去得，世間誰要白鬚翁。"]', '["形骸僶俛班行內，骨肉句留俸祿中。","無奈攀緣隨手长，亦知恩愛到头空。","草堂久閉廬山下，竹院新拋洛水东。","自是未能归去得，世间誰要白鬚翁。"]', '诗', 'shi', '', NULL, '憶廬山舊隱及洛下新居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9334bcd-0f9d-4a87-b260-3383a5590d16', '晚寒', '晚寒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["急景流如箭，淒風利似刀。","暝催雞翅歛，寒束樹枝高。","縮水濃和酒，加緜厚絮袍。","可憐冬計畢，煖臥醉陶陶。"]', '["急景流如箭，淒风利似刀。","暝催雞翅歛，寒束樹枝高。","縮水濃和酒，加緜厚絮袍。","可怜冬計畢，煖臥醉陶陶。"]', '诗', 'shi', '', NULL, '晚寒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcabf7d5-1aa0-4058-90d2-b8afc60c3aaf', '偶眠', '偶眠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["放桮書案上，枕臂火爐前。","老愛尋思事，慵多取次眠。","妻教卸烏帽，婢與展青氊。","便是屏風樣，何勞畫古賢。"]', '["放桮书案上，枕臂火爐前。","老愛尋思事，慵多取次眠。","妻教卸烏帽，婢與展青氊。","便是屏风樣，何勞畫古賢。"]', '诗', 'shi', '', NULL, '偶眠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2eb7a4-bb2d-464b-9cc2-1c0fde1276d9', '華城西北雉堞最高崔相公首創樓臺錢左丞繼種花果合爲勝境題在雅篇歲暮獨遊悵然成詠', '华城西北雉堞最高崔相公首創楼台錢左丞繼種花果合爲勝境題在雅篇歲暮独游悵然成詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高居稱君子，瀟灑四無鄰。","丞相棟梁久，使君桃李新。","凝情看麗句，駐步想清塵。","況是寒天客，樓空無主人。"]', '["高居稱君子，瀟灑四無鄰。","丞相棟梁久，使君桃李新。","凝情看丽句，駐步想清塵。","況是寒天客，楼空無主人。"]', '诗', 'shi', '', NULL, '華城西北雉堞最高崔相公首創樓臺錢左丞繼種花果合爲勝境題在雅篇歲暮獨遊悵然成詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95073e67-d7f7-4f11-ae5c-fca43d84ddcd', '奉使途中戲贈張常侍', '奉使途中戲贈張常侍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早風吹土滿長衢，驛騎星軺盡疾驅。","共笑籃舁亦稱使，日馳一驛向東都。"]', '["早风吹土满长衢，驛騎星軺尽疾驱。","共笑籃舁亦稱使，日驰一驛向东都。"]', '诗', 'shi', '', NULL, '奉使途中戲贈張常侍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77360386-2190-4ca0-93be-60bc18e5f57d', '有小白馬乘馭多時奉使東行至稠桑驛溘然而斃足可驚傷不能忘情題二十韻', '有小白马乘馭多时奉使东行至稠桑驛溘然而斃足可驚傷不能忘情題二十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["能驟復能馳，翩翩白馬兒。","毛寒一團雪，鬃薄萬條絲。","皁蓋春行日，驪駒曉從時。","雙旌前獨步，五馬內偏騎。","芳草承蹄葉，垂楊拂頂枝。","跨將迎好客，惜不換妖姬。","慢鞚遊蕭寺，閑驅醉習池。","睡來乘作夢，興發倚成詩。","鞭爲馴難下，鞍緣穩不離。","北歸還共到，東使亦相隨。","赭白何曾變，玄黃豈得知。","嘶風覺聲急，蹋雪怪行遲。","昨夜猶芻秣，今朝尚縶維。","臥槽應不起，顧主遂長辭。","塵滅駸駸迹，霜留皎皎姿。","度關形未改，過隙影難追。","念倍燕求駿，情深項別騅。","銀收鉤臆帶，金卸絡頭羈。","何處埋奇骨，誰家覓弊帷。","稠桑驛門外，吟罷涕雙垂。"]', '["能驟复能驰，翩翩白马兒。","毛寒一團雪，鬃薄万條絲。","皁蓋春行日，驪駒晓從时。","雙旌前独步，五马內偏騎。","芳草承蹄葉，垂楊拂頂枝。","跨將迎好客，惜不換妖姬。","慢鞚游蕭寺，闲驱醉習池。","睡来乘作梦，兴發倚成诗。","鞭爲馴难下，鞍緣穩不離。","北归還共到，东使亦相隨。","赭白何曾变，玄黄豈得知。","嘶风覺声急，蹋雪怪行遲。","昨夜猶芻秣，今朝尚縶維。","臥槽應不起，顧主遂长辞。","塵滅駸駸迹，霜留皎皎姿。","度关形未改，過隙影难追。","念倍燕求駿，情深項別騅。","銀收鉤臆带，金卸絡头羈。","何处埋奇骨，誰家覓弊帷。","稠桑驛门外，吟罷涕雙垂。"]', '诗', 'shi', '', NULL, '有小白馬乘馭多時奉使東行至稠桑驛溘然而斃足可驚傷不能忘情題二十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('795565b9-d424-4054-a14c-50db84ea637f', '題噴玉泉', '題噴玉泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["泉噴聲如玉，潭澄色似空。","練垂青嶂上，珠瀉綠盆中。","溜滴三秋雨，寒生六月風。","何時此岩下，來作濯纓翁。"]', '["泉噴声如玉，潭澄色似空。","練垂青嶂上，珠瀉綠盆中。","溜滴三秋雨，寒生六月风。","何时此岩下，来作濯纓翁。"]', '诗', 'shi', '', NULL, '題噴玉泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f66e17bf-07e1-4049-9e77-b44bb8c693ad', '酬皇甫賓客', '酬皇甫賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑官兼慢使，著處易停輪。","況欲逢新歲，仍初見故人。","冒寒尋到洛，待煖始歸秦。","亦擬同攜手，城東畧看春。"]', '["闲官兼慢使，著处易停輪。","況欲逢新歲，仍初见故人。","冒寒尋到洛，待煖始归秦。","亦擬同携手，城东畧看春。"]', '诗', 'shi', '', NULL, '酬皇甫賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3800c4bf-825d-4a24-b998-939c301a89af', '種白蓮', '種白蓮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吳中白藕洛中栽，莫戀江南花嬾開。","萬里攜歸爾知否，紅蕉朱槿不將來。"]', '["吳中白藕洛中栽，莫戀江南花嬾开。","万里携归爾知否，紅蕉朱槿不將来。"]', '诗', 'shi', '', NULL, '種白蓮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('506a9d4f-b70e-4de1-b7d7-d8d7b21851ea', '答蘇庶子', '答蘇庶子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["偶作關東使，重陪洛下遊。","病來從斷酒，老去可禁愁。","款曲偏青眼，蹉跎各白頭。","蓬山閑氣味，依約似龍樓。"]', '["偶作关东使，重陪洛下游。","病来從斷酒，老去可禁愁。","款曲偏青眼，蹉跎各白头。","蓬山闲氣味，依約似龙楼。"]', '诗', 'shi', '', NULL, '答蘇庶子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2dc9881-1139-4d03-a140-ca96daf47fa0', '答尉遲少監水閣重宴', '答尉遲少監水閣重宴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人情依舊歲華新，今日重招往日賓。","雞黍重回千里駕，林園闇換四年春。","水軒平寫琉璃鏡，草岸斜鋪翡翠茵。","聞道經營費心力，忍教成後屬他人。"]', '["人情依旧歲华新，今日重招往日賓。","雞黍重回千里駕，林园闇換四年春。","水軒平寫琉璃镜，草岸斜鋪翡翠茵。","闻道經營費心力，忍教成後屬他人。"]', '诗', 'shi', '', NULL, '答尉遲少監水閣重宴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0231df-73c6-432d-bf03-444aaa8e6df7', '和劉郎中傷鄂姬', '和劉郎中傷鄂姬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不獨君嗟我亦嗟，西風北雪殺南花。","不知月夜魂歸處，鸚鵡洲頭第幾家。"]', '["不独君嗟我亦嗟，西风北雪殺南花。","不知月夜魂归处，鸚鵡洲头第幾家。"]', '诗', 'shi', '', NULL, '和劉郎中傷鄂姬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a20ea2d-6ce9-42aa-a559-f171f53d4779', '贈東鄰王十三', '贈东鄰王十三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["攜手池邊月，開襟竹下風。","驅愁知酒力，破睡見茶功。","居處東西接，年顏老少同。","能來爲伴否，伊上作漁翁。"]', '["携手池邊月，开襟竹下风。","驱愁知酒力，破睡见茶功。","居处东西接，年顏老少同。","能来爲伴否，伊上作漁翁。"]', '诗', 'shi', '', NULL, '贈東鄰王十三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c3bbdb6-8f97-4a83-9a24-db9b4e9535b6', '早春同劉郎中寄宣武令狐相公', '早春同劉郎中寄宣武令狐相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["梁園不到一年強，遙想清吟對綠觴。","更有何人能飲酌，新添幾卷好篇章。","馬頭拂柳時回轡，豹尾穿花暫亞槍。","誰引相公開口笑，不逢白監與劉郎。"]', '["梁园不到一年強，遙想清吟对綠觴。","更有何人能饮酌，新添幾卷好篇章。","马头拂柳时回轡，豹尾穿花暫亞槍。","誰引相公开口笑，不逢白監與劉郎。"]', '诗', 'shi', '', NULL, '早春同劉郎中寄宣武令狐相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fded530-0634-4d30-9ee0-6a126d3473d8', '寄太原李相公', '寄太原李相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞道北都今一變，政和軍樂萬人安。","綺羅二八圍賓榻，組練三千夾將壇。","蟬鬢應誇丞相少，貂裘不覺太原寒。","世間大有虛榮貴，百歲無君一日歡。"]', '["闻道北都今一变，政和軍乐万人安。","綺羅二八圍賓榻，組練三千夾將壇。","蟬鬢應誇丞相少，貂裘不覺太原寒。","世间大有虛榮貴，百歲無君一日歡。"]', '诗', 'shi', '', NULL, '寄太原李相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e5af8b2-142c-4c56-8729-413b9cbd438f', '雪中寄令狐相公兼呈夢得', '雪中寄令狐相公兼呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["兔園春雪梁王會，想對金罍詠玉塵。","今日相如身在此，不知客右坐何人。"]', '["兔园春雪梁王會，想对金罍詠玉塵。","今日相如身在此，不知客右坐何人。"]', '诗', 'shi', '', NULL, '雪中寄令狐相公兼呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1192b8fe-60b3-4781-a068-0180e48f78b7', '出使在途所騎馬死改乘肩轝將歸長安偶詠旅懷寄太原李相公', '出使在途所騎马死改乘肩轝將归长安偶詠旅懷寄太原李相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["驛路崎嶇泥雪寒，欲登籃轝一長嘆。","風光不見桃花騎，塵土空留杏葉鞍。","喪乘獨歸殊不易，脫驂相贈豈爲難。","幷州好馬應無數，不怕旌旄試覓看。"]', '["驛路崎嶇泥雪寒，欲登籃轝一长嘆。","风光不见桃花騎，塵土空留杏葉鞍。","喪乘独归殊不易，脫驂相贈豈爲难。","幷州好马應無數，不怕旌旄試覓看。"]', '诗', 'shi', '', NULL, '出使在途所騎馬死改乘肩轝將歸長安偶詠旅懷寄太原李相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ccfdb12-ebda-4aab-aa04-d7d4596b6daa', '有雙鶴留在洛中忽見劉郎中依然鳴顧劉因爲鶴嘆二篇寄予予以二絕句答之 一', '有雙鹤留在洛中忽见劉郎中依然鳴顧劉因爲鹤嘆二篇寄予予以二絕句答之 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["辭鄉遠隔華亭水，逐我來棲緱嶺雲。","慚媿稻粱長不飽，未曾回眼向雞羣。"]', '["辞乡远隔华亭水，逐我来棲緱嶺云。","慚媿稻粱长不飽，未曾回眼向雞羣。"]', '诗', 'shi', '', NULL, '有雙鶴留在洛中忽見劉郎中依然鳴顧劉因爲鶴嘆二篇寄予予以二絕句答之 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d19277-9ac9-49eb-82da-b0cbb36008f8', '有雙鶴留在洛中忽見劉郎中依然鳴顧劉因爲鶴嘆二篇寄予予以二絕句答之 二', '有雙鹤留在洛中忽见劉郎中依然鳴顧劉因爲鹤嘆二篇寄予予以二絕句答之 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["荒草院中池水畔，銜恩不去又經春。","見君驚喜雙回顧，應爲吟聲似主人。"]', '["荒草院中池水畔，銜恩不去又經春。","见君驚喜雙回顧，應爲吟声似主人。"]', '诗', 'shi', '', NULL, '有雙鶴留在洛中忽見劉郎中依然鳴顧劉因爲鶴嘆二篇寄予予以二絕句答之 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11bafd22-27c4-463f-81f4-a6215439b2cf', '宿竇使君莊水亭', '宿竇使君莊水亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["使君何在在江東，池柳初黃杏欲紅。","有興即來閑便宿，不知誰是主人翁。"]', '["使君何在在江东，池柳初黄杏欲紅。","有兴即来闲便宿，不知誰是主人翁。"]', '诗', 'shi', '', NULL, '宿竇使君莊水亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a14046d-0356-4329-a8b6-ea3118c62f3e', '龍門下作', '龙门下作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["龍門澗下濯塵纓，擬作閑人過此生。","筋力不將諸處用，登山臨水詠詩行。"]', '["龙门澗下濯塵纓，擬作闲人過此生。","筋力不將諸处用，登山臨水詠诗行。"]', '诗', 'shi', '', NULL, '龍門下作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03af1258-83a1-4fcf-9ef0-824b1daa7f8c', '姚侍御見過戲贈', '姚侍御见過戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚起春寒慵裹頭，客來池上偶同遊。","東臺御史多提舉，莫按金章繫布裘。"]', '["晚起春寒慵裹头，客来池上偶同游。","东台御史多提舉，莫按金章繫布裘。"]', '诗', 'shi', '', NULL, '姚侍御見過戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26dc88d1-5f07-423c-8bae-bbc4c85da786', '履道春居', '履道春居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["微雨灑園林，新晴好一尋。","低風洗池面，斜日拆花心。","暝助嵐陰重，春添水色深。","不如陶省事，猶抱有弦琴。"]', '["微雨灑园林，新晴好一尋。","低风洗池面，斜日拆花心。","暝助嵐陰重，春添水色深。","不如陶省事，猶抱有弦琴。"]', '诗', 'shi', '', NULL, '履道春居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a50dd611-acce-4f90-ba58-7e298b93771f', '題洛中第宅', '題洛中第宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水木誰家宅，門高占地寬。","懸魚挂青甃，行馬護朱欄。","春榭籠煙煖，秋庭鎖月寒。","松膠黏琥珀，筠粉撲琅玕。","試問池臺主，多爲將相官。","終身不曾到，唯展宅圖看。"]', '["水木誰家宅，门高占地寬。","懸鱼挂青甃，行马護朱欄。","春榭籠煙煖，秋庭鎖月寒。","松膠黏琥珀，筠粉撲琅玕。","試问池台主，多爲將相官。","終身不曾到，唯展宅圖看。"]', '诗', 'shi', '', NULL, '題洛中第宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c80000-9ca1-450e-b23f-2a4b5d8e0129', '寄殷協律', '寄殷協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五歲優游同過日，一朝消散[似]浮雲。","琴詩酒伴皆拋我，雪月花時最憶君。","幾度聽雞歌白日，亦曾騎馬詠紅裙。","吳娘暮雨蕭蕭曲，自別江南更不聞。"]', '["五歲優游同過日，一朝消散[似]浮云。","琴诗酒伴皆拋我，雪月花时最憶君。","幾度听雞歌白日，亦曾騎马詠紅裙。","吳娘暮雨蕭蕭曲，自別江南更不闻。"]', '诗', 'shi', '', NULL, '寄殷協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc250d91-d362-4621-baf4-63304f5e0f44', '洛下諸客就宅相送偶題西亭', '洛下諸客就宅相送偶題西亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["几榻臨池坐，軒車冒雪過。","交親致桮酒，僮僕解笙歌。","流歲行將晚，浮榮得幾多。","林泉應問我，不住意如何。"]', '["几榻臨池坐，軒车冒雪過。","交親致桮酒，僮僕解笙歌。","流歲行將晚，浮榮得幾多。","林泉應问我，不住意如何。"]', '诗', 'shi', '', NULL, '洛下諸客就宅相送偶題西亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2d57649-22a8-4dd5-9633-d2d2df843ca4', '答林泉', '答林泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["好住舊林泉，回頭一悵然。","漸知吾潦倒，深愧爾留連。","欲作棲雲計，須營種黍錢。","更容求一郡，不得亦歸田。"]', '["好住旧林泉，回头一悵然。","漸知吾潦倒，深愧爾留連。","欲作棲云計，須營種黍錢。","更容求一郡，不得亦归田。"]', '诗', 'shi', '', NULL, '答林泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812f82fd-b61b-4190-969b-30413308faa7', '將發洛中枉令狐相公手札兼辱二篇寵行以長句答之', '將發洛中枉令狐相公手札兼辱二篇寵行以长句答之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["尺素忽驚來梓澤，雙金不惜送蓬山。","八行落泊飛雲雨，五字鎗鏦動珮環。","玉韻乍聽堪醒酒，銀鉤細讀當披顏。","收藏便作終身寶，何啻三年懷袖間。"]', '["尺素忽驚来梓澤，雙金不惜送蓬山。","八行落泊飞云雨，五字鎗鏦动珮环。","玉韻乍听堪醒酒，銀鉤細读當披顏。","收藏便作終身寶，何啻三年懷袖间。"]', '诗', 'shi', '', NULL, '將發洛中枉令狐相公手札兼辱二篇寵行以長句答之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5585e4e6-6526-45c0-bd38-e79693ee4c95', '臨都驛答夢得六言二首 一', '臨都驛答梦得六言二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["揚子津頭月下，臨都驛裏燈前。","昨日老於前日，去年春似今年。"]', '["揚子津头月下，臨都驛裏灯前。","昨日老於前日，去年春似今年。"]', '诗', 'shi', '', NULL, '臨都驛答夢得六言二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f3391c1-8a9f-432f-9edf-1e70ffb08683', '臨都驛答夢得六言二首 二', '臨都驛答梦得六言二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謝守歸爲秘監，馮公老作郎官。","前事不須問著，新詩且更吟看。"]', '["謝守归爲秘監，馮公老作郎官。","前事不須问著，新诗且更吟看。"]', '诗', 'shi', '', NULL, '臨都驛答夢得六言二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aa3def9-8feb-467b-9f28-84df62f0c714', '喜錢左丞再除華州以詩伸賀', '喜錢左丞再除华州以诗伸賀', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["左轄輟中臺，門東委上才。","彤襜經宿到，絳帳及春開。","民望懇難奪，天心慈易回。","那知不隔歲，重借寇恂來。"]', '["左轄輟中台，门东委上才。","彤襜經宿到，絳帳及春开。","民望懇难奪，天心慈易回。","那知不隔歲，重借寇恂来。"]', '诗', 'shi', '', NULL, '喜錢左丞再除華州以詩伸賀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f58d8266-4dbc-4e59-80a9-db04811a2de9', '和錢華州題少華清光絕句', '和錢华州題少华清光絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高情雅韻三峯守，主領清光管白雲。","自笑亦曾爲刺史，蘇州肥膩不如君。"]', '["高情雅韻三峯守，主領清光管白云。","自笑亦曾爲刺史，蘇州肥膩不如君。"]', '诗', 'shi', '', NULL, '和錢華州題少華清光絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53dd60a6-c37e-4b00-9f98-19662889c8fc', '送陝府王大夫', '送陝府王大夫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金馬門前回劒珮，鐵牛城下擁旌旗。","他時萬一爲交代，留取甘棠三兩枝。"]', '["金马门前回劒珮，鐵牛城下擁旌旗。","他时万一爲交代，留取甘棠三兩枝。"]', '诗', 'shi', '', NULL, '送陝府王大夫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54abc77f-ac71-4825-93c7-c155b27dff0f', '代迎春花招劉郎中', '代迎春花招劉郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["幸與松筠相近栽，不隨桃李一時開。","杏園豈敢妨君去，未有花時且看來。"]', '["幸與松筠相近栽，不隨桃李一时开。","杏园豈敢妨君去，未有花时且看来。"]', '诗', 'shi', '', NULL, '代迎春花招劉郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b62f2238-14f3-41a1-910a-a52266d15ea6', '翫迎春花贈楊郎中', '翫迎春花贈楊郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金英翠萼帶春寒，黃色花中有幾般。","憑君與向遊人道，莫作蔓菁花眼看。"]', '["金英翠萼带春寒，黄色花中有幾般。","憑君與向游人道，莫作蔓菁花眼看。"]', '诗', 'shi', '', NULL, '翫迎春花贈楊郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e573bdad-7b86-47f5-aeed-2edaf512967b', '閑出', '闲出', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身外無羈束，心中少是非。","被花留便住，逢酒醉方歸。","人事行時少，官曹入日稀。","春寒遊正好，穩馬薄綿衣。"]', '["身外無羈束，心中少是非。","被花留便住，逢酒醉方归。","人事行时少，官曹入日稀。","春寒游正好，穩马薄綿衣。"]', '诗', 'shi', '', NULL, '閑出 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e15c462-6977-474d-b4c9-d81e7225d8a3', '座上贈盧判官', '座上贈盧判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["把酒承花花落頻，花香酒味相和春。","莫言不是江南會，虛白亭中舊主人。"]', '["把酒承花花落頻，花香酒味相和春。","莫言不是江南會，虛白亭中旧主人。"]', '诗', 'shi', '', NULL, '座上贈盧判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e698becc-27d1-481c-ba5c-8ec131c898cc', '曲江有感', '曲江有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曲江西岸又春風，萬樹花前一老翁。","遇酒逢花還且醉，若論惆悵事何窮。"]', '["曲江西岸又春风，万樹花前一老翁。","遇酒逢花還且醉，若論惆悵事何窮。"]', '诗', 'shi', '', NULL, '曲江有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf9ad6f4-368b-40e2-bbbc-87d48674cc2c', '杏園花下贈劉郎中', '杏园花下贈劉郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["怪君把酒偏惆悵，曾是貞元花下人。","自別花來多少事，東風二十四回春。"]', '["怪君把酒偏惆悵，曾是貞元花下人。","自別花来多少事，东风二十四回春。"]', '诗', 'shi', '', NULL, '杏園花下贈劉郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fe915c6-5d52-4177-b90e-2b6875275b61', '花前有感兼呈崔相公劉郎中', '花前有感兼呈崔相公劉郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["落花如雪鬢如霜，醉把花看益自傷。","少日爲名多檢束，長年無興可顛狂。","四時輪轉春常少，百刻支分夜苦長。","何事同生壬子歲，老於崔相及劉郎。"]', '["落花如雪鬢如霜，醉把花看益自傷。","少日爲名多檢束，长年無兴可顛狂。","四时輪轉春常少，百刻支分夜苦长。","何事同生壬子歲，老於崔相及劉郎。"]', '诗', 'shi', '', NULL, '花前有感兼呈崔相公劉郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c92f757e-b30f-45cc-856f-30e3c4600f9a', '微之就拜尚書居易續除刑部因書賀意兼詠離懷', '微之就拜尚书居易續除刑部因书賀意兼詠離懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我爲憲部入南宮，君作尚書鎮浙東。","老去一時成白首，別來七度換春風。","簪纓假合虛名在，筋力銷磨實事空。","遠地官高親故少，些些談笑與誰同。"]', '["我爲憲部入南宮，君作尚书鎮浙东。","老去一时成白首，別来七度換春风。","簪纓假合虛名在，筋力銷磨實事空。","远地官高親故少，些些談笑與誰同。"]', '诗', 'shi', '', NULL, '微之就拜尚書居易續除刑部因書賀意兼詠離懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da239ce5-f95e-4ad5-a95a-5d33163d4cf1', '喜與韋左丞同入南省因敘舊以贈之', '喜與韋左丞同入南省因敘旧以贈之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早年同遇陶鈞主，利鈍精粗共在鎔。","金劒淬來長透匣，鉛刀磨盡不成鋒。","差肩北省慙非據，接武南宮幸再容。","跛鼈雖遲騏驥疾，何妨中路亦相逢。"]', '["早年同遇陶鈞主，利鈍精粗共在鎔。","金劒淬来长透匣，鉛刀磨尽不成鋒。","差肩北省慙非據，接武南宮幸再容。","跛鼈雖遲騏驥疾，何妨中路亦相逢。"]', '诗', 'shi', '', NULL, '喜與韋左丞同入南省因敘舊以贈之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2240af-d21e-4adc-bbb0-8c020cc5ee4c', '伊州', '伊州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老去將何散老愁，新教小玉唱伊州。","亦應不得多年聽，未教成時已白頭。"]', '["老去將何散老愁，新教小玉唱伊州。","亦應不得多年听，未教成时已白头。"]', '诗', 'shi', '', NULL, '伊州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68170055-ffba-441c-b198-c9de18ca237c', '早朝', '早朝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鼓動出新昌，雞鳴赴建章。","翩翩穩鞍馬，楚楚健衣裳。","宮漏傳殘夜，城陰送早涼。","月堤槐露氣，風燭樺煙香。","雙闕龍相對，千官雁一行。","漢庭方尚少，慙嘆鬢如霜。"]', '["鼓动出新昌，雞鳴赴建章。","翩翩穩鞍马，楚楚健衣裳。","宮漏傳殘夜，城陰送早涼。","月堤槐露氣，风燭樺煙香。","雙闕龙相对，千官雁一行。","漢庭方尚少，慙嘆鬢如霜。"]', '诗', 'shi', '', NULL, '早朝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e1cb68b-0d05-44e8-a92d-90e8d6ace1f3', '答裴相公乞鶴', '答裴相公乞鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["警露聲音好，沖天相貌殊。","終宜向遼廓，不稱在泥塗。","白首勞爲伴，朱門幸見呼。","不知疎野性，解愛鳳池無。"]', '["警露声音好，沖天相貌殊。","終宜向遼廓，不稱在泥塗。","白首勞爲伴，朱门幸见呼。","不知疎野性，解愛鳳池無。"]', '诗', 'shi', '', NULL, '答裴相公乞鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad0697af-2d57-4cb0-9ea7-420fb785d806', '晚從省歸', '晚從省归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝回北闕值清晨，晚出南宮送暮春。","入去丞郎非散秩，歸來詩酒是閑人。","猶思泉石多成夢，尚嘆簪裾未離身。","終是不如山下去，心頭眼底兩無塵。"]', '["朝回北闕值清晨，晚出南宮送暮春。","入去丞郎非散秩，归来诗酒是闲人。","猶思泉石多成梦，尚嘆簪裾未離身。","終是不如山下去，心头眼底兩無塵。"]', '诗', 'shi', '', NULL, '晚從省歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e961dc36-ff3f-4c04-89e7-ade8ec9c01f8', '北窗閑坐', '北窗闲坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["虛窗兩叢竹，靜室一爐香。","門外紅塵合，城中白日忙。","無煩尋道士，不要學仙方。","自有延年術，心閑歲月長。"]', '["虛窗兩叢竹，静室一爐香。","门外紅塵合，城中白日忙。","無煩尋道士，不要学仙方。","自有延年術，心闲歲月长。"]', '诗', 'shi', '', NULL, '北窗閑坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c49022b6-74af-46c2-8863-890e95922651', '酬嚴給事', '酬嚴給事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嬴女偷乘鳳去時，洞中潛歇弄瓊枝。","不緣啼鳥春饒舌，青瑣仙郎可得知。"]', '["嬴女偷乘鳳去时，洞中潛歇弄瓊枝。","不緣啼鸟春饒舌，青瑣仙郎可得知。"]', '诗', 'shi', '', NULL, '酬嚴給事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3d685c7-9217-4776-b9d3-412ae6b2a05a', '京路', '京路', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西來爲看秦山雪，東去緣尋洛苑春。","來去騰騰兩京路，閑行除我更無人。"]', '["西来爲看秦山雪，东去緣尋洛苑春。","来去腾腾兩京路，闲行除我更無人。"]', '诗', 'shi', '', NULL, '京路 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9680c3f4-d5b3-430d-ae79-2bb35e5ac83a', '華州西', '华州西', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["每逢人靜慵多歇，不計程行困即眠。","上得籃轝未能去，春風敷水店門前。"]', '["每逢人静慵多歇，不計程行困即眠。","上得籃轝未能去，春风敷水店门前。"]', '诗', 'shi', '', NULL, '華州西 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e568379-777b-4eea-8aa5-44f65a4ec62d', '從陝至東京', '從陝至东京', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["從陝至東京，山低路漸平。","風光四百里，車馬十三程。","花共垂鞭看，桮多並轡傾。","笙歌與談笑，隨分自將行。"]', '["從陝至东京，山低路漸平。","风光四百里，车马十三程。","花共垂鞭看，桮多並轡傾。","笙歌與談笑，隨分自將行。"]', '诗', 'shi', '', NULL, '從陝至東京 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dcf2049-139c-4649-91dd-1b1d25c04e5d', '送春', '送春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["銀花鑿落從君勸，金屑琵琶爲我彈。","不獨送春兼送老，更嘗一着更聽看。"]', '["銀花鑿落從君勸，金屑琵琶爲我彈。","不独送春兼送老，更嘗一着更听看。"]', '诗', 'shi', '', NULL, '送春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d47da9b-8ad5-4ac3-bd5f-c0abfe9d4aeb', '宿杜曲花下', '宿杜曲花下', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["覓得花千樹，攜來酒一壺。","嬾歸兼擬宿，未醉豈勞扶。","但惜春將晚，寧愁日漸晡。","籃轝爲臥舍，漆盝是行廚。","斑竹盛茶櫃，紅泥罨飯爐。","眼前無所闕，身外更何須。","小面琵琶婢，蒼頭觱篥奴。","從君飽富貴，曾作此遊無。"]', '["覓得花千樹，携来酒一壺。","嬾归兼擬宿，未醉豈勞扶。","但惜春將晚，寧愁日漸晡。","籃轝爲臥舍，漆盝是行廚。","斑竹盛茶櫃，紅泥罨飯爐。","眼前無所闕，身外更何須。","小面琵琶婢，蒼头觱篥奴。","從君飽富貴，曾作此游無。"]', '诗', 'shi', '', NULL, '宿杜曲花下 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2730deb-c3c3-469b-9b04-72a245f92362', '逢舊', '逢旧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["久別偶相逢，俱疑是夢中。","即今歡樂事，放醆又成空。"]', '["久別偶相逢，俱疑是梦中。","即今歡乐事，放醆又成空。"]', '诗', 'shi', '', NULL, '逢舊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5608e17-7480-4b59-abde-75943af4bc64', '繡婦嘆', '繡婦嘆', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["連枝花樣繡羅襦，本擬新年餉小姑。","自覺逢春饒悵望，誰能每日趂功夫。","針頭不解愁眉結，線縷難穿淚臉珠。","雖凭繡牀都不繡，同牀繡伴得知無。"]', '["連枝花樣繡羅襦，本擬新年餉小姑。","自覺逢春饒悵望，誰能每日趂功夫。","針头不解愁眉結，線縷难穿泪臉珠。","雖凭繡牀都不繡，同牀繡伴得知無。"]', '诗', 'shi', '', NULL, '繡婦嘆 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f30a611c-ee72-4317-a752-b241955ff493', '春詞', '春词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["低花樹暎小妝樓，春入眉心兩點愁。","斜倚欄干背鸚鵡，思量何事不回頭。"]', '["低花樹暎小妝楼，春入眉心兩点愁。","斜倚欄干背鸚鵡，思量何事不回头。"]', '诗', 'shi', '', NULL, '春詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d95c1f-1c5a-45a3-945b-04bda88e28ac', '恨詞', '恨词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翠黛眉低歛，紅珠淚暗銷。","從來恨人意，不省似今朝。"]', '["翠黛眉低歛，紅珠泪暗銷。","從来恨人意，不省似今朝。"]', '诗', 'shi', '', NULL, '恨詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa97f05f-e0f7-4bdb-a5b0-5c18046af690', '山石榴花十二韻', '山石榴花十二韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曄曄復煌煌，花中無比方。","豔夭宜小院，條短稱低廊。","本是山頭物，今爲砌下芳。","千叢相向背，萬朵互低昂。","照灼連朱檻，玲瓏暎粉牆。","風來添意態，日出助晶光。","漸綻臙脂萼，猶含琴軫房。","離披亂剪綵，斑駮未勻妝。","絳焰燈千炷，紅裙妓一行。","此時逢國色，何處覓天香？","恐合栽金闕，思將獻玉皇。","好差青鳥使，封作百花王。"]', '["曄曄复煌煌，花中無比方。","豔夭宜小院，條短稱低廊。","本是山头物，今爲砌下芳。","千叢相向背，万朵互低昂。","照灼連朱檻，玲瓏暎粉牆。","风来添意態，日出助晶光。","漸綻臙脂萼，猶含琴軫房。","離披亂剪綵，斑駮未勻妝。","絳焰灯千炷，紅裙妓一行。","此时逢国色，何处覓天香？","恐合栽金闕，思將獻玉皇。","好差青鸟使，封作百花王。"]', '诗', 'shi', '', NULL, '山石榴花十二韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec054e7f-324d-454e-a244-8bef18e7ee8a', '送敏中歸豳寧幕', '送敏中归豳寧幕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["六十衰翁兒女悲，傍人應笑爾應知。","弟兄垂老相逢日，桮酒臨歡欲散時。","前路加餐須努力，今宵盡醉莫推辭。","司徒知我難爲別，直過秋歸未訝遲。"]', '["六十衰翁兒女悲，傍人應笑爾應知。","弟兄垂老相逢日，桮酒臨歡欲散时。","前路加餐須努力，今宵尽醉莫推辞。","司徒知我难爲別，直過秋归未訝遲。"]', '诗', 'shi', '', NULL, '送敏中歸豳寧幕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81dd6865-1e6d-474f-bc5c-8b8223109c5a', '宴散', '宴散', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小宴追涼散，平橋步月回。","笙歌歸院落，燈火下樓臺。","殘暑蟬催盡，新秋雁帶來。","將何迎睡興，臨臥舉殘桮。"]', '["小宴追涼散，平橋步月回。","笙歌归院落，灯火下楼台。","殘暑蟬催尽，新秋雁带来。","將何迎睡兴，臨臥舉殘桮。"]', '诗', 'shi', '', NULL, '宴散 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('887824c8-fdd5-4e78-bf32-a2ec822f20ab', '人定', '人定', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人定月朧明，香消枕簟清。","翠屏遮燭影，紅袖下簾聲。","坐久吟方罷，眠初夢未成。","誰家教鸚鵡，故故語相驚。"]', '["人定月朧明，香消枕簟清。","翠屏遮燭影，紅袖下簾声。","坐久吟方罷，眠初梦未成。","誰家教鸚鵡，故故語相驚。"]', '诗', 'shi', '', NULL, '人定 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a63be1d1-0287-415b-9a20-774daf45db93', '池上', '池上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["褭褭涼風動，淒淒寒露零。","蘭衰花始白，荷破葉猶青。","獨立棲沙鶴，雙飛照水螢。","若爲寥落境，仍值酒初醒。"]', '["褭褭涼风动，淒淒寒露零。","蘭衰花始白，荷破葉猶青。","独立棲沙鹤，雙飞照水螢。","若爲寥落境，仍值酒初醒。"]', '诗', 'shi', '', NULL, '池上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('946d9648-d416-44b1-bae2-2414276c2ceb', '池窗', '池窗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池晚蓮芳謝，窗秋竹意深。","更無人作伴，唯對一張琴。"]', '["池晚蓮芳謝，窗秋竹意深。","更無人作伴，唯对一張琴。"]', '诗', 'shi', '', NULL, '池窗 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af72b11-3f71-4862-a45a-d5655fcf6816', '花酒', '花酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香醅淺酌浮如蟻，雪鬢新梳薄似蟬。","爲報洛城花酒道，莫辭送老二三年。"]', '["香醅淺酌浮如蟻，雪鬢新梳薄似蟬。","爲報洛城花酒道，莫辞送老二三年。"]', '诗', 'shi', '', NULL, '花酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('224152f2-bd04-4630-8643-b1584f086c5c', '題崔常侍濟源莊', '題崔常侍濟源莊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["谷口誰家住，雲扃鎖竹泉。","主人何處去，蘿薜換貂蟬。","籍在金閨內，班排玉扆前。","誠知憶山水，歸得是何年。"]', '["谷口誰家住，云扃鎖竹泉。","主人何处去，蘿薜換貂蟬。","籍在金閨內，班排玉扆前。","誠知憶山水，归得是何年。"]', '诗', 'shi', '', NULL, '題崔常侍濟源莊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77037740-3c99-4565-a8d9-976282f54bec', '認春戲呈馮少尹李郎中陳主簿', '認春戲呈馮少尹李郎中陳主簿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["認得春風先到處，西園南面水東頭。","柳初變後條猶重，花未開時枝已稠。","闇助醉歡尋綠酒，潛添睡興著紅樓。","知君未別陽和意，直待春深始擬遊。"]', '["認得春风先到处，西园南面水东头。","柳初变後條猶重，花未开时枝已稠。","闇助醉歡尋綠酒，潛添睡兴著紅楼。","知君未別陽和意，直待春深始擬游。"]', '诗', 'shi', '', NULL, '認春戲呈馮少尹李郎中陳主簿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1453f1c-6d56-4161-b800-7e863251437e', '魏堤有懷', '魏堤有懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["魏王堤下水，聲似使君灘。","惆悵回頭聽，躊躕立馬看。","蕩風波眼急，翻雪浪心寒。","憶得瞿唐事，重吟行路難。"]', '["魏王堤下水，声似使君灘。","惆悵回头听，躊躕立马看。","蕩风波眼急，翻雪浪心寒。","憶得瞿唐事，重吟行路难。"]', '诗', 'shi', '', NULL, '魏堤有懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcac29bf-007e-4b0d-b636-3167f0eb49b5', '柘枝詞', '柘枝词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柳闇長廊合，花深小院開。","蒼頭鋪錦褥，皓腕捧銀桮。","繡帽珠稠綴，香衫袖窄裁。","將軍拄毬杖，看按柘枝來。"]', '["柳闇长廊合，花深小院开。","蒼头鋪錦褥，皓腕捧銀桮。","繡帽珠稠綴，香衫袖窄裁。","將軍拄毬杖，看按柘枝来。"]', '诗', 'shi', '', NULL, '柘枝詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a527907-ee34-4da1-a5c2-1f1bb3801581', '代夢得吟', '代梦得吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["後來變化三分貴，同輩凋零太半無。","世上爭先從盡汝，人間鬬在不如吾。","竿頭已到應難久，局勢雖遲未必輸。","不見山苗與林葉，迎春先綠亦先枯。"]', '["後来变化三分貴，同輩凋零太半無。","世上爭先從尽汝，人间鬬在不如吾。","竿头已到應难久，局勢雖遲未必輸。","不见山苗與林葉，迎春先綠亦先枯。"]', '诗', 'shi', '', NULL, '代夢得吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae7bdec0-bc26-47b6-9bf8-34c27e1c61e3', '寄答周協律', '寄答周協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["故人敘舊寄新篇，惆悵江南到眼前。","闇想樓臺萬餘里，不聞歌吹一周年。","橋頭誰更看新月，池畔猶應泊舊船。","最憶後庭桮酒散，紅屏風掩綠窗眠。"]', '["故人敘旧寄新篇，惆悵江南到眼前。","闇想楼台万餘里，不闻歌吹一周年。","橋头誰更看新月，池畔猶應泊旧船。","最憶後庭桮酒散，紅屏风掩綠窗眠。"]', '诗', 'shi', '', NULL, '寄答周協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a66607c-8293-4818-b586-4b1390c222f0', '太和戊申歲大有年詔賜百寮出城觀稼謹書盛事以俟采詩', '太和戊申歲大有年詔賜百寮出城观稼謹书盛事以俟采诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["清晨承詔命，豐歲閱田閭。","膏雨抽苗足，涼風吐穗初。","早禾黃錯落，晚稻綠扶疎。","好入詩家詠，宜令史館書。","散爲萬姓食，堆作九年儲。","莫道如雲稼，今秋雲不如。"]', '["清晨承詔命，豐歲閱田閭。","膏雨抽苗足，涼风吐穗初。","早禾黄錯落，晚稻綠扶疎。","好入诗家詠，宜令史館书。","散爲万姓食，堆作九年儲。","莫道如云稼，今秋云不如。"]', '诗', 'shi', '', NULL, '太和戊申歲大有年詔賜百寮出城觀稼謹書盛事以俟采詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97d1b08e-b92a-408c-ac0c-01192eddac34', '贈悼懷太子挽歌辭二首 一', '贈悼懷太子挽歌辞二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["竹馬書薨歲，銅龍表葬時。","永言窀穸事，全用少陽儀。","壽夭由天命，哀榮出聖慈。","恭聞褒贈詔，軫念在與夷。"]', '["竹马书薨歲，銅龙表葬时。","永言窀穸事，全用少陽儀。","壽夭由天命，哀榮出聖慈。","恭闻褒贈詔，軫念在與夷。"]', '诗', 'shi', '', NULL, '贈悼懷太子挽歌辭二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39c85c6d-d4c8-4c91-9d88-c30297c12c17', '贈悼懷太子挽歌辭二首 二', '贈悼懷太子挽歌辞二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["剪葉藩封早，承華冊命尊。","笙歌辭洛苑，風雪蔽梁園。","鹵簿凌霜宿，銘旌向月翻。","宮寮不逮事，哭送出都門。"]', '["剪葉藩封早，承华冊命尊。","笙歌辞洛苑，风雪蔽梁园。","鹵簿凌霜宿，銘旌向月翻。","宮寮不逮事，哭送出都门。"]', '诗', 'shi', '', NULL, '贈悼懷太子挽歌辭二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e62cd454-8cda-44d6-b491-6a7a127de4a9', '雨中招張司業宿', '雨中招張司業宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["過夏衣香潤，迎秋簟色鮮。","斜支花石枕，臥詠蘂珠篇。","泥濘非遊日，陰沈好睡天。","能來同宿否，聽雨對牀眠。"]', '["過夏衣香潤，迎秋簟色鲜。","斜支花石枕，臥詠蘂珠篇。","泥濘非游日，陰沈好睡天。","能来同宿否，听雨对牀眠。"]', '诗', 'shi', '', NULL, '雨中招張司業宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e555361a-7e41-48b8-8040-b411fde3d49d', '和集賢劉學士早朝作', '和集賢劉学士早朝作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吟君昨日早朝詩，金御爐前喚仗時。","煙吐白龍頭宛轉，扇開青雉尾參差。","暫留春殿多稱屈，合入綸闈即可知。","從此摩霄去非晚，鬢邊未有一莖絲。"]', '["吟君昨日早朝诗，金御爐前喚仗时。","煙吐白龙头宛轉，扇开青雉尾參差。","暫留春殿多稱屈，合入綸闈即可知。","從此摩霄去非晚，鬢邊未有一莖絲。"]', '诗', 'shi', '', NULL, '和集賢劉學士早朝作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('874bb5b3-1e94-4b59-a222-bce3060a603d', '送陝州王司馬建赴任', '送陝州王司马建赴任', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陝州司馬去何如，養靜資貧兩有餘。","公事閑忙同少尹，料錢多少敵尚書。","秪攜美酒爲行伴，唯作新詩趂下車。","自有鐵牛無詠者，料君投刃必應虛。"]', '["陝州司马去何如，養静資貧兩有餘。","公事闲忙同少尹，料錢多少敵尚书。","秪携美酒爲行伴，唯作新诗趂下车。","自有鐵牛無詠者，料君投刃必應虛。"]', '诗', 'shi', '', NULL, '送陝州王司馬建赴任 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc48cce6-8d81-40d0-8ab6-c9eacbcdbaea', '對琴待月', '对琴待月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["竹院新晴夜，松窗未臥時。","共琴爲老伴，與月有秋期。","玉軫臨風久，金波出霧遲。","幽音待清景，唯是我心知。"]', '["竹院新晴夜，松窗未臥时。","共琴爲老伴，與月有秋期。","玉軫臨风久，金波出霧遲。","幽音待清景，唯是我心知。"]', '诗', 'shi', '', NULL, '對琴待月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8fb95f3-ae8d-4722-b50f-4b37c202e15d', '楊家南亭', '楊家南亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小亭門向月斜開，滿地涼風滿地苔。","此院好彈秋思處，終須一夜抱琴來。"]', '["小亭门向月斜开，满地涼风满地苔。","此院好彈秋思处，終須一夜抱琴来。"]', '诗', 'shi', '', NULL, '楊家南亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11a806e-7117-4cdf-a8f8-05cc03560457', '早寒', '早寒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃葉聚牆角，青苔圍柱根。","被經霜後薄，鏡遇雨來昏。","半卷寒簷幕，斜開暖閣門。","迎冬兼送老，只仰酒盈尊。"]', '["黄葉聚牆角，青苔圍柱根。","被經霜後薄，镜遇雨来昏。","半卷寒簷幕，斜开暖閣门。","迎冬兼送老，只仰酒盈尊。"]', '诗', 'shi', '', NULL, '早寒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6a8d607-0b55-48fa-8171-25544edde49c', '齋月靜居', '斋月静居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病來心靜一無思，老去身閑百不爲。","忽忽眼塵猶愛睡，些些口業尚誇詩。","葷腥每斷齋居月，香火常親宴坐時。","萬慮消停百神泰，唯應寂寞殺三尸。"]', '["病来心静一無思，老去身闲百不爲。","忽忽眼塵猶愛睡，些些口業尚誇诗。","葷腥每斷斋居月，香火常親宴坐时。","万慮消停百神泰，唯應寂寞殺三尸。"]', '诗', 'shi', '', NULL, '齋月靜居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a80c83c-5604-4112-ab99-8edf1bb3829a', '宿裴相公興化池亭', '宿裴相公兴化池亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["林亭一出宿風塵，忘却平津是要津。","松閣晴看山色近，石渠秋放水聲新。","孫弘閣鬧無閑客，傅說舟忙不借人。","何似掄才濟川外，別開池館待交親。"]', '["林亭一出宿风塵，忘却平津是要津。","松閣晴看山色近，石渠秋放水声新。","孫弘閣鬧無闲客，傅说舟忙不借人。","何似掄才濟川外，別开池館待交親。"]', '诗', 'shi', '', NULL, '宿裴相公興化池亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('977b738f-7a6f-4200-a957-7770bbf925f3', '和劉郎中望終南山秋雪', '和劉郎中望終南山秋雪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遍覽古今集，都無秋雪詩。","陽春先唱後，陰嶺未消時。","草訝霜凝重，松疑鶴散遲。","清光莫獨占，亦對白雲司。"]', '["遍覽古今集，都無秋雪诗。","陽春先唱後，陰嶺未消时。","草訝霜凝重，松疑鹤散遲。","清光莫独占，亦对白云司。"]', '诗', 'shi', '', NULL, '和劉郎中望終南山秋雪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c4ab796-a808-4556-8fc3-828dc5fa3d8a', '廣府胡尚書頻寄詩因答絕句', '廣府胡尚书頻寄诗因答絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["尚書清白臨南海，雖飲貪泉心不回。","唯向詩中得珠玉，時時寄到帝鄉來。"]', '["尚书清白臨南海，雖饮貪泉心不回。","唯向诗中得珠玉，时时寄到帝乡来。"]', '诗', 'shi', '', NULL, '廣府胡尚書頻寄詩因答絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7034a173-7baa-4bf3-a52e-b428e28572a7', '送鶴與裴相臨別贈詩', '送鹤與裴相臨別贈诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["司空愛爾爾須知，不信聽吟送鶴詩。","羽翮勢高寧惜別，稻粱恩厚莫愁飢。","夜棲少共雞爭樹，曉浴先饒鳳占池。","穩上青雲勿回顧，的應勝在白家時。"]', '["司空愛爾爾須知，不信听吟送鹤诗。","羽翮勢高寧惜別，稻粱恩厚莫愁飢。","夜棲少共雞爭樹，晓浴先饒鳳占池。","穩上青云勿回顧，的應勝在白家时。"]', '诗', 'shi', '', NULL, '送鶴與裴相臨別贈詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7952a975-819b-4b52-be03-f1bee23ca585', '令狐相公拜尚書後有喜從鎮歸朝之作劉郎中先和因以繼之', '令狐相公拜尚书後有喜從鎮归朝之作劉郎中先和因以繼之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["車騎新從梁苑回，履聲珮響入中臺。","鳳池望在終重去，龍節功成且納來。","金勒最宜乘雪出，玉觴何必待花開。","尚書首唱郎中和，不計官資只計才。"]', '["车騎新從梁苑回，履声珮响入中台。","鳳池望在終重去，龙節功成且納来。","金勒最宜乘雪出，玉觴何必待花开。","尚书首唱郎中和，不計官資只計才。"]', '诗', 'shi', '', NULL, '令狐相公拜尚書後有喜從鎮歸朝之作劉郎中先和因以繼之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8215659a-3816-4b6f-841f-1e5a9d14bcf6', '送河南尹馮學士赴任', '送河南尹馮学士赴任', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["石渠金谷中間路，軒騎翩翩十日程。","清洛飲冰添苦節，碧嵩看雪助高情。","謾誇河北操旄鉞，莫羨江西擁斾旌。","何似府寮京令外，別教三十六峰迎。"]', '["石渠金谷中间路，軒騎翩翩十日程。","清洛饮冰添苦節，碧嵩看雪助高情。","謾誇河北操旄鉞，莫羨江西擁斾旌。","何似府寮京令外，別教三十六峰迎。"]', '诗', 'shi', '', NULL, '送河南尹馮學士赴任 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33107f49-023b-41dc-824a-bf27a0970082', '讀鄂公傳', '读鄂公傳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高臥深居不見人，功名斗藪似灰塵。","唯留一部清商樂，月下風前伴老身。"]', '["高臥深居不见人，功名斗藪似灰塵。","唯留一部清商乐，月下风前伴老身。"]', '诗', 'shi', '', NULL, '讀鄂公傳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232f014d-c66d-43c8-be71-b25dffcb88ba', '烏夜啼', '烏夜啼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城上歸時晚，庭前宿處危。","月明無葉樹，霜滑有風枝。","啼澀飢喉咽，飛低凍翅垂。","畫堂鸚鵡鳥，冷暖不相知。"]', '["城上归时晚，庭前宿处危。","月明無葉樹，霜滑有风枝。","啼澀飢喉咽，飞低凍翅垂。","畫堂鸚鵡鸟，冷暖不相知。"]', '诗', 'shi', '', NULL, '烏夜啼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d4eb058-b753-472d-b307-b425ac50515c', '鏡換桮', '镜換桮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲將珠匣青銅鏡，換取金尊白玉巵。","鏡裏老來無避處，尊前愁至有消時。","茶能散悶爲功淺，萱縱忘憂得力遲。","不似杜康神用速，十分一盞便開眉。"]', '["欲將珠匣青銅镜，換取金尊白玉巵。","镜裏老来無避处，尊前愁至有消时。","茶能散悶爲功淺，萱縱忘憂得力遲。","不似杜康神用速，十分一盞便开眉。"]', '诗', 'shi', '', NULL, '鏡換桮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2b2f64c-ecc1-4380-9726-cb54a98a77df', '冬夜聞蟲', '冬夜闻蟲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蟲聲冬思苦於秋，不解愁人聞亦愁。","我是老翁聽不畏，少年莫聽白君頭。"]', '["蟲声冬思苦於秋，不解愁人闻亦愁。","我是老翁听不畏，少年莫听白君头。"]', '诗', 'shi', '', NULL, '冬夜聞蟲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('483ef41e-5a21-44ad-a591-03708a51ce91', '雙鸚鵡', '雙鸚鵡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綠衣整頓雙棲起，紅觜分明對語時。","始覺琵琶弦莽鹵，方知吉了舌參差。","鄭牛識字吾常嘆，丁鶴能歌爾亦知。","若稱白家鸚鵡鳥，籠中兼合解吟詩。"]', '["綠衣整頓雙棲起，紅觜分明对語时。","始覺琵琶弦莽鹵，方知吉了舌參差。","鄭牛識字吾常嘆，丁鹤能歌爾亦知。","若稱白家鸚鵡鸟，籠中兼合解吟诗。"]', '诗', 'shi', '', NULL, '雙鸚鵡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a0b702-9570-431a-b745-d22ecca78ae9', '贈朱道士', '贈朱道士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["儀容白皙上仙郎，方寸清虛內道場。","兩翼化生因服藥，三尸臥死爲休糧。","醮壇北向宵占斗，寢室東開早納陽。","盡日窗間更無事，唯燒一炷降真香。"]', '["儀容白皙上仙郎，方寸清虛內道場。","兩翼化生因服藥，三尸臥死爲休糧。","醮壇北向宵占斗，寢室东开早納陽。","尽日窗间更無事，唯燒一炷降真香。"]', '诗', 'shi', '', NULL, '贈朱道士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4759e66e-3358-437a-87cd-2f7c8f16ead8', '昨以拙詩十首寄西川杜相公相公亦以新作十首惠然報示首數雖等工拙不倫重以一章用伸答謝', '昨以拙诗十首寄西川杜相公相公亦以新作十首惠然報示首數雖等工拙不倫重以一章用伸答謝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["詩家律手在成都，權與尋常將相殊。","剪截五言兼用鉞，陶鈞六義別開爐。","驚人卷軸須知有，隨事文章不道無。","篇數雖同光價異，十魚目換十驪珠。"]', '["诗家律手在成都，權與尋常將相殊。","剪截五言兼用鉞，陶鈞六義別开爐。","驚人卷軸須知有，隨事文章不道無。","篇數雖同光價異，十鱼目換十驪珠。"]', '诗', 'shi', '', NULL, '昨以拙詩十首寄西川杜相公相公亦以新作十首惠然報示首數雖等工拙不倫重以一章用伸答謝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('778f314b-7103-490e-86fe-c9fc1a24d42f', '和汴州令狐相公新於郡內栽竹百竿拆壁開軒旦夕對翫偶題七言五韻', '和汴州令狐相公新於郡內栽竹百竿拆壁开軒旦夕对翫偶題七言五韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["梁園修竹舊傳名，園廢年深竹不生。","千畝荒涼尋未得，百竿青翠種新成。","牆開乍見重添興，窗靜時聞別有情。","煙葉蒙籠侵夜色，風枝蕭颯欲秋聲。","更登樓望尤堪重，千萬人家無一莖。"]', '["梁园修竹旧傳名，园廢年深竹不生。","千畝荒涼尋未得，百竿青翠種新成。","牆开乍见重添兴，窗静时闻別有情。","煙葉蒙籠侵夜色，风枝蕭颯欲秋声。","更登楼望尤堪重，千万人家無一莖。"]', '诗', 'shi', '', NULL, '和汴州令狐相公新於郡內栽竹百竿拆壁開軒旦夕對翫偶題七言五韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fb3270a-18a9-452d-a2f1-6bee72676b26', '重答汝州李六使君見和憶吳中舊遊五首', '重答汝州李六使君见和憶吳中旧游五首', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爲憶娃宮與虎丘，翫君新作不能休。","蜀牋寫出篇篇好，吳調吟時句句愁。","洛下林園終共住，江南風月會重遊。","由來事過多堪惜，何況蘇州勝汝州。"]', '["爲憶娃宮與虎丘，翫君新作不能休。","蜀牋寫出篇篇好，吳調吟时句句愁。","洛下林园終共住，江南风月會重游。","由来事過多堪惜，何況蘇州勝汝州。"]', '诗', 'shi', '', NULL, '重答汝州李六使君見和憶吳中舊遊五首 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27e1e855-bdb1-4d4a-96a6-681cf936ccd4', '見殷堯藩侍御憶江南詩三十首詩中多敘蘇杭勝事余嘗典二郡因繼和之', '见殷堯藩侍御憶江南诗三十首诗中多敘蘇杭勝事余嘗典二郡因繼和之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南名郡數蘇杭，寫在殷家三十章。","君是旅人猶苦憶，我爲刺史更難忘。","境牽吟詠真詩國，興入笙歌好醉鄉。","爲念舊遊終一去，扁舟直擬到滄浪。"]', '["江南名郡數蘇杭，寫在殷家三十章。","君是旅人猶苦憶，我爲刺史更难忘。","境牽吟詠真诗国，兴入笙歌好醉乡。","爲念旧游終一去，扁舟直擬到滄浪。"]', '诗', 'shi', '', NULL, '見殷堯藩侍御憶江南詩三十首詩中多敘蘇杭勝事余嘗典二郡因繼和之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7768a418-3453-4ca1-97ae-e216a411191d', '聞新蟬贈劉二十八', '闻新蟬贈劉二十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蟬發一聲時，槐花帶兩枝。","只應催我老，兼遣報君知。","白髮生頭速，青雲入手遲。","無過一桮酒，相勸數開眉。"]', '["蟬發一声时，槐花带兩枝。","只應催我老，兼遣報君知。","白髮生头速，青云入手遲。","無過一桮酒，相勸數开眉。"]', '诗', 'shi', '', NULL, '聞新蟬贈劉二十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('312c1c66-cbdf-499d-adaa-55a1322423f5', '贈王山人', '贈王山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玉芝觀裏王居士，服氣餐霞善養身。","夜後不聞龜喘息，秋來唯長鶴精神。","容顏盡怪長如故，名姓多疑不是真。","貴重榮華輕壽命，知君悶見世間人。"]', '["玉芝观裏王居士，服氣餐霞善養身。","夜後不闻龟喘息，秋来唯长鹤精神。","容顏尽怪长如故，名姓多疑不是真。","貴重榮华轻壽命，知君悶见世间人。"]', '诗', 'shi', '', NULL, '贈王山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dc665d9-b6f4-40bc-ba4d-8b72f120db76', '和劉郎中學士題集賢閣', '和劉郎中学士題集賢閣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朱閣青山高庳齊，與君才子作詩題。","傍聞大內笙歌近，下視諸司屋舍低。","萬卷圖書天祿上，一條風景月華西。","欲知丞相優賢意，百步新廊不蹋泥。"]', '["朱閣青山高庳齊，與君才子作诗題。","傍闻大內笙歌近，下視諸司屋舍低。","万卷圖书天祿上，一條风景月华西。","欲知丞相優賢意，百步新廊不蹋泥。"]', '诗', 'shi', '', NULL, '和劉郎中學士題集賢閣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d8afc5-0b5d-40b3-a373-76d40b33bd28', '觀幻', '观幻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有起皆因滅，無暌不暫同。","從歡終作慼，轉苦又成空。","次第花生眼，須臾燭過風。","更無尋覓處，鳥跡印空中。"]', '["有起皆因滅，無暌不暫同。","從歡終作慼，轉苦又成空。","次第花生眼，須臾燭過风。","更無尋覓处，鸟跡印空中。"]', '诗', 'shi', '', NULL, '觀幻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2882300f-b22a-46d6-8003-11948ccb8c23', '病假中龐少尹攜魚酒相過', '病假中龐少尹携鱼酒相過', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宦情牢落年將暮，病假聯緜日漸深。","被老相催雖白首，與春無分未甘心。","閑停茶椀從容語，醉把花枝取次吟。","勞動故人龐閣老，提魚攜酒遠相尋。"]', '["宦情牢落年將暮，病假聯緜日漸深。","被老相催雖白首，與春無分未甘心。","闲停茶椀從容語，醉把花枝取次吟。","勞动故人龐閣老，提鱼携酒远相尋。"]', '诗', 'shi', '', NULL, '病假中龐少尹攜魚酒相過 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401c1e34-c0a2-4d90-968c-43d1daa325f4', '聽田順兒歌', '听田順兒歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["戛玉敲冰聲未停，嫌雲不遏入青冥。","爭得黃金滿衫袖，一時拋與斷年聽。"]', '["戛玉敲冰声未停，嫌云不遏入青冥。","爭得黄金满衫袖，一时拋與斷年听。"]', '诗', 'shi', '', NULL, '聽田順兒歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d45ddee-35d8-4382-8108-e2e4f27ce179', '聽曹剛琵琶兼示重蓮', '听曹剛琵琶兼示重蓮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["撥撥弦弦意不同，胡啼番語兩玲瓏。","誰能截得曹剛手，插向重蓮衣袖中。"]', '["撥撥弦弦意不同，胡啼番語兩玲瓏。","誰能截得曹剛手，插向重蓮衣袖中。"]', '诗', 'shi', '', NULL, '聽曹剛琵琶兼示重蓮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c99df5-f3e0-4c3d-9938-d0f2814178af', '酬令狐相公春日尋花見寄六韻', '酬令狐相公春日尋花见寄六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病臥帝王州，花時不得遊。","老應隨日至，春肯爲人留。","粉壞杏將謝，火繁桃尚稠。","白飄僧院地，紅落酒家樓。","空裏雪相似，晚來風不休。","吟君悵望句，如到曲江頭。"]', '["病臥帝王州，花时不得游。","老應隨日至，春肯爲人留。","粉壞杏將謝，火繁桃尚稠。","白飄僧院地，紅落酒家楼。","空裏雪相似，晚来风不休。","吟君悵望句，如到曲江头。"]', '诗', 'shi', '', NULL, '酬令狐相公春日尋花見寄六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('138ff99d-9c55-4124-8001-969bbd55dd95', '和劉郎中曲江春望見示', '和劉郎中曲江春望见示', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["芳景多遊客，衰翁獨在家。","肺傷妨飲酒，眼痛忌看花。","寺路隨江曲，宮牆夾道斜。","羨君猶壯健，不枉度年華。"]', '["芳景多游客，衰翁独在家。","肺傷妨饮酒，眼痛忌看花。","寺路隨江曲，宮牆夾道斜。","羨君猶壯健，不枉度年华。"]', '诗', 'shi', '', NULL, '和劉郎中曲江春望見示 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('190d90cc-22b2-4755-a834-4adf7155988a', '送東都留守令狐尚書赴任', '送东都留守令狐尚书赴任', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翠華黃屋未東巡，碧洛青嵩付大臣。","地稱高情多水竹，山宜閑望少風塵。","龍門即擬爲遊客，金谷先憑作主人。","歌酒家家花處處，莫空管領上陽春。"]', '["翠华黄屋未东巡，碧洛青嵩付大臣。","地稱高情多水竹，山宜闲望少风塵。","龙门即擬爲游客，金谷先憑作主人。","歌酒家家花处处，莫空管領上陽春。"]', '诗', 'shi', '', NULL, '送東都留守令狐尚書赴任 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e814ead9-53cd-4d54-a500-a120a38ee9cf', '自題新昌居止因招楊郎中小飲', '自題新昌居止因招楊郎中小饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["地偏坊遠巷仍斜，最近東頭是白家。","宿雨長齊鄰舍柳，晴光照出夾城花。","春風小榼三升酒，寒食深爐一椀茶。","能到南園同醉否，笙歌隨分有些些。"]', '["地偏坊远巷仍斜，最近东头是白家。","宿雨长齊鄰舍柳，晴光照出夾城花。","春风小榼三升酒，寒食深爐一椀茶。","能到南园同醉否，笙歌隨分有些些。"]', '诗', 'shi', '', NULL, '自題新昌居止因招楊郎中小飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1540716-9d28-45d6-b1f7-1af4818684fb', '南園試小樂', '南园試小乐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小園斑駮花初發，新樂錚摐教欲成。","紅萼紫房皆手植，蒼頭碧玉盡家生。","高調管色吹銀字，慢拽歌詞唱渭城。","不飲一杯聽一曲，將何安慰老心情。"]', '["小园斑駮花初發，新乐錚摐教欲成。","紅萼紫房皆手植，蒼头碧玉尽家生。","高調管色吹銀字，慢拽歌词唱渭城。","不饮一杯听一曲，將何安慰老心情。"]', '诗', 'shi', '', NULL, '南園試小樂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b9b6071-6dc8-4b04-949c-5350f23e4f9d', '和微之春日投簡陽明洞天五十韻', '和微之春日投簡陽明洞天五十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青陽行已半，白日坐將徂。","越國強仍大，稽城高且孤。","利饒鹽煮海，名勝水澄湖。","牛斗天垂象，台明地展圖。","瓌奇填市井，佳麗溢闉闍。","句踐遺風霸，西施舊俗姝。","船頭龍夭矯，橋脚獸睢盱。","鄉味珍蟛蚏，時鮮貴鷓鴣。","語言諸夏異，衣服一方殊。","擣練蛾眉婢，鳴榔蛙角奴。","江清敵伊洛，山翠勝荆巫。","華表雙棲鶴，聯檣幾點烏。","煙波分渡口，雲樹接城隅。","澗遠松如畫，洲平水似鋪。","綠科秧早稻，紫笋折新蘆。","暖蹋泥中藕，香尋石上蒲。","雨來萌盡達，雷後蟄全蘇。","柳眼黃絲纇，花房絳蠟珠。","林風新竹折，野燒老桑枯。","帶嚲長枝蕙，錢穿短貫榆。","暄和生野菜，卑濕長街蕪。","女浣紗相伴，兒烹鯉一呼。","山魈啼稚子，林狖挂山都。","產業論蠶蟻，孳生計鴨雛。","泉岩雪飄灑，苔壁錦漫糊。","堰限舟航路，堤通車馬途。","耶溪岸回合，禹廟徑盤紆。","洞穴何因鑿，星槎誰與刳。","石凹仙藥臼，峰峭佛香爐。","去爲投金簡，來因挈玉壺。","貴仍招客宿，健未要人扶。","聞望賢丞相，儀形美丈夫。","前驅駐旌斾，偏坐列笙竽。","刺史旟翻隼，尚書履曳鳧。","學禪超後有，觀妙造虛無。","髻裏傳僧寶，環中得道樞。","登樓詩八詠，置硯賦三都。","捧擁羅將綺，趨蹌紫與朱。","廟謨藏稷卨，兵略貯孫吳。","令下三軍整，風高四海趨。","千家得慈母，六郡事嚴姑。","重士過三哺，輕財抵一銖。","送觥歌宛轉，嘲妓笑盧胡。","佐飲時炮鼈，蠲酲數鱠鱸。","醉鄉雖咫尺，樂事亦須臾。","若不中賢聖，何由外智愚。","伊予一生志，我爾百年軀。","江上三千里，城中十二衢。","出多無伴侶，歸只對妻孥。","白首青山約，抽身去得無。"]', '["青陽行已半，白日坐將徂。","越国強仍大，稽城高且孤。","利饒鹽煮海，名勝水澄湖。","牛斗天垂象，台明地展圖。","瓌奇填市井，佳丽溢闉闍。","句踐遺风霸，西施旧俗姝。","船头龙夭矯，橋脚獸睢盱。","乡味珍蟛蚏，时鲜貴鷓鴣。","語言諸夏異，衣服一方殊。","擣練蛾眉婢，鳴榔蛙角奴。","江清敵伊洛，山翠勝荆巫。","华表雙棲鹤，聯檣幾点烏。","煙波分渡口，云樹接城隅。","澗远松如畫，洲平水似鋪。","綠科秧早稻，紫笋折新蘆。","暖蹋泥中藕，香尋石上蒲。","雨来萌尽達，雷後蟄全蘇。","柳眼黄絲纇，花房絳蠟珠。","林风新竹折，野燒老桑枯。","带嚲长枝蕙，錢穿短貫榆。","暄和生野菜，卑濕长街蕪。","女浣紗相伴，兒烹鯉一呼。","山魈啼稚子，林狖挂山都。","產業論蠶蟻，孳生計鴨雛。","泉岩雪飄灑，苔壁錦漫糊。","堰限舟航路，堤通车马途。","耶溪岸回合，禹廟徑盤紆。","洞穴何因鑿，星槎誰與刳。","石凹仙藥臼，峰峭佛香爐。","去爲投金簡，来因挈玉壺。","貴仍招客宿，健未要人扶。","闻望賢丞相，儀形美丈夫。","前驱駐旌斾，偏坐列笙竽。","刺史旟翻隼，尚书履曳鳧。","学禪超後有，观妙造虛無。","髻裏傳僧寶，环中得道樞。","登楼诗八詠，置硯賦三都。","捧擁羅將綺，趨蹌紫與朱。","廟謨藏稷卨，兵略貯孫吳。","令下三軍整，风高四海趨。","千家得慈母，六郡事嚴姑。","重士過三哺，轻財抵一銖。","送觥歌宛轉，嘲妓笑盧胡。","佐饮时炮鼈，蠲酲數鱠鱸。","醉乡雖咫尺，乐事亦須臾。","若不中賢聖，何由外智愚。","伊予一生志，我爾百年軀。","江上三千里，城中十二衢。","出多無伴侶，归只对妻孥。","白首青山約，抽身去得無。"]', '诗', 'shi', '', NULL, '和微之春日投簡陽明洞天五十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dec5737-b0fb-4333-a9db-68fa6d3779c7', '酬鄭侍御多雨春空過詩三十韻', '酬鄭侍御多雨春空過诗三十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南雨來多滯，東風動即狂。","月行離畢急，龍走召雲忙。","鬼轉雷車響，蛇騰電策光。","浸淫天似漏，沮洳地成瘡。","慘淡陰煙白，空濛宿霧黃。","闇遮千里目，悶結九回腸。","寂寞羈臣館，深沈思婦房。","鏡昏鸞滅影，衣潤麝消香。","蘭濕難紉珮，花凋易落妝。","沾黃鶯翅重，滋綠草心長。","紫陌皆泥濘，黃汚共淼茫。","恐霖成怪沴，望霽劇禎祥。","楚柳腰肢嚲，湘筠涕淚滂。","晝昏疑是夜，陰盛勝於陽。","居士巾皆墊，行人蓋盡張。","跳蛙還屢出，移蟻欲深藏。","端坐交遊廢，閑行去步妨。","愁生垂白叟，惱殺蹋青娘。","變海常須慮，爲魚慎勿忘。","此時方共懼，何處可相將？","已望東溟禱，仍封北戶禳。","却思逢旱魃，誰喜見商羊。","預怕爲蠶病，先憂作麥傷。","惠應施浹洽，政豈假揄揚。","祀典修咸秩，農書振滿牀。","丹誠期懇苦，白日會昭彰。","賑廩賙飢戶，苫城備壞牆。","且當營歲事，寧暇惜年芳。","德勝令災弭，人安在吏良。","尚書心若此，不枉繫金章。"]', '["南雨来多滯，东风动即狂。","月行離畢急，龙走召云忙。","鬼轉雷车响，蛇腾電策光。","浸淫天似漏，沮洳地成瘡。","慘淡陰煙白，空濛宿霧黄。","闇遮千里目，悶結九回腸。","寂寞羈臣館，深沈思婦房。","镜昏鸾滅影，衣潤麝消香。","蘭濕难紉珮，花凋易落妝。","沾黄鶯翅重，滋綠草心长。","紫陌皆泥濘，黄汚共淼茫。","恐霖成怪沴，望霽劇禎祥。","楚柳腰肢嚲，湘筠涕泪滂。","晝昏疑是夜，陰盛勝於陽。","居士巾皆墊，行人蓋尽張。","跳蛙還屢出，移蟻欲深藏。","端坐交游廢，闲行去步妨。","愁生垂白叟，惱殺蹋青娘。","变海常須慮，爲鱼慎勿忘。","此时方共懼，何处可相將？","已望东溟禱，仍封北戶禳。","却思逢旱魃，誰喜见商羊。","預怕爲蠶病，先憂作麦傷。","惠應施浹洽，政豈假揄揚。","祀典修咸秩，農书振满牀。","丹誠期懇苦，白日會昭彰。","賑廩賙飢戶，苫城備壞牆。","且當營歲事，寧暇惜年芳。","德勝令災弭，人安在吏良。","尚书心若此，不枉繫金章。"]', '诗', 'shi', '', NULL, '酬鄭侍御多雨春空過詩三十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4d5f3ae-e7ec-43e1-9d40-aef83d598acd', '和春深二十首 一', '和春深二十首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深富貴家。","馬爲中路鳥，妓作後庭花。","羅綺驅論隊，金銀用斷車。","眼前何所苦，唯苦日西斜。"]', '["何处春深好，春深富貴家。","马爲中路鸟，妓作後庭花。","羅綺驱論隊，金銀用斷车。","眼前何所苦，唯苦日西斜。"]', '诗', 'shi', '', NULL, '和春深二十首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('269e8518-1710-4e3f-9c94-022b2e452f65', '和春深二十首 二', '和春深二十首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深貧賤家。","荒涼三徑草，冷落四鄰花。","奴困歸傭力，妻愁出賃車。","途窮平路險，舉足劇褒斜。"]', '["何处春深好，春深貧賤家。","荒涼三徑草，冷落四鄰花。","奴困归傭力，妻愁出賃车。","途窮平路險，舉足劇褒斜。"]', '诗', 'shi', '', NULL, '和春深二十首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d4d801-7c25-4697-9bb5-17c31fb4e7d6', '和春深二十首 三', '和春深二十首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深執政家。","鳳池添硯水，雞樹落衣花。","詔借當衢宅，恩容上殿車。","延英開對久，門與日西斜。"]', '["何处春深好，春深執政家。","鳳池添硯水，雞樹落衣花。","詔借當衢宅，恩容上殿车。","延英开对久，门與日西斜。"]', '诗', 'shi', '', NULL, '和春深二十首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126184fb-9a70-44be-bbfb-94e93ad79f29', '和春深二十首 四', '和春深二十首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深方鎮家。","通犀排帶胯，瑞鶻勘袍花。","飛絮衝毬馬，垂楊拂妓車。","戎裝拜春設，左握寶刀斜。"]', '["何处春深好，春深方鎮家。","通犀排带胯，瑞鶻勘袍花。","飞絮衝毬马，垂楊拂妓车。","戎裝拜春設，左握寶刀斜。"]', '诗', 'shi', '', NULL, '和春深二十首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2d758fc-5c12-40c0-887e-63072552962c', '和春深二十首 五', '和春深二十首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深刺史家。","陰繁棠布葉，岐秀麥分花。","五疋鳴珂馬，雙輪畫軾車。","和風引行樂，葉葉隼旟斜。"]', '["何处春深好，春深刺史家。","陰繁棠布葉，岐秀麦分花。","五疋鳴珂马，雙輪畫軾车。","和风引行乐，葉葉隼旟斜。"]', '诗', 'shi', '', NULL, '和春深二十首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d9386b2-89ad-4e4c-8eaa-8c2db3c4cbd7', '和春深二十首 六', '和春深二十首 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深學士家。","鳳書裁五色，馬鬣剪三花。","蠟炬開明火，銀臺賜物車。","相逢不敢揖，彼此帽低斜。"]', '["何处春深好，春深学士家。","鳳书裁五色，马鬣剪三花。","蠟炬开明火，銀台賜物车。","相逢不敢揖，彼此帽低斜。"]', '诗', 'shi', '', NULL, '和春深二十首 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd4fd54-5d56-453c-bb9d-49ac89d17661', '和春深二十首 七', '和春深二十首 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深女學家。","慣看溫室樹，飽識浴堂花。","御印提隨仗，香牋把下車。","宋家宮樣髻，一片綠雲斜。"]', '["何处春深好，春深女学家。","慣看溫室樹，飽識浴堂花。","御印提隨仗，香牋把下车。","宋家宮樣髻，一片綠云斜。"]', '诗', 'shi', '', NULL, '和春深二十首 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b40085bc-5eb9-42c9-9f51-3e41190efd8f', '和春深二十首 八', '和春深二十首 八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深御史家。","絮縈驄馬尾，蝶繞繡衣花。","破柱行持斧，埋輪立駐車。","入班遙認得，魚貫一行斜。"]', '["何处春深好，春深御史家。","絮縈驄马尾，蝶繞繡衣花。","破柱行持斧，埋輪立駐车。","入班遙認得，鱼貫一行斜。"]', '诗', 'shi', '', NULL, '和春深二十首 八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c442a1dc-6649-4650-a0ab-1b1d0d296020', '和春深二十首 九', '和春深二十首 九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深遷客家。","一桮寒食酒，萬里故園花。","炎瘴蒸如火，光陰走似車。","爲憂鵩鳥至，只恐日光斜。"]', '["何处春深好，春深遷客家。","一桮寒食酒，万里故园花。","炎瘴蒸如火，光陰走似车。","爲憂鵩鸟至，只恐日光斜。"]', '诗', 'shi', '', NULL, '和春深二十首 九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf899e8c-521e-4f22-83d7-c58f8b5b118b', '和春深二十首 十', '和春深二十首 十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深經業家。","唯求太常第，不管曲江花。","折桂名慙郄，收螢志慕車。","官場泥補處，最怕寸陰斜。"]', '["何处春深好，春深經業家。","唯求太常第，不管曲江花。","折桂名慙郄，收螢志慕车。","官場泥補处，最怕寸陰斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ac8ea1-5da6-4c89-bff1-285ff70d5b47', '和春深二十首 十一', '和春深二十首 十一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深隱士家。","野衣裁薜葉，山飯曬松花。","蘭索紉幽珮，蒲輪駐軟車。","林間箕踞坐，白眼向人斜。"]', '["何处春深好，春深隐士家。","野衣裁薜葉，山飯曬松花。","蘭索紉幽珮，蒲輪駐軟车。","林间箕踞坐，白眼向人斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed3e62b6-3c09-44b2-b8d4-992a5f07d953', '和春深二十首 十二', '和春深二十首 十二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深漁父家。","松灣隨櫂月，桃浦落船花。","投餌移輕楫，牽輪轉小車。","蕭蕭蘆葉裏，風起釣絲斜。"]', '["何处春深好，春深漁父家。","松灣隨櫂月，桃浦落船花。","投餌移轻楫，牽輪轉小车。","蕭蕭蘆葉裏，风起釣絲斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5124d7a9-5485-4b33-9781-dceb2457eb43', '和春深二十首 十三', '和春深二十首 十三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深潮戶家。","濤翻三月雪，浪噴四時花。","曳練馳千馬，驚雷走萬車。","餘波落何處，江轉富陽斜。"]', '["何处春深好，春深潮戶家。","濤翻三月雪，浪噴四时花。","曳練驰千马，驚雷走万车。","餘波落何处，江轉富陽斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c200245-2718-4e76-934a-efa60fb49cca', '和春深二十首 十四', '和春深二十首 十四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深痛飲家。","十分桮裏物，五色眼前花。","餔歠眠糟甕，流涎見麴車。","中山一沈醉，千度日西斜。"]', '["何处春深好，春深痛饮家。","十分桮裏物，五色眼前花。","餔歠眠糟甕，流涎见麴车。","中山一沈醉，千度日西斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adb95ad5-ed32-46ec-8de4-a428ac23d0ae', '和春深二十首 十五', '和春深二十首 十五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深上巳家。","蘭亭席上酒，曲洛岸邊花。","弄水遊童櫂，湔裾小婦車。","齊橈爭渡處，一匹錦標斜。"]', '["何处春深好，春深上巳家。","蘭亭席上酒，曲洛岸邊花。","弄水游童櫂，湔裾小婦车。","齊橈爭渡处，一匹錦標斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67075157-fff2-492d-97bf-62662bc88623', '和春深二十首 十六', '和春深二十首 十六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深寒食家。","玲瓏鏤雞子，宛轉綵毬花。","碧草追遊騎，紅塵拜掃車。","鞦韆細腰女，搖曳逐風斜。"]', '["何处春深好，春深寒食家。","玲瓏鏤雞子，宛轉綵毬花。","碧草追游騎，紅塵拜掃车。","鞦韆細腰女，搖曳逐风斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e97a325e-e1df-40a0-890c-096bf38d0b6b', '和春深二十首 十七', '和春深二十首 十七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深博弈家。","一先爭破眼，六聚鬬成花。","鼓應投壺馬，兵衝象戲車。","彈碁局上事，最妙是長斜。"]', '["何处春深好，春深博弈家。","一先爭破眼，六聚鬬成花。","鼓應投壺马，兵衝象戲车。","彈碁局上事，最妙是长斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49623bd9-d02c-40bb-a14d-e7f882f8c0dc', '和春深二十首 十八', '和春深二十首 十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深嫁女家。","紫排襦上雉，黃帖鬢邊花。","轉燭初移障，鳴環欲上車。","青衣傳氈褥，錦繡一條斜。"]', '["何处春深好，春深嫁女家。","紫排襦上雉，黄帖鬢邊花。","轉燭初移障，鳴环欲上车。","青衣傳氈褥，錦繡一條斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9609189c-395d-4d53-b23a-be20166da715', '和春深二十首 十九', '和春深二十首 十九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深娶婦家。","兩行籠裏燭，一樹扇間花。","賓拜登華席，親迎障幰車。","催妝詩未了，星斗漸傾斜。"]', '["何处春深好，春深娶婦家。","兩行籠裏燭，一樹扇间花。","賓拜登华席，親迎障幰车。","催妝诗未了，星斗漸傾斜。"]', '诗', 'shi', '', NULL, '和春深二十首 十九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b590d1f5-7509-4e19-b2e9-0b35bf6ca3c7', '和春深二十首 二十', '和春深二十首 二十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春深好，春深妓女家。","眉欺楊柳葉，裙妬石榴花。","蘭麝熏行被，金銅釘坐車。","杭州蘇小小，人道最夭斜。"]', '["何处春深好，春深妓女家。","眉欺楊柳葉，裙妬石榴花。","蘭麝熏行被，金銅釘坐车。","杭州蘇小小，人道最夭斜。"]', '诗', 'shi', '', NULL, '和春深二十首 二十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c02f7ae-a3c9-4e40-98fb-e098dcf3f93f', '詠家醖十韻', '詠家醖十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨醒從古笑靈均，長醉如今斅伯倫。","舊法依稀傳自杜，新方要妙得於陳。","井泉王相資重九，麴糵精靈用上寅。","釀糯豈勞炊范黍，撇篘何假漉陶巾。","常嫌竹葉猶凡濁，始覺榴花不正真。","甕揭開時香酷烈，缾封貯後味甘辛。","捧疑明水從空化，飲似陽和滿腹春。","色洞玉壺無表裏，光搖金醆有精神。","能銷忙事成閑事，轉得憂人作樂人。","應是世間賢聖物，與君還往擬終身。"]', '["独醒從古笑靈均，长醉如今斅伯倫。","旧法依稀傳自杜，新方要妙得於陳。","井泉王相資重九，麴糵精靈用上寅。","釀糯豈勞炊范黍，撇篘何假漉陶巾。","常嫌竹葉猶凡濁，始覺榴花不正真。","甕揭开时香酷烈，缾封貯後味甘辛。","捧疑明水從空化，饮似陽和满腹春。","色洞玉壺無表裏，光搖金醆有精神。","能銷忙事成闲事，轉得憂人作乐人。","應是世间賢聖物，與君還往擬終身。"]', '诗', 'shi', '', NULL, '詠家醖十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efd04832-4cbd-4b1e-a1b5-98c570a312af', '池鶴二首 一', '池鹤二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高竹籠前無伴侶，亂雞羣裏有風標。","低頭乍恐丹砂落，曬翅常疑白雪消。","轉覺鸕鷀毛色下，苦嫌鸚鵡語聲嬌。","臨風一唳思何事，悵望青田雲水遙。"]', '["高竹籠前無伴侶，亂雞羣裏有风標。","低头乍恐丹砂落，曬翅常疑白雪消。","轉覺鸕鷀毛色下，苦嫌鸚鵡語声嬌。","臨风一唳思何事，悵望青田云水遙。"]', '诗', 'shi', '', NULL, '池鶴二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9ada4c-ae7c-4a80-8b9c-81b4eedf5be4', '池鶴二首 二', '池鹤二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池中此鶴鶴中稀，恐是遼東老令威。","帶雪松枝翹膝脛，放花菱片綴毛衣。","低迴且向林間宿，奮迅終須天外飛。","若問故巢知處在，主人相戀未能歸。"]', '["池中此鹤鹤中稀，恐是遼东老令威。","带雪松枝翹膝脛，放花菱片綴毛衣。","低迴且向林间宿，奮迅終須天外飞。","若问故巢知处在，主人相戀未能归。"]', '诗', 'shi', '', NULL, '池鶴二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475f20cc-bff7-4225-bd20-ac5b1d6bb96d', '對酒五首 一', '对酒五首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巧拙賢愚相是非，何如一醉盡忘機。","君知天地中寬窄，鵰鶚鸞皇各自飛。"]', '["巧拙賢愚相是非，何如一醉尽忘機。","君知天地中寬窄，鵰鶚鸾皇各自飞。"]', '诗', 'shi', '', NULL, '對酒五首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e603b132-ce1c-4009-94da-e5aae4820914', '對酒五首 二', '对酒五首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蝸牛角上爭何事，石火光中寄此身。","隨富隨貧且歡樂，不開口笑是癡人。"]', '["蝸牛角上爭何事，石火光中寄此身。","隨富隨貧且歡乐，不开口笑是癡人。"]', '诗', 'shi', '', NULL, '對酒五首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbc907f2-5469-4558-a423-4e7b869de6e9', '對酒五首 三', '对酒五首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["丹砂見火去無迹，白髮泥人來不休。","賴有酒仙相暖熱，松喬醉即到前頭。"]', '["丹砂见火去無迹，白髮泥人来不休。","賴有酒仙相暖熱，松喬醉即到前头。"]', '诗', 'shi', '', NULL, '對酒五首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8ad1721-8b65-4822-a830-8105eb343f4c', '對酒五首 四', '对酒五首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百歲無多時壯健，一春能幾日晴明。","相逢且莫推辭醉，聽唱陽關第四聲。"]', '["百歲無多时壯健，一春能幾日晴明。","相逢且莫推辞醉，听唱陽关第四声。"]', '诗', 'shi', '', NULL, '對酒五首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e8a1ab-6753-4ac5-87f0-8589eec0ee09', '對酒五首 五', '对酒五首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日低眉問疾來，今朝收淚弔人回。","眼前流例君看取，且遣琵琶送一桮。"]', '["昨日低眉问疾来，今朝收泪弔人回。","眼前流例君看取，且遣琵琶送一桮。"]', '诗', 'shi', '', NULL, '對酒五首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbebe3bb-6bbf-492f-b55a-f6407ae867cd', '僧院花', '僧院花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲悟色空爲佛事，故栽芳樹在僧家。","細看便是華嚴偈，方便風開智慧花。"]', '["欲悟色空爲佛事，故栽芳樹在僧家。","細看便是华嚴偈，方便风开智慧花。"]', '诗', 'shi', '', NULL, '僧院花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dde9fcb5-0bee-4caa-b76b-4f40f811f831', '老戒', '老戒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我有白頭戒，聞於韓侍郎。","老多憂活計，病更戀班行。","矍鑠誇身健，周遮說話長。","不知吾免否，兩鬢已成霜。"]', '["我有白头戒，闻於韓侍郎。","老多憂活計，病更戀班行。","矍鑠誇身健，周遮说話长。","不知吾免否，兩鬢已成霜。"]', '诗', 'shi', '', NULL, '老戒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c430d72c-3b6e-40c4-8511-da871922f1fc', '洛橋寒食日作十韻', '洛橋寒食日作十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上苑風煙好，中橋道路平。","蹴毬塵不起，潑火雨新晴。","宿醉頭仍重，晨遊眼乍明。","老慵雖省事，春誘尚多情。","遇客踟躕立，尋花取次行。","連錢嚼金勒，鑿落寫銀罌。","府醞傷教送，官娃豈要迎。","舞腰那及柳，歌舌不如鶯。","鄉國真堪戀，光陰可合輕。","三年遇寒食，盡在洛陽城。"]', '["上苑风煙好，中橋道路平。","蹴毬塵不起，潑火雨新晴。","宿醉头仍重，晨游眼乍明。","老慵雖省事，春誘尚多情。","遇客踟躕立，尋花取次行。","連錢嚼金勒，鑿落寫銀罌。","府醞傷教送，官娃豈要迎。","舞腰那及柳，歌舌不如鶯。","乡国真堪戀，光陰可合轻。","三年遇寒食，尽在洛陽城。"]', '诗', 'shi', '', NULL, '洛橋寒食日作十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abd0cd0e-97b9-4a67-a1b5-4792a2c372aa', '快活', '快活', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["可惜鶯啼花落處，一壺濁酒送殘春。","可憐月好風涼夜，一部清商伴老身。","飽食安眠消日月，閑談冷笑接交親。","誰知將相王侯外，別有優游快活人。"]', '["可惜鶯啼花落处，一壺濁酒送殘春。","可怜月好风涼夜，一部清商伴老身。","飽食安眠消日月，闲談冷笑接交親。","誰知將相王侯外，別有優游快活人。"]', '诗', 'shi', '', NULL, '快活 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acab01b4-43e9-4f17-a94f-7d851fdd94e8', '送令狐相公赴太原', '送令狐相公赴太原', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["六纛雙旌萬鐵衣，幷汾舊路滿光輝。","青衫書記何年去，紅斾將軍昨日歸。","詩作馬蹄隨筆走，獵酣鷹翅伴觥飛。","此都莫作多時計，再爲蒼生入紫微。"]', '["六纛雙旌万鐵衣，幷汾旧路满光輝。","青衫书記何年去，紅斾將軍昨日归。","诗作马蹄隨笔走，獵酣鷹翅伴觥飞。","此都莫作多时計，再爲蒼生入紫微。"]', '诗', 'shi', '', NULL, '送令狐相公赴太原 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee9fe31-acd1-4464-95b0-d5acf9de17b9', '不出', '不出', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["簷前新葉覆殘花，席上餘桮對早茶。","好是老身銷日處，誰能騎馬傍人家。"]', '["簷前新葉覆殘花，席上餘桮对早茶。","好是老身銷日处，誰能騎马傍人家。"]', '诗', 'shi', '', NULL, '不出 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94e24f31-18de-49fa-97f1-cb5cdc0560e9', '惜落花', '惜落花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜來風雨急，無復舊花林。","枝上三分落，園中二寸深。","日斜啼鳥思，春盡老人心。","莫怪添桮飲，情多酒不禁。"]', '["夜来风雨急，無复旧花林。","枝上三分落，园中二寸深。","日斜啼鸟思，春尽老人心。","莫怪添桮饮，情多酒不禁。"]', '诗', 'shi', '', NULL, '惜落花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545723e9-3bab-484c-a54c-70a95c51b8a3', '老病', '老病', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晝聽笙歌夜醉眠，若非月下即花前。","如今老病須知分，不負春來二十年。"]', '["晝听笙歌夜醉眠，若非月下即花前。","如今老病須知分，不負春来二十年。"]', '诗', 'shi', '', NULL, '老病 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1544581f-5ec2-41b8-af81-83ddfe3b1f8d', '憶晦叔', '憶晦叔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遊山弄水攜詩卷，看月尋花把酒桮。","六事盡思君作伴，幾時歸到洛陽來。"]', '["游山弄水携诗卷，看月尋花把酒桮。","六事尽思君作伴，幾时归到洛陽来。"]', '诗', 'shi', '', NULL, '憶晦叔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d0a663a-582a-44c5-8389-b1471d377b3c', '送徐州高僕射赴鎮', '送徐州高僕射赴鎮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["大紅斾引碧幢旌，新拜將軍指點行。","戰將易求何足貴，書生難得始堪榮。","離筵歌舞花叢散，候騎刀槍雪隊迎。","應笑蹉跎白頭尹，風塵唯管洛陽城。"]', '["大紅斾引碧幢旌，新拜將軍指点行。","戰將易求何足貴，书生难得始堪榮。","離筵歌舞花叢散，候騎刀槍雪隊迎。","應笑蹉跎白头尹，风塵唯管洛陽城。"]', '诗', 'shi', '', NULL, '送徐州高僕射赴鎮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b33dd6-2b36-45ae-9938-268229e7ead2', '琴酒', '琴酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["耳根得聽琴初暢，心地忘機酒半酣。","若使啓期兼解醉，應言四樂不言三。"]', '["耳根得听琴初暢，心地忘機酒半酣。","若使啓期兼解醉，應言四乐不言三。"]', '诗', 'shi', '', NULL, '琴酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a985da00-109a-4637-9572-d9586e4ab8e8', '聽幽蘭', '听幽蘭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["琴中古曲是幽蘭，爲我慇懃更弄看。","欲得身心俱靜好，自彈不及聽人彈。"]', '["琴中古曲是幽蘭，爲我慇懃更弄看。","欲得身心俱静好，自彈不及听人彈。"]', '诗', 'shi', '', NULL, '聽幽蘭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44a5dc80-55aa-4d6b-9c62-25fea11a1dc9', '六年秋重題白蓮', '六年秋重題白蓮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["素房含露玉冠鮮，紺葉搖風鈿扇圓。","本是吳州供進藕，今爲伊水寄生蓮。","移根到此三千里，結子經今六七年。","不獨池中花故舊，兼乘舊日採花船。"]', '["素房含露玉冠鲜，紺葉搖风鈿扇圓。","本是吳州供進藕，今爲伊水寄生蓮。","移根到此三千里，結子經今六七年。","不独池中花故旧，兼乘旧日採花船。"]', '诗', 'shi', '', NULL, '六年秋重題白蓮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9279ca45-262c-4d33-bb5c-894d1e394a23', '元相公挽歌詞三首 一', '元相公挽歌词三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["銘旌官重威儀盛，騎吹聲繁鹵簿長。","後魏帝孫唐宰相，六年七月葬咸陽。"]', '["銘旌官重威儀盛，騎吹声繁鹵簿长。","後魏帝孫唐宰相，六年七月葬咸陽。"]', '诗', 'shi', '', NULL, '元相公挽歌詞三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aeae636-0c10-4f56-bfde-7117b3aeb972', '元相公挽歌詞三首 二', '元相公挽歌词三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["墓門已閉笳簫去，唯有夫人哭不休。","蒼蒼露草咸陽壠，此是千秋第一秋。"]', '["墓门已閉笳簫去，唯有夫人哭不休。","蒼蒼露草咸陽壠，此是千秋第一秋。"]', '诗', 'shi', '', NULL, '元相公挽歌詞三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7671d638-703a-41d4-b478-4fa8fdac62b1', '元相公挽歌詞三首 三', '元相公挽歌词三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["送葬萬人皆慘澹，反虞駟馬亦悲鳴。","琴書劒珮誰收拾，三歲遺孤新學行。"]', '["送葬万人皆慘澹，反虞駟马亦悲鳴。","琴书劒珮誰收拾，三歲遺孤新学行。"]', '诗', 'shi', '', NULL, '元相公挽歌詞三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b8a84ee-47b7-4e37-a47c-2ea383d69a99', '臥聽法曲霓裳', '臥听法曲霓裳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金磬玉笙調已久，牙牀角枕睡常遲。","朦朧閑夢初成後，宛轉柔聲入破時。","樂可理心應不謬，酒能陶性信無疑。","起嘗殘酌聽餘曲，斜背銀缸半下帷。"]', '["金磬玉笙調已久，牙牀角枕睡常遲。","朦朧闲梦初成後，宛轉柔声入破时。","乐可理心應不謬，酒能陶性信無疑。","起嘗殘酌听餘曲，斜背銀缸半下帷。"]', '诗', 'shi', '', NULL, '臥聽法曲霓裳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df82fbf-916d-437d-9c85-e00951cc349d', '結之', '結之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歡愛今何在，悲啼亦是空。","同爲一夜夢，共過十年中。"]', '["歡愛今何在，悲啼亦是空。","同爲一夜梦，共過十年中。"]', '诗', 'shi', '', NULL, '結之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e64ba6-5d47-42f8-9deb-7a63a68a0425', '五鳳樓晚望', '五鳳楼晚望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晴陽晚照濕煙銷，五鳳樓高天泬寥。","野綠全經朝雨洗，林紅半被暮雲燒。","龍門翠黛眉相對，伊水黃金線一條。","自入秋來風景好，就中最好是今朝。"]', '["晴陽晚照濕煙銷，五鳳楼高天泬寥。","野綠全經朝雨洗，林紅半被暮云燒。","龙门翠黛眉相对，伊水黄金線一條。","自入秋来风景好，就中最好是今朝。"]', '诗', 'shi', '', NULL, '五鳳樓晚望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('300dcb91-a371-4441-87dd-e60a6efd877a', '寄劉蘇州', '寄劉蘇州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["去年八月哭微之，今年八月哭敦詩。","何堪老淚交流日，多是秋風搖落時。","泣罷幾迴深自念，情來一倍苦相思。","同年同病同心事，除却蘇州更是誰。"]', '["去年八月哭微之，今年八月哭敦诗。","何堪老泪交流日，多是秋风搖落时。","泣罷幾迴深自念，情来一倍苦相思。","同年同病同心事，除却蘇州更是誰。"]', '诗', 'shi', '', NULL, '寄劉蘇州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a16eb0f-af60-4dd0-8823-b71ae52c6c18', '送客', '送客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病上籃輿相送來，衰容秋思兩悠哉。","涼風褭褭吹槐子，却請行人勸一桮。"]', '["病上籃輿相送来，衰容秋思兩悠哉。","涼风褭褭吹槐子，却請行人勸一桮。"]', '诗', 'shi', '', NULL, '送客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa0a689-f740-4d41-b2a5-7b488711796f', '秋思', '秋思', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夕照紅於燒，晴空碧勝藍。","獸形雲不一，弓勢月初三。","雁思來天北，砧愁滿水南。","蕭條秋氣味，未老已深諳。"]', '["夕照紅於燒，晴空碧勝藍。","獸形云不一，弓勢月初三。","雁思来天北，砧愁满水南。","蕭條秋氣味，未老已深諳。"]', '诗', 'shi', '', NULL, '秋思 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da5d0377-2e65-4451-b965-1e63dca82383', '酬夢得秋夕不寐見寄', '酬梦得秋夕不寐见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["碧簟絳紗帳，夜涼風景清。","病聞和藥氣，渴聽碾茶聲。","露竹偷燈影，煙松護月明。","何言千里隔，秋思一時生。"]', '["碧簟絳紗帳，夜涼风景清。","病闻和藥氣，渴听碾茶声。","露竹偷灯影，煙松護月明。","何言千里隔，秋思一时生。"]', '诗', 'shi', '', NULL, '酬夢得秋夕不寐見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab72d60-7944-4ef1-b6a9-328c896251c6', '題周家歌者', '題周家歌者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["清緊如敲玉，深圓似轉簧。","一聲腸一斷，能有幾多腸。"]', '["清緊如敲玉，深圓似轉簧。","一声腸一斷，能有幾多腸。"]', '诗', 'shi', '', NULL, '題周家歌者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9e483fd-a0d3-49be-976e-27faad14176b', '憶夢得', '憶梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["齒髮各蹉跎，疎慵與病和。","愛花心在否，見酒興如何。","年長風情少，官高俗慮多。","幾時紅燭下，聞唱竹枝歌。"]', '["齒髮各蹉跎，疎慵與病和。","愛花心在否，见酒兴如何。","年长风情少，官高俗慮多。","幾时紅燭下，闻唱竹枝歌。"]', '诗', 'shi', '', NULL, '憶夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da56c3f9-586e-431d-9d4b-28303d311a96', '贈同座', '贈同座', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春黛雙蛾嫩，秋蓬兩鬢侵。","謀歡身太晚，恨老意彌深。","薄解燈前舞，尤能酒後吟。","花叢便不入，猶自未甘心。"]', '["春黛雙蛾嫩，秋蓬兩鬢侵。","謀歡身太晚，恨老意彌深。","薄解灯前舞，尤能酒後吟。","花叢便不入，猶自未甘心。"]', '诗', 'shi', '', NULL, '贈同座 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b08d742c-7d0a-4d94-96d5-f48dde14bd55', '失婢', '失婢', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宅院小牆庳，坊門帖牓遲。","舊恩慚自薄，前事悔難追。","籠鳥無常主，風花不戀枝。","今宵在何處，唯有月明知。"]', '["宅院小牆庳，坊门帖牓遲。","旧恩慚自薄，前事悔难追。","籠鸟無常主，风花不戀枝。","今宵在何处，唯有月明知。"]', '诗', 'shi', '', NULL, '失婢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1acea810-d596-43a5-9ecd-9bce21934e6e', '夜招晦叔', '夜招晦叔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["庭草留霜池結冰，黃昏鐘絕凍雲凝。","碧氈帳上正飄雪，紅火爐前初炷燈。","高調秦箏一兩弄，小花蠻榼二三升。","爲君更奏湘神曲，夜就儂來能不能。"]', '["庭草留霜池結冰，黄昏鐘絕凍云凝。","碧氈帳上正飄雪，紅火爐前初炷灯。","高調秦箏一兩弄，小花蠻榼二三升。","爲君更奏湘神曲，夜就儂来能不能。"]', '诗', 'shi', '', NULL, '夜招晦叔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31d1a842-3ff2-467c-9c3c-7976abc05124', '戲答皇甫監', '戲答皇甫監', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寒宵勸酒君須飲，君是孤眠七十身。","莫道非人身不煖，十分一醆煖於人。"]', '["寒宵勸酒君須饮，君是孤眠七十身。","莫道非人身不煖，十分一醆煖於人。"]', '诗', 'shi', '', NULL, '戲答皇甫監 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d7f4c3-7561-4896-8b20-4e89b2a11e20', '和楊師臯傷小姬英英', '和楊師臯傷小姬英英', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自從嬌騃一相依，共見楊花七度飛。","玳瑁牀空收枕席，琵琶弦斷倚屏幃。","人間有夢何曾入，泉下無家豈是歸。","墳上少啼留取淚，明年寒食更沾衣。"]', '["自從嬌騃一相依，共见楊花七度飞。","玳瑁牀空收枕席，琵琶弦斷倚屏幃。","人间有梦何曾入，泉下無家豈是归。","墳上少啼留取泪，明年寒食更沾衣。"]', '诗', 'shi', '', NULL, '和楊師臯傷小姬英英 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('104b0aa6-35d3-41f8-9961-a66fd899631c', '池邊即事', '池邊即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["氈帳胡琴出塞曲，蘭塘越櫂弄潮聲。","何言此處同風月，薊北江南萬里情。"]', '["氈帳胡琴出塞曲，蘭塘越櫂弄潮声。","何言此处同风月，薊北江南万里情。"]', '诗', 'shi', '', NULL, '池邊即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15030c88-7a2f-4850-9f3d-eb1c763080c7', '聞樂感鄰', '闻乐感鄰', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老去親朋零落盡，秋來弦管感傷多。","尚書宅畔悲鄰笛，廷尉門前歎雀羅。","綠綺窗空分妓女，絳紗帳掩罷笙歌。","歡娛未足身先去，爭奈書生薄命何。"]', '["老去親朋零落尽，秋来弦管感傷多。","尚书宅畔悲鄰笛，廷尉门前歎雀羅。","綠綺窗空分妓女，絳紗帳掩罷笙歌。","歡娛未足身先去，爭奈书生薄命何。"]', '诗', 'shi', '', NULL, '聞樂感鄰 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d6f94fa-23b0-4451-a96f-b8a9fc66bb57', '戊申歲暮詠懷三首 一', '戊申歲暮詠懷三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["窮冬月末兩三日，半百年過六七時。","龍尾趂朝無氣力，牛頭參道有心期。","榮華外物終須悟，老病傍人豈得知。","猶被妻兒教漸退，莫求致仕且分司。"]', '["窮冬月末兩三日，半百年過六七时。","龙尾趂朝無氣力，牛头參道有心期。","榮华外物終須悟，老病傍人豈得知。","猶被妻兒教漸退，莫求致仕且分司。"]', '诗', 'shi', '', NULL, '戊申歲暮詠懷三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7350629-440e-4864-80d4-2a65aa9a154f', '戊申歲暮詠懷三首 二', '戊申歲暮詠懷三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["唯生一女才十二，秪欠三年未六旬。","婚嫁累輕何怕老，飢寒心慣不憂貧。","紫泥丹筆皆經手，赤紱金章盡到身。","更擬踟躕覓何事，不歸嵩洛作閑人。"]', '["唯生一女才十二，秪欠三年未六旬。","婚嫁累轻何怕老，飢寒心慣不憂貧。","紫泥丹笔皆經手，赤紱金章尽到身。","更擬踟躕覓何事，不归嵩洛作闲人。"]', '诗', 'shi', '', NULL, '戊申歲暮詠懷三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e01ccfa-881b-4207-828a-97b2349a7e35', '戊申歲暮詠懷三首 三', '戊申歲暮詠懷三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七年囚閉作籠禽，但願開籠便入林。","幸得展張今日翅，不能辜負昔時心。","人間禍福愚難料，世上風波老不禁。","萬一差池似前事，又應追悔不抽簪。"]', '["七年囚閉作籠禽，但願开籠便入林。","幸得展張今日翅，不能辜負昔时心。","人间禍福愚难料，世上风波老不禁。","万一差池似前事，又應追悔不抽簪。"]', '诗', 'shi', '', NULL, '戊申歲暮詠懷三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3531e9e7-a673-42b3-bb4e-882ff7423bdb', '贈夢得', '贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["心中萬事不思量，坐倚屏風臥向陽。","漸覺詠詩猶老醜，豈宜憑酒更麄狂。","頭垂白髮我思退，脚蹋青雲君欲忙。","只有今春相伴在，花前賸醉兩三場。"]', '["心中万事不思量，坐倚屏风臥向陽。","漸覺詠诗猶老醜，豈宜憑酒更麄狂。","头垂白髮我思退，脚蹋青云君欲忙。","只有今春相伴在，花前賸醉兩三場。"]', '诗', 'shi', '', NULL, '贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c73e5eb-b53c-4bc7-87c8-896fe5e91b50', '想東遊五十韻', '想东游五十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海內時無事，江南歲有秋。","生民皆樂業，地主盡賢侯。","郊靜銷戎馬，城高逼斗牛。","平河七百里，沃壤二三州。","坐有湖山趣，行無風浪憂。","食寧妨解纜，寢不廢乘流。","泉石諳天竺，煙霞識虎丘。","餘芳認蘭澤，遺詠思蘋洲。","菡萏紅塗粉，菰蒲綠潑油。","鱗差漁戶舍，綺錯稻田溝。","紫洞藏仙窟，玄泉貯怪湫。","精神昂老鶴，姿彩媚潛蚪。","靜閱天工妙，閑窺物狀幽。","投竿出比目，擲果下獼猴。","味苦蓮心小，漿甜蔗節稠。","橘苞從自結，藕孔是誰鎪。","逐日移潮信，隨風變櫂謳。","遞夫交烈火，候吏次鳴騶。","梵塔形疑踊，閶門勢欲浮。","客迎攜酒榼，僧待置茶甌。","小宴閑談笑，初筵雅獻酬。","稍催朱蠟炬，徐動碧牙籌。","圓醆飛蓮子，長裾曳石榴。","柘枝隨畫鼓，調笑從香毬。","幕颺雲飄檻，簾褰月露鉤。","舞繁紅袖凝，歌切翠眉愁。","弦管寧容歇，桮盤未許收。","良辰宜酩酊，卒歲好優游。","鱠縷鮮仍細，蓴絲滑且柔。","飽餐爲日計，穩睡是身謀。","名媿空虛得，官知止足休。","自嫌猶屑屑，衆笑大悠悠。","物表疎形役，人寰足悔尤。","蛾須遠燈燭，兔勿近罝罘。","幻世春來夢，浮生水上漚。","百憂中莫入，一醉外何求。","未死癡王湛，無兒老鄧攸。","蜀琴安膝上，周易在牀頭。","去去無程客，行行不繫舟。","勞君頻問訊，勸我少淹留。","雲雨多分散，關山苦阻修。","一吟江月別，七見日星周。","珠玉傳新什，鵷鸞念故儔。","懸旌心宛轉，束楚意綢繆。","驛舫妝青雀，官槽䬴紫騮。","鏡湖期遠汎，禹穴約冥搜。","預掃題詩壁，先開望海樓。","飲思親履舄，宿憶竝衾裯。","志氣吾衰也，風情子在不。","應須相見後，別作一家遊。"]', '["海內时無事，江南歲有秋。","生民皆乐業，地主尽賢侯。","郊静銷戎马，城高逼斗牛。","平河七百里，沃壤二三州。","坐有湖山趣，行無风浪憂。","食寧妨解纜，寢不廢乘流。","泉石諳天竺，煙霞識虎丘。","餘芳認蘭澤，遺詠思蘋洲。","菡萏紅塗粉，菰蒲綠潑油。","鱗差漁戶舍，綺錯稻田溝。","紫洞藏仙窟，玄泉貯怪湫。","精神昂老鹤，姿彩媚潛蚪。","静閱天工妙，闲窺物狀幽。","投竿出比目，擲果下獼猴。","味苦蓮心小，漿甜蔗節稠。","橘苞從自結，藕孔是誰鎪。","逐日移潮信，隨风变櫂謳。","遞夫交烈火，候吏次鳴騶。","梵塔形疑踊，閶门勢欲浮。","客迎携酒榼，僧待置茶甌。","小宴闲談笑，初筵雅獻酬。","稍催朱蠟炬，徐动碧牙籌。","圓醆飞蓮子，长裾曳石榴。","柘枝隨畫鼓，調笑從香毬。","幕颺云飄檻，簾褰月露鉤。","舞繁紅袖凝，歌切翠眉愁。","弦管寧容歇，桮盤未許收。","良辰宜酩酊，卒歲好優游。","鱠縷鲜仍細，蓴絲滑且柔。","飽餐爲日計，穩睡是身謀。","名媿空虛得，官知止足休。","自嫌猶屑屑，衆笑大悠悠。","物表疎形役，人寰足悔尤。","蛾須远灯燭，兔勿近罝罘。","幻世春来梦，浮生水上漚。","百憂中莫入，一醉外何求。","未死癡王湛，無兒老鄧攸。","蜀琴安膝上，周易在牀头。","去去無程客，行行不繫舟。","勞君頻问訊，勸我少淹留。","云雨多分散，关山苦阻修。","一吟江月別，七见日星周。","珠玉傳新什，鵷鸾念故儔。","懸旌心宛轉，束楚意綢繆。","驛舫妝青雀，官槽䬴紫騮。","镜湖期远汎，禹穴約冥搜。","預掃題诗壁，先开望海楼。","饮思親履舄，宿憶竝衾裯。","志氣吾衰也，风情子在不。","應須相见後，別作一家游。"]', '诗', 'shi', '', NULL, '想東遊五十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b258b9b-2195-47d7-aff6-e0da75bbcc56', '病免後喜除賓客', '病免後喜除賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臥在漳濱滿十旬，起爲商皓伴三人。","從今且莫嫌身病，不病何由索得身。"]', '["臥在漳濱满十旬，起爲商皓伴三人。","從今且莫嫌身病，不病何由索得身。"]', '诗', 'shi', '', NULL, '病免後喜除賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0461e544-0911-4944-afcd-cb7ca4f34bf7', '長樂亭留別', '长乐亭留別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["灞滻風煙函谷路，曾經幾度別長安。","昔時蹙促爲遷客，今日從容自去官。","優詔幸分四皓秩，祖筵慚繼二疎歡。","塵纓世網重重縛，迴顧方知出得難。"]', '["灞滻风煙函谷路，曾經幾度別长安。","昔时蹙促爲遷客，今日從容自去官。","優詔幸分四皓秩，祖筵慚繼二疎歡。","塵纓世網重重縛，迴顧方知出得难。"]', '诗', 'shi', '', NULL, '長樂亭留別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6ff052-46ae-4a57-907a-b28a10352041', '陝府王大夫相迎偶贈', '陝府王大夫相迎偶贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫微閣老自多情，白首園公豈要迎。","伴我綠槐陰下歇，向君紅斾影前行。","綸巾髮少渾欹仄，籃轝肩齊甚穩平。","但問主人留幾日，分司賓客去無程。"]', '["紫微閣老自多情，白首园公豈要迎。","伴我綠槐陰下歇，向君紅斾影前行。","綸巾髮少渾欹仄，籃轝肩齊甚穩平。","但问主人留幾日，分司賓客去無程。"]', '诗', 'shi', '', NULL, '陝府王大夫相迎偶贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e592f003-9497-4ce0-afef-231973017049', '別陝州王司馬', '別陝州王司马', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["笙歌惆悵欲爲別，風景闌珊初過春。","爭得遣君詩不苦，黃河岸上白頭人。"]', '["笙歌惆悵欲爲別，风景闌珊初過春。","爭得遣君诗不苦，黄河岸上白头人。"]', '诗', 'shi', '', NULL, '別陝州王司馬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9911748-ed02-42c8-94e1-08a8968a7708', '將至東都先寄令狐留守', '將至东都先寄令狐留守', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃鳥無聲葉滿枝，閑吟想到洛城時。","惜逢金谷三春盡，恨拜銅樓一月遲。","詩境忽來還自得，醉鄉潛去與誰期。","東都添箇狂賓客，先報壺觴風月知。"]', '["黄鸟無声葉满枝，闲吟想到洛城时。","惜逢金谷三春尽，恨拜銅楼一月遲。","诗境忽来還自得，醉乡潛去與誰期。","东都添箇狂賓客，先報壺觴风月知。"]', '诗', 'shi', '', NULL, '將至東都先寄令狐留守 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da3ccf2c-9071-4540-9c06-485ee08ba64a', '荅崔十八見寄', '荅崔十八见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["明朝欲見琴尊伴，洗拭金桮拂玉徽。","君乞曹州刺史替，我拋刑部侍郎歸。","倚瘡老馬收蹄立，避箭高鴻盡翅飛。","豈料洛陽風月夜，故人垂老得相依。"]', '["明朝欲见琴尊伴，洗拭金桮拂玉徽。","君乞曹州刺史替，我拋刑部侍郎归。","倚瘡老马收蹄立，避箭高鴻尽翅飞。","豈料洛陽风月夜，故人垂老得相依。"]', '诗', 'shi', '', NULL, '荅崔十八見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0aa5c86-09f7-4217-a6cf-4908288e3530', '贈皇甫賓客', '贈皇甫賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["輕衣穩馬槐陰路，漸近東來漸少塵。","耳鬧久憎聞俗事，眼明初喜見閑人。","昔曾對作承華相，今復連爲博望賓。","始信淡交宜久遠，與君轉老轉相親。"]', '["轻衣穩马槐陰路，漸近东来漸少塵。","耳鬧久憎闻俗事，眼明初喜见闲人。","昔曾对作承华相，今复連爲博望賓。","始信淡交宜久远，與君轉老轉相親。"]', '诗', 'shi', '', NULL, '贈皇甫賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d24a24c-c4c4-498f-a45b-d345a7fee8a7', '歸履道宅', '归履道宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["驛吏引藤轝，家童開竹扉。","往時多暫住，今日是長歸。","眼下有衣食，耳邊無是非。","不論貧與富，飲水亦應肥。"]', '["驛吏引藤轝，家童开竹扉。","往时多暫住，今日是长归。","眼下有衣食，耳邊無是非。","不論貧與富，饮水亦應肥。"]', '诗', 'shi', '', NULL, '歸履道宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a3ad978-2075-452d-89cc-60ed2cecc697', '問江南物', '问江南物', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歸來未及問生涯，先問江南物在耶。","引手摩挲青石笋，迴頭點檢白蓮花。","蘇州舫故龍頭闇，王尹橋傾雁齒斜。","別有夜深惆悵事，月明雙鶴在裴家。"]', '["归来未及问生涯，先问江南物在耶。","引手摩挲青石笋，迴头点檢白蓮花。","蘇州舫故龙头闇，王尹橋傾雁齒斜。","別有夜深惆悵事，月明雙鹤在裴家。"]', '诗', 'shi', '', NULL, '問江南物 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81329510-177f-4290-9f45-91f2e2a2bae3', '蕭庶子相過', '蕭庶子相過', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["半日停車馬，何人在白家。","慇懃蕭庶子，愛酒不嫌茶。"]', '["半日停车马，何人在白家。","慇懃蕭庶子，愛酒不嫌茶。"]', '诗', 'shi', '', NULL, '蕭庶子相過 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da06a0b-654a-4ea8-ad5f-42be99b0f4f1', '荅尉遲少尹問所須', '荅尉遲少尹问所須', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["乍到頻勞問所須，所須非玉亦非珠。","愛君水閣宜閑詠，每有詩成許去無。"]', '["乍到頻勞问所須，所須非玉亦非珠。","愛君水閣宜闲詠，每有诗成許去無。"]', '诗', 'shi', '', NULL, '荅尉遲少尹問所須 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('129b8890-021e-4eb2-96d3-84b9ef07b83d', '詠閑', '詠闲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["但有閑銷日，都無事繫懷。","朝眠因客起，午飯伴僧齋。","樹合陰交戶，池分水夾階。","就中今夜好，風月似江淮。"]', '["但有闲銷日，都無事繫懷。","朝眠因客起，午飯伴僧斋。","樹合陰交戶，池分水夾階。","就中今夜好，风月似江淮。"]', '诗', 'shi', '', NULL, '詠閑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f515370-afa3-4d8c-831e-553fbc31be5d', '同崔十八寄元浙東王陝州', '同崔十八寄元浙东王陝州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["未能同隱雲林下，且復相招祿仕間。","隨月有錢勝賣藥，終年無事抵歸山。","鏡湖水遠何由汎，棠樹枝高不易攀。","惆悵八科殘四在，兩人榮鬧兩人閑。"]', '["未能同隐云林下，且复相招祿仕间。","隨月有錢勝賣藥，終年無事抵归山。","镜湖水远何由汎，棠樹枝高不易攀。","惆悵八科殘四在，兩人榮鬧兩人闲。"]', '诗', 'shi', '', NULL, '同崔十八寄元浙東王陝州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94dea6d7-8593-4d27-b958-cd7cf0c1687a', '荅蘇庶子月夜聞家僮奏樂見贈', '荅蘇庶子月夜闻家僮奏乐见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["牆西明月水東亭，一曲霓裳按小伶。","不敢邀君無別意，弦生管澀未堪聽。"]', '["牆西明月水东亭，一曲霓裳按小伶。","不敢邀君無別意，弦生管澀未堪听。"]', '诗', 'shi', '', NULL, '荅蘇庶子月夜聞家僮奏樂見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6520433b-3513-4a9b-85e9-d9adaf5ed311', '偶吟', '偶吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["里巷多通水，林園盡不扃。","松身爲外戶，池面是中庭。","元氏詩三帙，陳家酒一瓶。","醉來狂發詠，鄰女暎籬聽。"]', '["里巷多通水，林园尽不扃。","松身爲外戶，池面是中庭。","元氏诗三帙，陳家酒一瓶。","醉来狂發詠，鄰女暎籬听。"]', '诗', 'shi', '', NULL, '偶吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27abe2fc-5749-470b-9ba7-b371abcd7066', '白蓮池汎舟', '白蓮池汎舟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白藕新花照水開，紅窗小舫信風迴。","誰教一片江南興，逐我慇懃萬里來。"]', '["白藕新花照水开，紅窗小舫信风迴。","誰教一片江南兴，逐我慇懃万里来。"]', '诗', 'shi', '', NULL, '白蓮池汎舟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f3c55f-6f0c-4ef8-8644-0473187aa8fa', '池上即事', '池上即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["行尋甃石引新泉，坐看修橋補釣船。","綠竹挂衣涼處歇，清風展簟困時眠。","身閑當貴真天爵，官散無憂即地仙。","林下水邊無厭日，便堪終老豈論年。"]', '["行尋甃石引新泉，坐看修橋補釣船。","綠竹挂衣涼处歇，清风展簟困时眠。","身闲當貴真天爵，官散無憂即地仙。","林下水邊無厭日，便堪終老豈論年。"]', '诗', 'shi', '', NULL, '池上即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee43204-82fd-45d5-9e52-71c9a570f265', '酬裴相公見寄二絕 一', '酬裴相公见寄二絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["習靜心方泰，勞生事漸稀。","可憐安穩地，捨此欲何歸。"]', '["習静心方泰，勞生事漸稀。","可怜安穩地，捨此欲何归。"]', '诗', 'shi', '', NULL, '酬裴相公見寄二絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc0f5796-8f9a-47ad-93d5-27206ae38c3a', '酬裴相公見寄二絕 二', '酬裴相公见寄二絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一雙垂翅鶴，數首解嘲文。","總是迂閑物，爭堪伴相君。"]', '["一雙垂翅鹤，數首解嘲文。","總是迂闲物，爭堪伴相君。"]', '诗', 'shi', '', NULL, '酬裴相公見寄二絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0848de11-6e78-4a69-a20d-8f503e320d31', '荅夢得聞蟬見寄', '荅梦得闻蟬见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["開緘思浩然，獨詠晚風前。","人貌非前日，蟬聲似去年。","槐花新雨後，柳影欲秋天。","聽罷無他計，相思又一篇。"]', '["开緘思浩然，独詠晚风前。","人貌非前日，蟬声似去年。","槐花新雨後，柳影欲秋天。","听罷無他計，相思又一篇。"]', '诗', 'shi', '', NULL, '荅夢得聞蟬見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56ce8a48-d698-4ff1-a5d1-70dbe2c3a7c9', '令狐尚書許過弊居先贈長句', '令狐尚书許過弊居先贈长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不矜軒冕愛林泉，許到池頭一醉眠。","已遣平治行藥逕，兼教掃拂釣魚船。","應將筆硯隨詩主，定有笙歌伴酒仙。","祗候高情無別物，蒼苔石笋白花蓮。"]', '["不矜軒冕愛林泉，許到池头一醉眠。","已遣平治行藥逕，兼教掃拂釣鱼船。","應將笔硯隨诗主，定有笙歌伴酒仙。","祗候高情無別物，蒼苔石笋白花蓮。"]', '诗', 'shi', '', NULL, '令狐尚書許過弊居先贈長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('057e4259-0862-4bbf-ac19-f2e91720ce49', '自題', '自題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老宜官冷靜，貧賴俸優饒。","熱月無堆案，寒天不趂朝。","傍看應寂寞，自覺甚逍遙。","徒對盈尊酒，兼無愁可銷。"]', '["老宜官冷静，貧賴俸優饒。","熱月無堆案，寒天不趂朝。","傍看應寂寞，自覺甚逍遙。","徒对盈尊酒，兼無愁可銷。"]', '诗', 'shi', '', NULL, '自題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0024073c-14e3-4d76-822e-b905d3b6f6d7', '荅崔十八', '荅崔十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勞將白叟比黃公，今古由來事不同。","我有商山君未見，清泉白石在胸中。"]', '["勞將白叟比黄公，今古由来事不同。","我有商山君未见，清泉白石在胸中。"]', '诗', 'shi', '', NULL, '荅崔十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('625fd0b6-33da-4b00-b6d6-e03c2f1ab2ac', '偶詠', '偶詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["禦熱蕉衣健，扶羸竹杖輕。","誦經凭檻立，散藥繞廊行。","暝槿無風落，秋蟲欲雨鳴。","身閑當將息，病亦有心情。"]', '["禦熱蕉衣健，扶羸竹杖轻。","誦經凭檻立，散藥繞廊行。","暝槿無风落，秋蟲欲雨鳴。","身闲當將息，病亦有心情。"]', '诗', 'shi', '', NULL, '偶詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2efcf64-19cb-4834-88d5-d2481d4e18ff', '荅蘇六', '荅蘇六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["但喜暑隨三伏去，不知秋送二毛來。","更無別計相寬慰，故遣陽關勸一桮。"]', '["但喜暑隨三伏去，不知秋送二毛来。","更無別計相寬慰，故遣陽关勸一桮。"]', '诗', 'shi', '', NULL, '荅蘇六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bd83315-5205-4a7c-a12a-51589232880e', '秋遊', '秋游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["下馬閑行伊水頭，涼風清景勝春遊。","何事古今詩句裏，不多說著洛陽秋。"]', '["下马闲行伊水头，涼风清景勝春游。","何事古今诗句裏，不多说著洛陽秋。"]', '诗', 'shi', '', NULL, '秋遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bc83f62-9ca6-426c-8086-ce2cc97b54c3', '偶作', '偶作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["張翰一桮酒，榮期三樂歌。","聰明傷混沌，煩惱汚頭陁。","簟冷秋生早，堦閑日上多。","近來門更靜，無雀可張羅。"]', '["張翰一桮酒，榮期三乐歌。","聰明傷混沌，煩惱汚头陁。","簟冷秋生早，堦闲日上多。","近来门更静，無雀可張羅。"]', '诗', 'shi', '', NULL, '偶作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab7fb31-90ad-4737-b871-48e00fcd152f', '遊平原贈晦叔', '游平原贈晦叔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["照水容雖老，登山力未衰。","欲眠先命酒，暫歇亦吟詩。","且喜身無縛，終慙鬢有絲。","迴頭語閑伴，閑校十年遲。"]', '["照水容雖老，登山力未衰。","欲眠先命酒，暫歇亦吟诗。","且喜身無縛，終慙鬢有絲。","迴头語闲伴，闲校十年遲。"]', '诗', 'shi', '', NULL, '遊平原贈晦叔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('941995d2-23b6-461a-a742-151fbefda506', '不出門', '不出门', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不出門來又數旬，將何銷日與誰親。","鶴籠開處見君子，書卷展時逢古人。","自靜其心延壽命，無求於物長精神。","能行便是真修道，何必降魔調伏身。"]', '["不出门来又數旬，將何銷日與誰親。","鹤籠开处见君子，书卷展时逢古人。","自静其心延壽命，無求於物长精神。","能行便是真修道，何必降魔調伏身。"]', '诗', 'shi', '', NULL, '不出門 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959e7ad3-110a-48c4-bb5c-ee40e9628914', '歎鶴病', '歎鹤病', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["右翅低垂左脛傷，可憐風貌甚昂藏。","亦知白日青天好，未要高飛且養瘡。"]', '["右翅低垂左脛傷，可怜风貌甚昂藏。","亦知白日青天好，未要高飞且養瘡。"]', '诗', 'shi', '', NULL, '歎鶴病 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1099630e-cb16-494b-a990-eef0794ae50b', '臨都驛送崔十八', '臨都驛送崔十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勿言臨都五六里，扶病出城相送來。","莫道長安一步地，馬頭西去幾時迴。","與君後會知何處，爲我今朝盡一桮。"]', '["勿言臨都五六里，扶病出城相送来。","莫道长安一步地，马头西去幾时迴。","與君後會知何处，爲我今朝尽一桮。"]', '诗', 'shi', '', NULL, '臨都驛送崔十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e042ea2d-0c5c-4f50-8bc3-e2eecd4549c6', '對鏡', '对镜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三分鬢髮二分絲，曉鏡秋容相對時。","去作忙官應太老，退爲閑叟未全遲。","靜中得味何須道，穩處安身更莫疑。","若使至今黃綺在，聞吾此語亦分司。"]', '["三分鬢髮二分絲，晓镜秋容相对时。","去作忙官應太老，退爲闲叟未全遲。","静中得味何須道，穩处安身更莫疑。","若使至今黄綺在，闻吾此語亦分司。"]', '诗', 'shi', '', NULL, '對鏡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('170c4529-da68-4758-9dca-14a7ae904979', '勸酒十四首 何處難忘酒七首 一', '勸酒十四首 何处难忘酒七首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處難忘酒，長安喜氣新。","初登高第後，乍作好官人。","省壁明張牓，朝衣穩稱身。","此時無一醆，爭奈帝城春。"]', '["何处难忘酒，长安喜氣新。","初登高第後，乍作好官人。","省壁明張牓，朝衣穩稱身。","此时無一醆，爭奈帝城春。"]', '诗', 'shi', '', NULL, '勸酒十四首 何處難忘酒七首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5675bc63-ae80-4966-8014-2d9b91b10f29', '勸酒十四首 何處難忘酒七首 二', '勸酒十四首 何处难忘酒七首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處難忘酒，天涯話舊情。","青雲俱不達，白髮遞相驚。","二十年前別，三千里外行。","此時無一醆，何以敘平生。"]', '["何处难忘酒，天涯話旧情。","青云俱不達，白髮遞相驚。","二十年前別，三千里外行。","此时無一醆，何以敘平生。"]', '诗', 'shi', '', NULL, '勸酒十四首 何處難忘酒七首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b74db1-b72b-4f63-a7e7-0d942b62a43c', '勸酒十四首 何處難忘酒七首 三', '勸酒十四首 何处难忘酒七首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處難忘酒，朱門羨少年。","春分花發後，寒食月明前。","小院迴羅綺，深房理管弦。","此時無一醆，爭過豔陽天。"]', '["何处难忘酒，朱门羨少年。","春分花發後，寒食月明前。","小院迴羅綺，深房理管弦。","此时無一醆，爭過豔陽天。"]', '诗', 'shi', '', NULL, '勸酒十四首 何處難忘酒七首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('126e6a7e-f649-40ef-af70-a94af44a0569', '勸酒十四首 何處難忘酒七首 四', '勸酒十四首 何处难忘酒七首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處難忘酒，霜庭老病翁。","闇聲啼蟋蟀，乾葉落梧桐。","鬢爲愁先白，顏因醉暫紅。","此時無一醆，何計奈秋風。"]', '["何处难忘酒，霜庭老病翁。","闇声啼蟋蟀，乾葉落梧桐。","鬢爲愁先白，顏因醉暫紅。","此时無一醆，何計奈秋风。"]', '诗', 'shi', '', NULL, '勸酒十四首 何處難忘酒七首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec2cdd28-69a2-4f37-9561-0d02ed1aca7b', '勸酒十四首 何處難忘酒七首 五', '勸酒十四首 何处难忘酒七首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處難忘酒，軍功第一高。","還鄉隨露布，半路授旌旄。","玉柱剝葱手，金章爛椹袍。","此時無一醆，何以騁雄豪。"]', '["何处难忘酒，軍功第一高。","還乡隨露布，半路授旌旄。","玉柱剝葱手，金章爛椹袍。","此时無一醆，何以騁雄豪。"]', '诗', 'shi', '', NULL, '勸酒十四首 何處難忘酒七首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27063ff-16bc-4333-847e-d5b30ace29ab', '勸酒十四首 何處難忘酒七首 六', '勸酒十四首 何处难忘酒七首 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處難忘酒，青門送別多。","歛襟收涕淚，簇馬聽笙歌。","煙樹灞陵岸，風塵長樂坡。","此時無一醆，爭奈去留何。"]', '["何处难忘酒，青门送別多。","歛襟收涕泪，簇马听笙歌。","煙樹灞陵岸，风塵长乐坡。","此时無一醆，爭奈去留何。"]', '诗', 'shi', '', NULL, '勸酒十四首 何處難忘酒七首 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0164b588-486c-4f96-b1c1-fe2165b2a1e2', '勸酒十四首 何處難忘酒七首 七', '勸酒十四首 何处难忘酒七首 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處難忘酒，逐臣歸故園。","赦書逢驛騎，賀客出都門。","半面瘴煙色，滿衫鄉淚痕。","此時無一醆，何物可招魂。"]', '["何处难忘酒，逐臣归故园。","赦书逢驛騎，賀客出都门。","半面瘴煙色，满衫乡泪痕。","此时無一醆，何物可招魂。"]', '诗', 'shi', '', NULL, '勸酒十四首 何處難忘酒七首 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('331ec948-26e6-4ad3-bf97-5aac5a8f6661', '勸酒十四首 不如來飲酒七首 一', '勸酒十四首 不如来饮酒七首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫隱深山去，君應到自嫌。","齒傷朝水冷，貌苦夜霜嚴。","漁去風生浦，樵歸雪滿巖。","不如來飲酒，相對醉厭厭。"]', '["莫隐深山去，君應到自嫌。","齒傷朝水冷，貌苦夜霜嚴。","漁去风生浦，樵归雪满巖。","不如来饮酒，相对醉厭厭。"]', '诗', 'shi', '', NULL, '勸酒十四首 不如來飲酒七首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('430b85e6-224e-4c26-b82c-6228acda7bc4', '勸酒十四首 不如來飲酒七首 二', '勸酒十四首 不如来饮酒七首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫作農夫去，君應見自愁。","迎春犂瘦地，趂晚餧羸牛。","數被官加稅，稀逢歲有秋。","不如來飲酒，相伴醉悠悠。"]', '["莫作農夫去，君應见自愁。","迎春犂瘦地，趂晚餧羸牛。","數被官加稅，稀逢歲有秋。","不如来饮酒，相伴醉悠悠。"]', '诗', 'shi', '', NULL, '勸酒十四首 不如來飲酒七首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4e70600-7be6-4037-8992-940a7773517e', '勸酒十四首 不如來飲酒七首 三', '勸酒十四首 不如来饮酒七首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫作商人去，恓惶君未諳。","雪霜行塞北，風水宿江南。","藏鏹百千萬，沈舟十二三。","不如來飲酒，仰面醉酣酣。"]', '["莫作商人去，恓惶君未諳。","雪霜行塞北，风水宿江南。","藏鏹百千万，沈舟十二三。","不如来饮酒，仰面醉酣酣。"]', '诗', 'shi', '', NULL, '勸酒十四首 不如來飲酒七首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4161c70-be10-4148-b6c0-79be92bec1c7', '勸酒十四首 不如來飲酒七首 四', '勸酒十四首 不如来饮酒七首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫事長征去，辛勤難具論。","何曾畫麟閣，祗是老轅門。","蟣蝨衣中物，刀槍面上痕。","不如來飲酒，合眼醉昏昏。"]', '["莫事长征去，辛勤难具論。","何曾畫麟閣，祗是老轅门。","蟣蝨衣中物，刀槍面上痕。","不如来饮酒，合眼醉昏昏。"]', '诗', 'shi', '', NULL, '勸酒十四首 不如來飲酒七首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65eaed8e-1714-42a7-93be-017eea369da0', '勸酒十四首 不如來飲酒七首 五', '勸酒十四首 不如来饮酒七首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫學長生去，仙方悞殺君。","那將薤上露，擬待鶴邊雲。","矻矻皆燒藥，纍纍盡作墳。","不如來飲酒，閑坐醉醺醺。"]', '["莫学长生去，仙方悞殺君。","那將薤上露，擬待鹤邊云。","矻矻皆燒藥，纍纍尽作墳。","不如来饮酒，闲坐醉醺醺。"]', '诗', 'shi', '', NULL, '勸酒十四首 不如來飲酒七首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8f6ca8-92c4-438f-a645-3aac916af9a2', '勸酒十四首 不如來飲酒七首 六', '勸酒十四首 不如来饮酒七首 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫上青雲去，青雲足愛憎。","自賢誇智慧，相糺鬬功能。","魚爛緣吞餌，蛾燋爲撲燈。","不如來飲酒，任性醉騰騰。"]', '["莫上青云去，青云足愛憎。","自賢誇智慧，相糺鬬功能。","鱼爛緣吞餌，蛾燋爲撲灯。","不如来饮酒，任性醉腾腾。"]', '诗', 'shi', '', NULL, '勸酒十四首 不如來飲酒七首 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1d1a647-63de-4e4b-8026-bfe6bf5d8d19', '勸酒十四首 不如來飲酒七首 七', '勸酒十四首 不如来饮酒七首 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫入紅塵去，令人心力勞。","相爭兩蝸角，所得一牛毛。","且滅嗔中火，休磨笑裏刀。","不如來飲酒，穩臥醉陶陶。"]', '["莫入紅塵去，令人心力勞。","相爭兩蝸角，所得一牛毛。","且滅嗔中火，休磨笑裏刀。","不如来饮酒，穩臥醉陶陶。"]', '诗', 'shi', '', NULL, '勸酒十四首 不如來飲酒七首 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e23518e0-65d1-4890-81b1-5b557eb78555', '和令狐相公寄劉郎中兼見示長句', '和令狐相公寄劉郎中兼见示长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日月天衢仰面看，尚淹池鳳滯臺鸞。","碧幢千里空移鎮，赤筆三年未轉官。","別後縱吟終少興，病來雖飲不多歡。","酒軍詩敵如相遇，臨老猶能一據鞍。"]', '["日月天衢仰面看，尚淹池鳳滯台鸾。","碧幢千里空移鎮，赤笔三年未轉官。","別後縱吟終少兴，病来雖饮不多歡。","酒軍诗敵如相遇，臨老猶能一據鞍。"]', '诗', 'shi', '', NULL, '和令狐相公寄劉郎中兼見示長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b436b45f-f872-4455-b8da-3d99fd4012c6', '即事', '即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["見月連宵坐，聞風盡日眠。","室香羅藥氣，籠煖焙茶煙。","鶴啄新晴地，雞棲薄暮天。","自看淘酒米，倚杖小池前。"]', '["见月連宵坐，闻风尽日眠。","室香羅藥氣，籠煖焙茶煙。","鹤啄新晴地，雞棲薄暮天。","自看淘酒米，倚杖小池前。"]', '诗', 'shi', '', NULL, '即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abedde78-4e7b-4445-a43f-faa2f2b13bd3', '期宿客不至', '期宿客不至', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風飄雨灑簾帷故，竹暎松遮燈火深。","宿客不來嫌冷落，一尊酒對一張琴。"]', '["风飄雨灑簾帷故，竹暎松遮灯火深。","宿客不来嫌冷落，一尊酒对一張琴。"]', '诗', 'shi', '', NULL, '期宿客不至 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99800513-46d2-4f7c-84b2-be96f8206138', '問移竹', '问移竹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["問君移竹意如何，慎勿排行但間窠。","多種少栽皆有意，大都少校不如多。"]', '["问君移竹意如何，慎勿排行但间窠。","多種少栽皆有意，大都少校不如多。"]', '诗', 'shi', '', NULL, '問移竹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29611f25-d27c-4485-920f-d9ab1cfc8a18', '重陽席上賦白菊', '重陽席上賦白菊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿園花菊鬱金黃，中有孤叢色似霜。","還似今朝歌酒席，白頭翁入少年場。"]', '["满园花菊鬱金黄，中有孤叢色似霜。","還似今朝歌酒席，白头翁入少年場。"]', '诗', 'shi', '', NULL, '重陽席上賦白菊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcee09cf-8460-4b79-bd54-23b0c82c33eb', '偶吟二首 一', '偶吟二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["眼下有衣兼有食，心中無喜亦無憂。","正如身後有何事，應向人間無所求。","靜念道經深閉目，閑迎禪客小低頭。","猶殘少許雲泉興，一歲龍門數度遊。"]', '["眼下有衣兼有食，心中無喜亦無憂。","正如身後有何事，應向人间無所求。","静念道經深閉目，闲迎禪客小低头。","猶殘少許云泉兴，一歲龙门數度游。"]', '诗', 'shi', '', NULL, '偶吟二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('535fef96-ff6b-44f3-b0a4-ecdef79f5331', '偶吟二首 二', '偶吟二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晴教曬藥泥茶竈，閑看科松洗竹林。","活計縱貧長淨潔，池亭雖小頗幽深。","廚香炊黍調和酒，窗暖安弦拂拭琴。","老去生涯祗如此，更無餘事可勞心。"]', '["晴教曬藥泥茶竈，闲看科松洗竹林。","活計縱貧长淨潔，池亭雖小頗幽深。","廚香炊黍調和酒，窗暖安弦拂拭琴。","老去生涯祗如此，更無餘事可勞心。"]', '诗', 'shi', '', NULL, '偶吟二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7caa199c-ae4d-4abd-ac07-6b3e3e80f50e', '何處春先到', '何处春先到', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處春先到，橋東水北亭。","凍花開未得，冷酒酌難醒。","就日移輕榻，遮風展小屏。","不勞人勸醉，鶯語漸丁寧。"]', '["何处春先到，橋东水北亭。","凍花开未得，冷酒酌难醒。","就日移轻榻，遮风展小屏。","不勞人勸醉，鶯語漸丁寧。"]', '诗', 'shi', '', NULL, '何處春先到 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0674f13a-ed30-4516-b15a-ee5fdd1c7b8a', '勉閑遊', '勉闲游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天時人事常多故，一歲春能幾處遊。","不是塵埃便風雨，若非疾病即悲憂。","貧窮心苦多無興，富貴身忙不自由。","唯有分司官恰好，閑遊雖老未能休。"]', '["天时人事常多故，一歲春能幾处游。","不是塵埃便风雨，若非疾病即悲憂。","貧窮心苦多無兴，富貴身忙不自由。","唯有分司官恰好，闲游雖老未能休。"]', '诗', 'shi', '', NULL, '勉閑遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab89f06a-c738-43c3-aa4c-c29cda738f04', '寄兩銀榼與裴侍郎因題兩絕句 一', '寄兩銀榼與裴侍郎因題兩絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["貧無好物堪爲信，雙榼雖輕意不輕。","願奉謝公池上酌，丹心綠酒一時傾。"]', '["貧無好物堪爲信，雙榼雖轻意不轻。","願奉謝公池上酌，丹心綠酒一时傾。"]', '诗', 'shi', '', NULL, '寄兩銀榼與裴侍郎因題兩絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe580e6-2934-4e80-8410-116c7213b174', '寄兩銀榼與裴侍郎因題兩絕句 二', '寄兩銀榼與裴侍郎因題兩絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慣和麴糵堪盛否，重用鹽梅試洗看。","小器不知容幾許，襄陽米賤酒升寬。"]', '["慣和麴糵堪盛否，重用鹽梅試洗看。","小器不知容幾許，襄陽米賤酒升寬。"]', '诗', 'shi', '', NULL, '寄兩銀榼與裴侍郎因題兩絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c63ccc1-2995-4dc6-a80c-1b6a1241c3e0', '小橋柳', '小橋柳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["細水涓涓似淚流，日西惆悵小橋頭。","衰楊葉盡空枝在，猶被霜風吹不休。"]', '["細水涓涓似泪流，日西惆悵小橋头。","衰楊葉尽空枝在，猶被霜风吹不休。"]', '诗', 'shi', '', NULL, '小橋柳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f33fa93c-572e-4d82-b6b0-f18e4632982c', '哭微之二首 一', '哭微之二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["八月涼風吹白幕，寢門廊下哭微之。","妻孥朋友來相弔，唯道皇天無所知。"]', '["八月涼风吹白幕，寢门廊下哭微之。","妻孥朋友来相弔，唯道皇天無所知。"]', '诗', 'shi', '', NULL, '哭微之二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5643776d-56eb-4c72-ae22-49a11d1fc0e0', '哭微之二首 二', '哭微之二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["文章卓犖生無敵，風骨英靈歿有神。","哭送咸陽北原上，可能隨例作灰塵。"]', '["文章卓犖生無敵，风骨英靈歿有神。","哭送咸陽北原上，可能隨例作灰塵。"]', '诗', 'shi', '', NULL, '哭微之二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be1b8708-5201-48d3-a7de-9aebf9ff583b', '馬上晚吟', '马上晚吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人少街荒已寂寥，風多塵起重蕭條。","上陽落葉飄宮樹，中渡流澌擁渭橋。","出早冒寒衣挍薄，歸遲侵黑酒全消。","如今不是閑行日，日短天陰坊曲遙。"]', '["人少街荒已寂寥，风多塵起重蕭條。","上陽落葉飄宮樹，中渡流澌擁渭橋。","出早冒寒衣挍薄，归遲侵黑酒全消。","如今不是闲行日，日短天陰坊曲遙。"]', '诗', 'shi', '', NULL, '馬上晚吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f07d66a-91a2-427a-a43d-d4940d963e7a', '醉中重留夢得', '醉中重留梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["劉郎劉郎莫先起，蘇臺蘇臺隔雲水。","酒醆來從一百分，馬頭去便三千里。"]', '["劉郎劉郎莫先起，蘇台蘇台隔云水。","酒醆来從一百分，马头去便三千里。"]', '诗', 'shi', '', NULL, '醉中重留夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0427c764-1d52-46ed-babb-d641183b7c23', '雪夜喜李郎中見訪兼酬所贈', '雪夜喜李郎中见訪兼酬所贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["可憐今夜鵝毛雪，引得高情鶴氅人。","紅蠟燭前明似晝，青氈帳裏暖如春。","十分滿醆黃金液，一尺中庭白玉塵。","對此欲留君便宿，詩情酒分合相親。"]', '["可怜今夜鵝毛雪，引得高情鹤氅人。","紅蠟燭前明似晝，青氈帳裏暖如春。","十分满醆黄金液，一尺中庭白玉塵。","对此欲留君便宿，诗情酒分合相親。"]', '诗', 'shi', '', NULL, '雪夜喜李郎中見訪兼酬所贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91d4bed5-1ea1-4a13-bded-1e035363d903', '任老', '任老', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不愁陌上春光盡，亦任庭前日影斜。","面黑眼昏頭雪白，老應無可更增加。"]', '["不愁陌上春光尽，亦任庭前日影斜。","面黑眼昏头雪白，老應無可更增加。"]', '诗', 'shi', '', NULL, '任老 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed1aa7ed-fe99-47af-8398-86e280de9470', '勸歡', '勸歡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["火急歡娛慎勿遲，眼看老病悔難追。","尊前花下歌筵裏，會有求來不得時。"]', '["火急歡娛慎勿遲，眼看老病悔难追。","尊前花下歌筵裏，會有求来不得时。"]', '诗', 'shi', '', NULL, '勸歡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17d53913-cc9a-441e-869e-b47a6c8e6664', '荅王尚書問履道池舊橋', '荅王尚书问履道池旧橋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["虹梁雁齒隨年換，素板朱欄逐日修。","但恨尚書能久別，莫忘州守不頻遊。","重移舊柱開中眼，亂種新花擁兩頭。","李郭小船何足問，待君乘過濟川舟。"]', '["虹梁雁齒隨年換，素板朱欄逐日修。","但恨尚书能久別，莫忘州守不頻游。","重移旧柱开中眼，亂種新花擁兩头。","李郭小船何足问，待君乘過濟川舟。"]', '诗', 'shi', '', NULL, '荅王尚書問履道池舊橋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a57665af-c94d-4271-98d1-a9035bbbc5f4', '晚歸府', '晚归府', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚從履道來歸府，街路雖長尹不嫌。","馬上涼於牀上坐，綠槐風透紫蕉衫。"]', '["晚從履道来归府，街路雖长尹不嫌。","马上涼於牀上坐，綠槐风透紫蕉衫。"]', '诗', 'shi', '', NULL, '晚歸府 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23358244-82d2-45a4-b12b-c6675502abb5', '從龍潭寺至少林寺題贈同遊者', '從龙潭寺至少林寺題贈同游者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山屐田衣六七賢，搴芳蹋翠弄潺湲。","九龍潭月落桮酒，三品松風飄管弦。","強健且宜遊勝地，清涼不覺過炎天。","始知駕鶴乘雲外，別有逍遙地上仙。"]', '["山屐田衣六七賢，搴芳蹋翠弄潺湲。","九龙潭月落桮酒，三品松风飄管弦。","強健且宜游勝地，清涼不覺過炎天。","始知駕鹤乘云外，別有逍遙地上仙。"]', '诗', 'shi', '', NULL, '從龍潭寺至少林寺題贈同遊者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b49d16-df1b-4df1-8671-cd6c4bcece95', '夜從法王寺下歸嶽寺', '夜從法王寺下归嶽寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雙剎夾虛空，緣雲一徑通。","似從忉利下，如過劒門中。","燈火光初合，笙歌曲未終。","可憐獅子座，舁出淨名翁。"]', '["雙剎夾虛空，緣云一徑通。","似從忉利下，如過劒门中。","灯火光初合，笙歌曲未終。","可怜獅子座，舁出淨名翁。"]', '诗', 'shi', '', NULL, '夜從法王寺下歸嶽寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cefade4-ae6e-495e-ba2b-db2a162c7544', '宿龍潭寺', '宿龙潭寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜上九潭誰是伴，雲隨飛蓋月隨桮。","明年尚作三川守，此地兼將歌舞來。"]', '["夜上九潭誰是伴，云隨飞蓋月隨桮。","明年尚作三川守，此地兼將歌舞来。"]', '诗', 'shi', '', NULL, '宿龍潭寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f993a332-d674-421b-b8c5-5a7df6792ac4', '嵩陽觀夜奏霓裳', '嵩陽观夜奏霓裳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["開元遺曲自淒涼，況近秋天調是商。","愛者誰人唯白尹，奏時何處在嵩陽。","迴臨山月聲彌怨，散入松風韻更長。","子晉少姨聞定怪，人間亦便有霓裳。"]', '["开元遺曲自淒涼，況近秋天調是商。","愛者誰人唯白尹，奏时何处在嵩陽。","迴臨山月声彌怨，散入松风韻更长。","子晉少姨闻定怪，人间亦便有霓裳。"]', '诗', 'shi', '', NULL, '嵩陽觀夜奏霓裳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd511e6f-8ebc-499f-a9ed-1216b34b3dc5', '過元家履信宅', '過元家履信宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雞犬喪家分散後，林園失主寂寥時。","落花不語空辭樹，流水無情自入池。","風蕩醼船初破漏，雨淋歌閣欲傾欹。","前庭後院傷心事，唯是春風秋月知。"]', '["雞犬喪家分散後，林园失主寂寥时。","落花不語空辞樹，流水無情自入池。","风蕩醼船初破漏，雨淋歌閣欲傾欹。","前庭後院傷心事，唯是春风秋月知。"]', '诗', 'shi', '', NULL, '過元家履信宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('620190f9-ce46-4ac0-979a-2926f377fb5a', '和杜錄事題紅葉', '和杜錄事題紅葉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寒山十月旦，霜葉一時新。","似燒非因火，如花不待春。","連行排絳帳，亂落剪紅巾。","解駐籃轝看，風前唯兩人。"]', '["寒山十月旦，霜葉一时新。","似燒非因火，如花不待春。","連行排絳帳，亂落剪紅巾。","解駐籃轝看，风前唯兩人。"]', '诗', 'shi', '', NULL, '和杜錄事題紅葉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29f76e5-7ede-43dc-a9fe-052e756be427', '題崔常侍濟上別墅', '題崔常侍濟上別墅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["求榮爭寵任紛紛，脫棄金貂祗有君。","散員疏去未爲貴，小邑陶休何足云。","山色好當晴後見，泉聲宜向醉中聞。","主人憶爾爾知否，拋却青雲歸白雲。"]', '["求榮爭寵任紛紛，脫棄金貂祗有君。","散員疏去未爲貴，小邑陶休何足云。","山色好當晴後见，泉声宜向醉中闻。","主人憶爾爾知否，拋却青云归白云。"]', '诗', 'shi', '', NULL, '題崔常侍濟上別墅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b730d38-b7d0-48c0-a16a-a41b9c2685e8', '過溫尚書舊莊', '過溫尚书旧莊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白石清泉拋濟口，碧幢紅斾照河陽。","邨人都不知時事，猶自呼爲處士莊。"]', '["白石清泉拋濟口，碧幢紅斾照河陽。","邨人都不知时事，猶自呼爲处士莊。"]', '诗', 'shi', '', NULL, '過溫尚書舊莊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b04eb77-5a74-46a5-bbf9-24a5cca7dd90', '天壇峰下贈杜錄事', '天壇峰下贈杜錄事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年顏氣力漸衰殘，王屋中峰欲上難。","頂上將探小有洞，喉中須嚥大還丹。","河車九轉宜精鍊，火候三年在好看。","他日藥成分一粒，與君先去掃天壇。"]', '["年顏氣力漸衰殘，王屋中峰欲上难。","頂上將探小有洞，喉中須嚥大還丹。","河车九轉宜精鍊，火候三年在好看。","他日藥成分一粒，與君先去掃天壇。"]', '诗', 'shi', '', NULL, '天壇峰下贈杜錄事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04deb13e-52ad-4525-973a-0de929cc384c', '贈僧五首 鉢塔院如大師', '贈僧五首 鉢塔院如大師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百千萬劫菩提種，八十三年功德林。","若不秉持僧行苦，將何報答佛恩深。","慈悲不瞬諸天眼，清淨無塵幾地心。","每歲八關蒙九授，慇懃一戒重千金。"]', '["百千万劫菩提種，八十三年功德林。","若不秉持僧行苦，將何報答佛恩深。","慈悲不瞬諸天眼，清淨無塵幾地心。","每歲八关蒙九授，慇懃一戒重千金。"]', '诗', 'shi', '', NULL, '贈僧五首 鉢塔院如大師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4def9d24-051a-4e09-b119-55316b644f04', '贈僧五首 神照上人', '贈僧五首 神照上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["心如定水隨形應，口似懸河逐病治。","曾向衆中先禮拜，西方去日莫相遺。"]', '["心如定水隨形應，口似懸河逐病治。","曾向衆中先禮拜，西方去日莫相遺。"]', '诗', 'shi', '', NULL, '贈僧五首 神照上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e42689be-67b4-4431-8587-19f93f98c2af', '贈僧五首 自遠禪師', '贈僧五首 自远禪師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自出家來長自在，緣身一衲一繩牀。","令人見即心無事，每一相逢是道場。"]', '["自出家来长自在，緣身一衲一繩牀。","令人见即心無事，每一相逢是道場。"]', '诗', 'shi', '', NULL, '贈僧五首 自遠禪師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd4151e-a99b-408e-9d87-a19e2667081a', '贈僧五首 宗實上人', '贈僧五首 宗實上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["榮華恩愛棄成唾，戒定真如和作香。","今古雖殊同一法，瞿曇拋却轉輪王。"]', '["榮华恩愛棄成唾，戒定真如和作香。","今古雖殊同一法，瞿曇拋却轉輪王。"]', '诗', 'shi', '', NULL, '贈僧五首 宗實上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66ec2417-f842-4c8b-a8be-84fa0f9e874f', '贈僧五首 清閑上人', '贈僧五首 清闲上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["梓潼眷屬何年別，長壽壇場近日開。","應是蜀人皆度了，法輪移向洛中來。"]', '["梓潼眷屬何年別，长壽壇場近日开。","應是蜀人皆度了，法輪移向洛中来。"]', '诗', 'shi', '', NULL, '贈僧五首 清閑上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfcc1e2a-aa1f-4ffb-a4a6-5c56897ccb2c', '彈秋思', '彈秋思', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["信意閑彈秋思時，調清聲直韻疎遲。","近來漸喜無人聽，琴格高低心自知。"]', '["信意闲彈秋思时，調清声直韻疎遲。","近来漸喜無人听，琴格高低心自知。"]', '诗', 'shi', '', NULL, '彈秋思 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcfe87e1-db7b-482e-92d8-83dda9223c1a', '自詠', '自詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隨宜飲食聊充腹，取次衣裘亦煖身。","未必得年非瘦薄，無妨長福是單貧。","老龜豈羨犧牲飽，蟠木寧爭桃李春。","隨分自安心自斷，是非何用問閑人。"]', '["隨宜饮食聊充腹，取次衣裘亦煖身。","未必得年非瘦薄，無妨长福是單貧。","老龟豈羨犧牲飽，蟠木寧爭桃李春。","隨分自安心自斷，是非何用问闲人。"]', '诗', 'shi', '', NULL, '自詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd35a15-7789-487f-8fb7-8037519cbb4a', '分司初到洛中偶題六韻兼戲呈馮尹', '分司初到洛中偶題六韻兼戲呈馮尹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["相府念多病，春宮容不才。","官銜依口得，俸料逐身來。","白首林園在，紅塵車馬迴。","招呼新客侶，掃掠舊池臺。","小舫宜攜樂，新荷好蓋桮。","不知金谷主，早晚賀筵開。"]', '["相府念多病，春宮容不才。","官銜依口得，俸料逐身来。","白首林园在，紅塵车马迴。","招呼新客侶，掃掠旧池台。","小舫宜携乐，新荷好蓋桮。","不知金谷主，早晚賀筵开。"]', '诗', 'shi', '', NULL, '分司初到洛中偶題六韻兼戲呈馮尹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63ab766f-09f5-417f-8f36-53068bad7b47', '春風', '春风', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春風先發苑中梅，櫻杏桃梨次第開。","薺花榆莢深邨裏，亦道春風爲我來。"]', '["春风先發苑中梅，櫻杏桃梨次第开。","薺花榆莢深邨裏，亦道春风爲我来。"]', '诗', 'shi', '', NULL, '春風 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e02d8087-7962-4f39-9529-bbe3f7a427bd', '洛陽春', '洛陽春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛陽陌上春長在，惜別今來二十年。","唯覓少年心不得，其餘萬事盡依然。"]', '["洛陽陌上春长在，惜別今来二十年。","唯覓少年心不得，其餘万事尽依然。"]', '诗', 'shi', '', NULL, '洛陽春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc28335d-1c50-4b11-9ce3-9d4b0bfa90c2', '恨去年', '恨去年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老去唯耽酒，春來不著家。","去年來校晚，不見洛陽花。"]', '["老去唯耽酒，春来不著家。","去年来校晚，不见洛陽花。"]', '诗', 'shi', '', NULL, '恨去年 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dac9096-03e2-4fad-a9d5-d5247588d772', '早出晚歸', '早出晚归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早起或因攜酒出，晚歸多是看花迴。","若拋風景長閑坐，自問東京作底來。"]', '["早起或因携酒出，晚归多是看花迴。","若拋风景长闲坐，自问东京作底来。"]', '诗', 'shi', '', NULL, '早出晚歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95bf6c8f-60f1-47e0-b1d5-c0d01b9a0c21', '魏王堤', '魏王堤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花寒嬾發鳥慵啼，信馬閑行到日西。","何處未春先有思，柳條無力魏王堤。"]', '["花寒嬾發鸟慵啼，信马闲行到日西。","何处未春先有思，柳條無力魏王堤。"]', '诗', 'shi', '', NULL, '魏王堤 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a75592c2-f753-4bf0-80fe-46d26aaa0e79', '嘗黃醅新酎憶微之', '嘗黄醅新酎憶微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世間好物黃醅酒，天下閑人白侍郎。","愛向卯時謀洽樂，亦曾酉日放粗狂。","醉來枕麴貧如富，身後堆金有若亡。","元九計程殊未到，甕頭一醆共誰嘗。"]', '["世间好物黄醅酒，天下闲人白侍郎。","愛向卯时謀洽乐，亦曾酉日放粗狂。","醉来枕麴貧如富，身後堆金有若亡。","元九計程殊未到，甕头一醆共誰嘗。"]', '诗', 'shi', '', NULL, '嘗黃醅新酎憶微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfb7769-d8cd-4a37-8cc7-6825dc6fb4db', '勸行樂', '勸行乐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["少年信美何曾久，春日雖遲不再中。","歡笑勝愁歌勝哭，請君莫道等頭空。"]', '["少年信美何曾久，春日雖遲不再中。","歡笑勝愁歌勝哭，請君莫道等头空。"]', '诗', 'shi', '', NULL, '勸行樂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41b9065d-fd8b-4ab0-b4e6-157ac997972a', '老慵', '老慵', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豈是交親向我疎，老慵自愛閉門居。","近來漸喜知聞斷，免惱嵇康索報書。"]', '["豈是交親向我疎，老慵自愛閉门居。","近来漸喜知闻斷，免惱嵇康索報书。"]', '诗', 'shi', '', NULL, '老慵 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35e48220-8b62-4a31-bc8e-6f47f48ad039', '酬別微之', '酬別微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["[灃]頭峽口錢唐岸，三別都經二十年。","且喜筋骸俱健在，勿嫌鬚鬢各皤然。","君歸北闕朝天帝，我住東京作地仙。","博望自來非棄置，承明重入莫拘牽。","醉收桮杓停燈語，寒展衾裯對枕眠。","猶被分司官繫絆，送君不得過甘泉。"]', '["[灃]头峽口錢唐岸，三別都經二十年。","且喜筋骸俱健在，勿嫌鬚鬢各皤然。","君归北闕朝天帝，我住东京作地仙。","博望自来非棄置，承明重入莫拘牽。","醉收桮杓停灯語，寒展衾裯对枕眠。","猶被分司官繫絆，送君不得過甘泉。"]', '诗', 'shi', '', NULL, '酬別微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a37dedb1-2c20-42c5-ba34-0ce1f7115b2a', '予與微之老而無子發於言歎著在詩篇今年冬各有一子戲作二什一以相賀一以自嘲 一', '予與微之老而無子發於言歎著在诗篇今年冬各有一子戲作二什一以相賀一以自嘲 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["常憂到老都無子，何況新生又是兒。","陰德自然宜有慶，皇天可得道無知。","一園水竹今爲主，百卷文章更付誰。","莫慮鵷鶵無浴處，即應重入鳳皇池。"]', '["常憂到老都無子，何況新生又是兒。","陰德自然宜有慶，皇天可得道無知。","一园水竹今爲主，百卷文章更付誰。","莫慮鵷鶵無浴处，即應重入鳳皇池。"]', '诗', 'shi', '', NULL, '予與微之老而無子發於言歎著在詩篇今年冬各有一子戲作二什一以相賀一以自嘲 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ef28ff3-b8c8-4b9d-8d5b-7d9688419a27', '予與微之老而無子發於言歎著在詩篇今年冬各有一子戲作二什一以相賀一以自嘲 二', '予與微之老而無子發於言歎著在诗篇今年冬各有一子戲作二什一以相賀一以自嘲 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五十八翁方有後，靜思堪喜亦堪嗟。","一珠甚小還慚蚌，八子雖多不羨鴉。","秋月晚生丹桂實，春風新長紫蘭芽。","持桮祝願無他語，慎勿頑愚似汝爺。"]', '["五十八翁方有後，静思堪喜亦堪嗟。","一珠甚小還慚蚌，八子雖多不羨鴉。","秋月晚生丹桂實，春风新长紫蘭芽。","持桮祝願無他語，慎勿頑愚似汝爺。"]', '诗', 'shi', '', NULL, '予與微之老而無子發於言歎著在詩篇今年冬各有一子戲作二什一以相賀一以自嘲 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a1ca837-d486-4601-bb34-8a7b4d8cdd5c', '自問', '自问', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年來私自問，何故不歸京。","佩玉腰無力，看花眼不明。","老慵難發遣，春病易滋生。","賴有彈琴女，時時聽一聲。"]', '["年来私自问，何故不归京。","佩玉腰無力，看花眼不明。","老慵难發遣，春病易滋生。","賴有彈琴女，时时听一声。"]', '诗', 'shi', '', NULL, '自問 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24ce74cc-5141-4312-a1f9-04686bd90c94', '晚桃花', '晚桃花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一樹紅桃亞拂池，竹遮松蔭晚開時。","非因斜日無由見，不是閑人豈得知。","寒地生材遺挍易，貧家養女嫁常遲。","春深欲落誰憐惜，白侍郎來折一枝。"]', '["一樹紅桃亞拂池，竹遮松蔭晚开时。","非因斜日無由见，不是闲人豈得知。","寒地生材遺挍易，貧家養女嫁常遲。","春深欲落誰怜惜，白侍郎来折一枝。"]', '诗', 'shi', '', NULL, '晚桃花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('728b4fb6-68d0-489a-817d-4881ef033379', '夜調琴憶崔少卿', '夜調琴憶崔少卿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今夜調琴忽有情，欲彈惆悵憶崔卿。","何人解愛中徽上，秋思頭邊八九聲。"]', '["今夜調琴忽有情，欲彈惆悵憶崔卿。","何人解愛中徽上，秋思头邊八九声。"]', '诗', 'shi', '', NULL, '夜調琴憶崔少卿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc01555d-9800-4f45-bd7f-e25fb62876d1', '阿崔', '阿崔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謝病臥東都，羸然一老夫。","孤單同伯道，遲暮過商瞿。","豈料鬢成雪，方看掌弄珠。","已衰寧望有，雖晚亦勝無。","蘭入前春夢，桑懸昨日弧。","里閭多慶賀，親戚共歡娛。","膩剃新胎髮，香綳小繡襦。","玉芽開手爪，酥顆點肌膚。","弓冶將傳汝，琴書勿墜吾。","未能知壽夭，何暇慮賢愚。","乳氣初離殼，啼聲漸變雛。","何時能反哺，供養白頭烏。"]', '["謝病臥东都，羸然一老夫。","孤單同伯道，遲暮過商瞿。","豈料鬢成雪，方看掌弄珠。","已衰寧望有，雖晚亦勝無。","蘭入前春梦，桑懸昨日弧。","里閭多慶賀，親戚共歡娛。","膩剃新胎髮，香綳小繡襦。","玉芽开手爪，酥顆点肌膚。","弓冶將傳汝，琴书勿墜吾。","未能知壽夭，何暇慮賢愚。","乳氣初離殼，啼声漸变雛。","何时能反哺，供養白头烏。"]', '诗', 'shi', '', NULL, '阿崔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94b0f3e4-5bc9-4b87-ac5c-f309cef8f759', '贈鄰里往還', '贈鄰里往還', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["問予何故獨安然，免被飢寒婚嫁牽。","骨肉都盧無十口，糧儲依約有三年。","但能斗藪人間事，便是逍遙地上仙。","唯恐往還相厭賤，南家飲酒北家眠。"]', '["问予何故独安然，免被飢寒婚嫁牽。","骨肉都盧無十口，糧儲依約有三年。","但能斗藪人间事，便是逍遙地上仙。","唯恐往還相厭賤，南家饮酒北家眠。"]', '诗', 'shi', '', NULL, '贈鄰里往還 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75562208-45df-4293-b663-acac33e31611', '王子晉廟', '王子晉廟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["子晉廟前山月明，人聞往往夜吹笙。","鸞吟鳳唱聽無拍，多似霓裳散序聲。"]', '["子晉廟前山月明，人闻往往夜吹笙。","鸾吟鳳唱听無拍，多似霓裳散序声。"]', '诗', 'shi', '', NULL, '王子晉廟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9014fd06-8969-4fb7-8a05-d823bd668d70', '晚起', '晚起', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["起晚憐春暖，歸遲愛月明。","放慵長飽睡，聞健且閑行。","北闕停朝簿，西方入社名。","唯吟一句偈，無念是無生。"]', '["起晚怜春暖，归遲愛月明。","放慵长飽睡，闻健且闲行。","北闕停朝簿，西方入社名。","唯吟一句偈，無念是無生。"]', '诗', 'shi', '', NULL, '晚起 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a9ce1f9-46fa-4871-83ed-007e95f1f744', '酬皇甫賓客', '酬皇甫賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玄晏家風黃綺身，深居高臥養精神。","性慵無病常稱病，心足雖貧不道貧。","竹院君閑銷永日，花亭我醉送殘春。","自嫌詩酒猶多興，若比先生是俗人。"]', '["玄晏家风黄綺身，深居高臥養精神。","性慵無病常稱病，心足雖貧不道貧。","竹院君闲銷永日，花亭我醉送殘春。","自嫌诗酒猶多兴，若比先生是俗人。"]', '诗', 'shi', '', NULL, '酬皇甫賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc1d2a40-cef1-422c-8371-011ced271c57', '池上贈韋山人', '池上贈韋山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新竹夾平流，新荷拂小舟。","衆皆嫌好拙，誰肯伴閑遊。","客爲忙多去，僧因飯暫留。","獨憐韋處士，盡日共悠悠。"]', '["新竹夾平流，新荷拂小舟。","衆皆嫌好拙，誰肯伴闲游。","客爲忙多去，僧因飯暫留。","独怜韋处士，尽日共悠悠。"]', '诗', 'shi', '', NULL, '池上贈韋山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02334a47-6844-426c-a42c-bd513c558e5a', '無夢', '無梦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老眼花前闇，春衣雨後寒。","舊詩多忘却，新酒且嘗看。","拙定於身穩，慵應趂伴難。","漸銷名利想，無夢到長安。"]', '["老眼花前闇，春衣雨後寒。","旧诗多忘却，新酒且嘗看。","拙定於身穩，慵應趂伴难。","漸銷名利想，無梦到长安。"]', '诗', 'shi', '', NULL, '無夢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c2c7c44-7a0a-4a09-9d88-1290404d41a2', '對小潭寄遠上人', '对小潭寄远上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小潭澄見底，閑客坐開襟。","借問不流水，何如無念心。","彼惟清且淺，此乃寂而深。","是義誰能荅，明朝問道林。"]', '["小潭澄见底，闲客坐开襟。","借问不流水，何如無念心。","彼惟清且淺，此乃寂而深。","是義誰能荅，明朝问道林。"]', '诗', 'shi', '', NULL, '對小潭寄遠上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a372afdb-2ab8-4ef9-8e01-11acfdb99149', '閑吟二首 一', '闲吟二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["留司老賓客，春盡興如何。","官寺行香少，僧房寄宿多。","閑傾一醆酒，醉聽兩聲歌。","憶得陶潛語，羲皇無以過。"]', '["留司老賓客，春尽兴如何。","官寺行香少，僧房寄宿多。","闲傾一醆酒，醉听兩声歌。","憶得陶潛語，羲皇無以過。"]', '诗', 'shi', '', NULL, '閑吟二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e01fe77-9a43-4823-9fdb-7a6069fd7acd', '閑吟二首 二', '闲吟二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑遊來早晚，已得一周年。","嵩洛供雲水，朝廷乞俸錢。","長歌時獨酌，飽食後安眠。","聞道山榴發，明朝向玉泉。"]', '["闲游来早晚，已得一周年。","嵩洛供云水，朝廷乞俸錢。","长歌时独酌，飽食後安眠。","闻道山榴發，明朝向玉泉。"]', '诗', 'shi', '', NULL, '閑吟二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdaee7f6-98a8-4b91-9daf-348758f7dcad', '獨遊玉泉寺', '独游玉泉寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲樹玉泉寺，肩舁半日程。","更無人作伴，祗共酒同行。","新葉千萬影，殘鶯三兩聲。","閑遊竟未足，春盡有餘情。"]', '["云樹玉泉寺，肩舁半日程。","更無人作伴，祗共酒同行。","新葉千万影，殘鶯三兩声。","闲游竟未足，春尽有餘情。"]', '诗', 'shi', '', NULL, '獨遊玉泉寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd37ab6-5677-49a1-9e8c-4fd4d7ec697b', '晚出尋人不遇', '晚出尋人不遇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["籃轝不乘乘晚涼，相尋不遇亦無妨。","輕衣穩馬槐陰下，自要閑行一兩坊。"]', '["籃轝不乘乘晚涼，相尋不遇亦無妨。","轻衣穩马槐陰下，自要闲行一兩坊。"]', '诗', 'shi', '', NULL, '晚出尋人不遇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eed0454-c8dc-4d6b-89be-ce2a56a36414', '苦熱', '苦熱', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頭痛汗盈巾，連宵復達晨。","不堪逢苦熱，猶賴是閑人。","朝客應煩倦，農夫更苦辛。","始慙當此日，得作自由身。"]', '["头痛汗盈巾，連宵复達晨。","不堪逢苦熱，猶賴是闲人。","朝客應煩倦，農夫更苦辛。","始慙當此日，得作自由身。"]', '诗', 'shi', '', NULL, '苦熱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('968ae6c2-3e54-41fb-83a6-12bb479fff36', '銷暑', '銷暑', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何以銷煩暑，端居一院中。","眼前無長物，窗下有清風。","熱散由心靜，涼生爲室空。","此時身自得，難更與人同。"]', '["何以銷煩暑，端居一院中。","眼前無长物，窗下有清风。","熱散由心静，涼生爲室空。","此时身自得，难更與人同。"]', '诗', 'shi', '', NULL, '銷暑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a37e35be-7eb2-4ee0-921c-a02055ae4251', '行香歸', '行香归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["出作行香客，歸如坐夏僧。","牀前雙草屨，簷下一紗燈。","珮委腰無力，冠欹髮不勝。","鸞臺龍尾道，合盡少年登。"]', '["出作行香客，归如坐夏僧。","牀前雙草屨，簷下一紗灯。","珮委腰無力，冠欹髮不勝。","鸾台龙尾道，合尽少年登。"]', '诗', 'shi', '', NULL, '行香歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52b01d69-c9ed-43eb-ba7a-71c0a3d60fa5', '同王十七庶子李六員外鄭二侍御同年四人遊龍門有感而作', '同王十七庶子李六員外鄭二侍御同年四人游龙门有感而作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一曲悲歌酒一尊，同年零落幾人存。","世如閱水應堪歎，名是浮雲豈足論。","各從仕祿休明代，共感平生知己恩。","今日與君重上處，龍門不是舊龍門。"]', '["一曲悲歌酒一尊，同年零落幾人存。","世如閱水應堪歎，名是浮云豈足論。","各從仕祿休明代，共感平生知己恩。","今日與君重上处，龙门不是旧龙门。"]', '诗', 'shi', '', NULL, '同王十七庶子李六員外鄭二侍御同年四人遊龍門有感而作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f98359-792c-4502-b493-1c916b62e85b', '池上小宴問程秀才', '池上小宴问程秀才', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛下林園好自知，江南景物闇相隨。","淨淘紅粒罯香飯，薄切紫鱗烹水葵。","雨滴篷聲青雀舫，浪搖花影白蓮池。","停杯一問蘇州客，何似吳松江上時。"]', '["洛下林园好自知，江南景物闇相隨。","淨淘紅粒罯香飯，薄切紫鱗烹水葵。","雨滴篷声青雀舫，浪搖花影白蓮池。","停杯一问蘇州客，何似吳松江上时。"]', '诗', 'shi', '', NULL, '池上小宴問程秀才 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21fa156d-3f6d-49c0-9a6e-9db39f8bf166', '橋亭卯飲', '橋亭卯饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["卯時偶飲齋時臥，林下高橋橋上亭。","松影過窗眠始覺，竹風吹面醉初醒。","就荷葉上包魚鮓，當石渠中浸酒缾。","生計悠悠身兀兀，甘從妻喚作劉伶。"]', '["卯时偶饮斋时臥，林下高橋橋上亭。","松影過窗眠始覺，竹风吹面醉初醒。","就荷葉上包鱼鮓，當石渠中浸酒缾。","生計悠悠身兀兀，甘從妻喚作劉伶。"]', '诗', 'shi', '', NULL, '橋亭卯飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e11040-1dc3-4a6c-936b-5ad1b0b17ace', '舟中夜坐', '舟中夜坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潭邊霽後多清景，橋下涼來足好風。","秋鶴一雙船一隻，夜深相伴月明中。"]', '["潭邊霽後多清景，橋下涼来足好风。","秋鹤一雙船一隻，夜深相伴月明中。"]', '诗', 'shi', '', NULL, '舟中夜坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df6bde2-1979-41b9-9bc0-cae37434bfd6', '戲和微之荅竇七行軍之作', '戲和微之荅竇七行軍之作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["旌鉞從櫜鞬，賓僚禮數全。","夔龍來要地，鵷鷺下遼天。","赭汗騎驕馬，青娥舞醉仙。","合成江上作，散到洛中傳。","陋巷能無酒，貧池亦有船。","春裝秋未寄，謾道有閑錢。"]', '["旌鉞從櫜鞬，賓僚禮數全。","夔龙来要地，鵷鷺下遼天。","赭汗騎驕马，青娥舞醉仙。","合成江上作，散到洛中傳。","陋巷能無酒，貧池亦有船。","春裝秋未寄，謾道有闲錢。"]', '诗', 'shi', '', NULL, '戲和微之荅竇七行軍之作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa6f8fd6-9461-49e6-bbbf-69094f42595f', '閑忙', '闲忙', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["奔走朝行內，棲遲林墅間。","多因病後退，少及健時還。","斑白霜侵鬢，蒼黃日下山。","閑忙俱過日，忙挍不如閑。"]', '["奔走朝行內，棲遲林墅间。","多因病後退，少及健时還。","斑白霜侵鬢，蒼黄日下山。","闲忙俱過日，忙挍不如闲。"]', '诗', 'shi', '', NULL, '閑忙 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e99d734c-7070-4a97-bc7b-40dd3c3fec18', '西風', '西风', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西風來幾日，一葉已先飛。","新霽乘輕屐，初涼換熟衣。","淺渠銷慢水，疎竹漏斜暉。","薄暮青苔巷，家僮引鶴歸。"]', '["西风来幾日，一葉已先飞。","新霽乘轻屐，初涼換熟衣。","淺渠銷慢水，疎竹漏斜暉。","薄暮青苔巷，家僮引鹤归。"]', '诗', 'shi', '', NULL, '西風 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc51fd9a-5ede-4965-870a-f84c91e91f86', '題西亭', '題西亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["多見朱門富貴人，林園未畢即無身。","我今幸作西亭主，已見池塘五度春。"]', '["多见朱门富貴人，林园未畢即無身。","我今幸作西亭主，已见池塘五度春。"]', '诗', 'shi', '', NULL, '題西亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61ecb7d-60b0-4fc3-b570-c0a8189e8fa5', '觀游魚', '观游鱼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["繞池閑步看魚游，正值兒童弄釣舟。","一種愛魚心各異，我來施食爾垂鉤。"]', '["繞池闲步看鱼游，正值兒童弄釣舟。","一種愛鱼心各異，我来施食爾垂鉤。"]', '诗', 'shi', '', NULL, '觀游魚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f98b254c-9b18-4b26-9a27-e02684b086e5', '看採蓮', '看採蓮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小桃閑上小蓮船，半採紅蓮半白蓮。","不似江南惡風浪，芙蓉池在臥牀前。"]', '["小桃闲上小蓮船，半採紅蓮半白蓮。","不似江南惡风浪，芙蓉池在臥牀前。"]', '诗', 'shi', '', NULL, '看採蓮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe43c29-9ba8-4e50-9a81-1551890a8cbf', '看採菱', '看採菱', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["菱池如鏡淨無波，白點花稀青角多。","時唱一聲新水調，謾人道是採菱歌。"]', '["菱池如镜淨無波，白点花稀青角多。","时唱一声新水調，謾人道是採菱歌。"]', '诗', 'shi', '', NULL, '看採菱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff38d6b1-e797-4077-a203-4893b551703a', '夭老', '夭老', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早世身如風裏燭，暮年髮似鏡中絲。","誰人斷得人間事，少夭堪傷老又悲。"]', '["早世身如风裏燭，暮年髮似镜中絲。","誰人斷得人间事，少夭堪傷老又悲。"]', '诗', 'shi', '', NULL, '夭老 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4c9d4d-e062-42b3-8316-80ebfce176aa', '秋池', '秋池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洗浪清風透水霜，水邊閑坐一繩牀。","眼塵心垢見皆盡，不是秋池是道場。"]', '["洗浪清风透水霜，水邊闲坐一繩牀。","眼塵心垢见皆尽，不是秋池是道場。"]', '诗', 'shi', '', NULL, '秋池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4c5505a-88ad-49b8-9d62-2e3632d194b3', '登天宮閣', '登天宮閣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["午時乘興出，薄暮未能還。","高上煙中閣，平看雪後山。","委形羣動裏，任性一生間。","洛下多閑客，其中我最閑。"]', '["午时乘兴出，薄暮未能還。","高上煙中閣，平看雪後山。","委形羣动裏，任性一生间。","洛下多闲客，其中我最闲。"]', '诗', 'shi', '', NULL, '登天宮閣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ea5b1d9-d366-4e8e-a105-5305e0ce9146', '新雪二首 一', '新雪二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不思北省煙霄地，不憶南宮風月天。","唯憶靜恭楊閣老，小園新雪煖爐前。"]', '["不思北省煙霄地，不憶南宮风月天。","唯憶静恭楊閣老，小园新雪煖爐前。"]', '诗', 'shi', '', NULL, '新雪二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6746e7c3-b779-46fe-b639-023356abaa55', '新雪二首 二', '新雪二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不思朱雀街東鼓，不憶青龍寺後鐘。","唯憶夜深新雪後，新昌臺上七株松。"]', '["不思朱雀街东鼓，不憶青龙寺後鐘。","唯憶夜深新雪後，新昌台上七株松。"]', '诗', 'shi', '', NULL, '新雪二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b17cdfb-d181-4937-8492-18c6526bcaf0', '日高臥', '日高臥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["怕寒放嬾日高臥，臨老誰言牽率身。","夾幕繞房深似洞，重裀襯枕煖於春。","小青衣動桃根起，嫩綠醅浮竹葉新。","未裹頭前傾一醆，何如衝雪趂朝人。"]', '["怕寒放嬾日高臥，臨老誰言牽率身。","夾幕繞房深似洞，重裀襯枕煖於春。","小青衣动桃根起，嫩綠醅浮竹葉新。","未裹头前傾一醆，何如衝雪趂朝人。"]', '诗', 'shi', '', NULL, '日高臥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('141a584c-e120-41bd-aada-7742004a9258', '和微之任校書郎日過三鄉', '和微之任校书郎日過三乡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三鄉過日君年幾，今日君年五十餘。","不獨年催身亦變，校書郎變作尚書。"]', '["三乡過日君年幾，今日君年五十餘。","不独年催身亦变，校书郎变作尚书。"]', '诗', 'shi', '', NULL, '和微之任校書郎日過三鄉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de77138-1aed-487a-91a4-d8d58c49fb60', '和微之十七與君別及隴月花枝之詠', '和微之十七與君別及隴月花枝之詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["別時十七今頭白，惱亂君心三十年。","垂老休吟花月句，恐君更結後身緣。"]', '["別时十七今头白，惱亂君心三十年。","垂老休吟花月句，恐君更結後身緣。"]', '诗', 'shi', '', NULL, '和微之十七與君別及隴月花枝之詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b04ebb1-cc81-4c1c-a57e-0aa2afbd2f96', '和微之歎槿花', '和微之歎槿花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝榮殊可惜，暮落實堪嗟。","若向花中比，猶應勝眼花。"]', '["朝榮殊可惜，暮落實堪嗟。","若向花中比，猶應勝眼花。"]', '诗', 'shi', '', NULL, '和微之歎槿花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72508a9c-b467-4052-ab2b-84e0019c857f', '思往喜今', '思往喜今', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶除司馬向江州，及此凡經十五秋。","雖在簪裾從俗累，半尋山水是閑遊。","謫居終帶鄉關思，領郡猶分邦國憂。","爭似如今作賓客，都無一念到心頭。"]', '["憶除司马向江州，及此凡經十五秋。","雖在簪裾從俗累，半尋山水是闲游。","謫居終带乡关思，領郡猶分邦国憂。","爭似如今作賓客，都無一念到心头。"]', '诗', 'shi', '', NULL, '思往喜今 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c206fa0c-f6f0-47b2-ae41-360791f5961d', '題平泉薛家雪堆莊', '題平泉薛家雪堆莊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["怪石千年應自結，靈泉一帶是誰開。","蹙爲宛轉青蛇項，噴作玲瓏白雪堆。","赤日旱天長看雨，玄陰臘月亦聞雷。","所嗟地去都門遠，不得肩舁每日來。"]', '["怪石千年應自結，靈泉一带是誰开。","蹙爲宛轉青蛇項，噴作玲瓏白雪堆。","赤日旱天长看雨，玄陰臘月亦闻雷。","所嗟地去都门远，不得肩舁每日来。"]', '诗', 'shi', '', NULL, '題平泉薛家雪堆莊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecde3098-58c3-422e-92b1-6d78255b5995', '和微之道保生三日', '和微之道保生三日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["相看鬢似絲，始作弄璋詩。","且有承家望，誰論得力時。","莫興三日歎，猶勝七年遲。","我未能忘喜，君應不合悲。","嘉名稱道保，乞姓號崔兒。","但恐持相竝，蒹葭瓊樹枝。"]', '["相看鬢似絲，始作弄璋诗。","且有承家望，誰論得力时。","莫兴三日歎，猶勝七年遲。","我未能忘喜，君應不合悲。","嘉名稱道保，乞姓號崔兒。","但恐持相竝，蒹葭瓊樹枝。"]', '诗', 'shi', '', NULL, '和微之道保生三日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfe8691c-d2eb-4e25-b6ac-094d525c155c', '哭皇甫七郎中', '哭皇甫七郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["志業過玄晏，詞華似禰衡。","多才非福祿，薄命是聰明。","不得人間壽，還留身後名。","涉江文一首，便可敵公卿。"]', '["志業過玄晏，词华似禰衡。","多才非福祿，薄命是聰明。","不得人间壽，還留身後名。","涉江文一首，便可敵公卿。"]', '诗', 'shi', '', NULL, '哭皇甫七郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd6dd1f-bf4d-4a82-aeac-0459d9e87f95', '晚起', '晚起', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爛熳朝眠後，頻伸晚起時。","煖爐生火早，寒鏡裹頭遲。","融雪煎香茗，調酥煮乳糜。","慵饞還自哂，快活亦誰知。","酒性溫無毒，琴聲淡不悲。","榮公三樂外，仍弄小男兒。"]', '["爛熳朝眠後，頻伸晚起时。","煖爐生火早，寒镜裹头遲。","融雪煎香茗，調酥煮乳糜。","慵饞還自哂，快活亦誰知。","酒性溫無毒，琴声淡不悲。","榮公三乐外，仍弄小男兒。"]', '诗', 'shi', '', NULL, '晚起 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a207a4a-2fdf-46e9-8c3d-f831b9e623fb', '疑夢二首 一', '疑梦二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫驚寵辱虛憂喜，莫計恩讐浪苦辛。","黃帝孔丘無處問，安知不是夢中身。"]', '["莫驚寵辱虛憂喜，莫計恩讐浪苦辛。","黄帝孔丘無处问，安知不是梦中身。"]', '诗', 'shi', '', NULL, '疑夢二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf439ecc-7724-4703-a4da-777573f02643', '疑夢二首 二', '疑梦二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鹿疑鄭相終難辨，蝶化莊生詎可知。","假使如今不是夢，能長於夢幾多時。"]', '["鹿疑鄭相終难辨，蝶化莊生詎可知。","假使如今不是梦，能长於梦幾多时。"]', '诗', 'shi', '', NULL, '疑夢二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('919df5a8-f380-4a15-97d1-8ea586a6ee5b', '夜宴惜別', '夜宴惜別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["笙歌旖旎曲終頭，轉作離聲滿坐愁。","箏怨朱弦從此斷，燭啼紅淚爲誰流。","夜長似歲歡宜盡，醉未如泥飲莫休。","何況雞鳴即須別，門前風雨冷脩脩。"]', '["笙歌旖旎曲終头，轉作離声满坐愁。","箏怨朱弦從此斷，燭啼紅泪爲誰流。","夜长似歲歡宜尽，醉未如泥饮莫休。","何況雞鳴即須別，门前风雨冷脩脩。"]', '诗', 'shi', '', NULL, '夜宴惜別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b898c89-82a2-46d9-acb3-2d2577552423', '歸來二周歲', '归来二周歲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歸來二周歲，二歲似須臾。","池藕重生葉，林鴉再引雛。","時豐實倉廩，春暖葺庖廚。","更作三年計，三年身健無。"]', '["归来二周歲，二歲似須臾。","池藕重生葉，林鴉再引雛。","时豐實倉廩，春暖葺庖廚。","更作三年計，三年身健無。"]', '诗', 'shi', '', NULL, '歸來二周歲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05111aeb-2fcd-48fc-8d0c-a6dd4c7274b6', '吾土', '吾土', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身心安處爲吾土，豈限長安與洛陽。","水竹花前謀活計，琴詩酒裏到家鄉。","榮先生老何妨樂，楚接輿歌未必狂。","不用將金買莊宅，城東無主是春光。"]', '["身心安处爲吾土，豈限长安與洛陽。","水竹花前謀活計，琴诗酒裏到家乡。","榮先生老何妨乐，楚接輿歌未必狂。","不用將金買莊宅，城东無主是春光。"]', '诗', 'shi', '', NULL, '吾土 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3eea558-6a63-40c0-afea-19db68f28f2e', '題岐王舊山池石壁', '題岐王旧山池石壁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樹深藤老竹迴環，石壁重重錦翠斑。","俗客看來猶解愛，忙人到此亦須閑。","況當霽景涼風後，如在千巖萬壑間。","黃綺更歸何處去，洛陽城內有商山。"]', '["樹深藤老竹迴环，石壁重重錦翠斑。","俗客看来猶解愛，忙人到此亦須闲。","況當霽景涼风後，如在千巖万壑间。","黄綺更归何处去，洛陽城內有商山。"]', '诗', 'shi', '', NULL, '題岐王舊山池石壁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd2c8a3-117a-4fdf-a8b3-db2fc107d053', '病眼花', '病眼花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頭風目眩乘衰老，祗有增加豈有瘳。","花發眼中猶足怪，柳生肘上亦須休。","大窠羅綺看纔辨，小字文書見便愁。","必若不能分黑白，却應無悔復無尤。"]', '["头风目眩乘衰老，祗有增加豈有瘳。","花發眼中猶足怪，柳生肘上亦須休。","大窠羅綺看纔辨，小字文书见便愁。","必若不能分黑白，却應無悔复無尤。"]', '诗', 'shi', '', NULL, '病眼花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b22643fe-f413-4429-889a-46efafe7eef1', '早飲醉中除河南尹敕到', '早饮醉中除河南尹敕到', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪擁衡門水滿池，溫爐卯後煖寒時。","綠醅新酎嘗初醉，黃紙除書到不知。","厚俸自來誠忝濫，老身欲起尚遲疑。","應須了却丘中計，女嫁男婚三逕資。"]', '["雪擁衡门水满池，溫爐卯後煖寒时。","綠醅新酎嘗初醉，黄紙除书到不知。","厚俸自来誠忝濫，老身欲起尚遲疑。","應須了却丘中計，女嫁男婚三逕資。"]', '诗', 'shi', '', NULL, '早飲醉中除河南尹敕到 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9567e00d-04aa-4e56-b3f8-d513d78578cd', '除夜', '除夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病眼少眠非守歲，老心多感又臨春。","火銷燈盡天明後，便是平頭六十人。"]', '["病眼少眠非守歲，老心多感又臨春。","火銷灯尽天明後，便是平头六十人。"]', '诗', 'shi', '', NULL, '除夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1da54ac-493e-4957-8ed3-04312d994a5a', '府西池', '府西池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柳無氣力枝先動，池有波紋冰盡開。","今日不知誰計會，春風春水一時來。"]', '["柳無氣力枝先动，池有波紋冰尽开。","今日不知誰計會，春风春水一时来。"]', '诗', 'shi', '', NULL, '府西池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1da16782-2e2c-4d65-8d87-64203d26c2ff', '天津橋', '天津橋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["津橋東北斗亭西，到此令人詩思迷。","眉月晚生神女浦，臉波春傍窈娘堤。","柳絲褭褭風繰出，草縷茸茸雨剪齊。","報道前驅少呼喝，恐驚黃鳥不成啼。"]', '["津橋东北斗亭西，到此令人诗思迷。","眉月晚生神女浦，臉波春傍窈娘堤。","柳絲褭褭风繰出，草縷茸茸雨剪齊。","報道前驱少呼喝，恐驚黄鸟不成啼。"]', '诗', 'shi', '', NULL, '天津橋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('448201e3-351a-4d40-a790-0da20438af6a', '不准擬二首 一', '不准擬二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["籃轝騰騰一老夫，褐裘烏帽白髭鬚。","早衰饒病多蔬食，筋力消磨合有無。","不准擬身年六十，上山仍未要人扶。"]', '["籃轝腾腾一老夫，褐裘烏帽白髭鬚。","早衰饒病多蔬食，筋力消磨合有無。","不准擬身年六十，上山仍未要人扶。"]', '诗', 'shi', '', NULL, '不准擬二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47efd92-0c2c-4867-b8e7-b5cc5aa02325', '不准擬二首 二', '不准擬二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昔謫居炎瘴地，巴猿引哭虎隨行。","多於賈誼長沙苦，小挍潘安白髮生。","不准擬身年六十，遊春猶自有心情。"]', '["憶昔謫居炎瘴地，巴猿引哭虎隨行。","多於賈誼长沙苦，小挍潘安白髮生。","不准擬身年六十，游春猶自有心情。"]', '诗', 'shi', '', NULL, '不准擬二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2139cfca-2633-4d25-929b-84688c377f7d', '府中夜賞', '府中夜賞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["櫻桃廳院春偏好，石井欄堂夜更幽。","白粉牆頭花半出，緋紗燭下水平流。","閑留賓客嘗新酒，醉領笙歌上小舟。","舞袖飄颻櫂容與，忽疑身是夢中遊。"]', '["櫻桃廳院春偏好，石井欄堂夜更幽。","白粉牆头花半出，緋紗燭下水平流。","闲留賓客嘗新酒，醉領笙歌上小舟。","舞袖飄颻櫂容與，忽疑身是梦中游。"]', '诗', 'shi', '', NULL, '府中夜賞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93d50ae4-64bf-4302-8608-f02de262487c', '府西池北新葺水齋即事招賓偶題十六韻', '府西池北新葺水斋即事招賓偶題十六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["繚繞府西面，潺湲池北頭。","鑿開明月峽，決破白蘋洲。","清淺漪瀾急，夤緣浦嶼幽。","直衝行徑斷，平入臥齋流。","石疊青稜玉，波翻白片鷗。","噴時千點雨，澄處一泓油。","絕境應難別，同心豈易求。","少逢人愛翫，多是我淹留。","夾岸鋪長簟，當軒泊小舟。","枕前看鶴浴，牀下見魚遊。","洞戶斜開扇，疎簾半上鉤。","紫浮萍泛泛，碧亞竹修修。","讀罷書仍展，碁終局未收。","午茶能散睡，卯酒善銷愁。","簷雨晚初霽，窗風涼欲休。","誰能伴老尹，時復一閑遊。"]', '["繚繞府西面，潺湲池北头。","鑿开明月峽，決破白蘋洲。","清淺漪瀾急，夤緣浦嶼幽。","直衝行徑斷，平入臥斋流。","石叠青稜玉，波翻白片鷗。","噴时千点雨，澄处一泓油。","絕境應难別，同心豈易求。","少逢人愛翫，多是我淹留。","夾岸鋪长簟，當軒泊小舟。","枕前看鹤浴，牀下见鱼游。","洞戶斜开扇，疎簾半上鉤。","紫浮萍泛泛，碧亞竹修修。","读罷书仍展，碁終局未收。","午茶能散睡，卯酒善銷愁。","簷雨晚初霽，窗风涼欲休。","誰能伴老尹，时复一闲游。"]', '诗', 'shi', '', NULL, '府西池北新葺水齋即事招賓偶題十六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa2f2676-f244-4d86-a6f5-ead20f9410f8', '哭崔兒', '哭崔兒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["掌珠一顆兒三歲，鬢雪千莖父六旬。","豈料汝先爲異物，常憂吾不見成人。","悲腸自斷非因劒，啼眼加昏不是塵。","懷抱又空天默默，依前重作鄧攸身。"]', '["掌珠一顆兒三歲，鬢雪千莖父六旬。","豈料汝先爲異物，常憂吾不见成人。","悲腸自斷非因劒，啼眼加昏不是塵。","懷抱又空天默默，依前重作鄧攸身。"]', '诗', 'shi', '', NULL, '哭崔兒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cff2300a-74e5-4813-9775-c17364dfc883', '初喪崔兒報微之晦叔', '初喪崔兒報微之晦叔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["書報微之晦叔知，欲題崔字淚先垂。","世間此恨偏敦我，天下何人不哭兒。","蟬老悲鳴拋蛻後，龍眠驚覺失珠時。","文章十帙官三品，身後傳誰庇蔭誰。"]', '["书報微之晦叔知，欲題崔字泪先垂。","世间此恨偏敦我，天下何人不哭兒。","蟬老悲鳴拋蛻後，龙眠驚覺失珠时。","文章十帙官三品，身後傳誰庇蔭誰。"]', '诗', 'shi', '', NULL, '初喪崔兒報微之晦叔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90fc8301-75ed-434e-8b23-db82081f55dd', '府齋感懷酬夢得', '府斋感懷酬梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["府伶呼喚爭先到，家醞提攜動輙隨。","合是人生開眼日，自當年老歛眉時。","丹砂鍊作三銖土，玄髮看成一把絲。","勞寄新詩遠安慰，不聞枯樹再生枝。"]', '["府伶呼喚爭先到，家醞提携动輙隨。","合是人生开眼日，自當年老歛眉时。","丹砂鍊作三銖土，玄髮看成一把絲。","勞寄新诗远安慰，不闻枯樹再生枝。"]', '诗', 'shi', '', NULL, '府齋感懷酬夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('765f0774-e40c-4aca-b274-d2120353ff0f', '齋居', '斋居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香火多相對，葷腥久不嘗。","黃耆數匙粥，赤箭一甌湯。","厚俸將何用，閑居不可忘。","明年官滿後，擬買雪堆莊。"]', '["香火多相对，葷腥久不嘗。","黄耆數匙粥，赤箭一甌湯。","厚俸將何用，闲居不可忘。","明年官满後，擬買雪堆莊。"]', '诗', 'shi', '', NULL, '齋居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37835093-80d6-4331-9591-d6813541f4f9', '與諸道者同遊二室至九龍潭作', '與諸道者同游二室至九龙潭作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["喜逢二室遊仙子，厭作三川守土臣。","舉手摩挲潭上石，開襟斗藪府中塵。","他日終爲獨往客，今朝未是自由身。","若言尹是嵩山主，三十六峰應笑人。"]', '["喜逢二室游仙子，厭作三川守土臣。","舉手摩挲潭上石，开襟斗藪府中塵。","他日終爲独往客，今朝未是自由身。","若言尹是嵩山主，三十六峰應笑人。"]', '诗', 'shi', '', NULL, '與諸道者同遊二室至九龍潭作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac24f165-9fea-4c03-9f12-bfbc8a34e769', '履道池上作', '履道池上作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["家池動作經旬別，松竹琴魚好在無。","樹暗小巢藏巧婦，渠荒新葉長慈姑。","不因車馬時時到，豈覺林園日日蕪。","猶喜春深公事少，每來花下得踟躕。"]', '["家池动作經旬別，松竹琴鱼好在無。","樹暗小巢藏巧婦，渠荒新葉长慈姑。","不因车马时时到，豈覺林园日日蕪。","猶喜春深公事少，每来花下得踟躕。"]', '诗', 'shi', '', NULL, '履道池上作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('771f975f-ac98-4eac-92a6-c3e17d830004', '六十拜河南尹', '六十拜河南尹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["六十河南尹，前途足可知。","老應無處避，病不與人期。","幸遇芳菲日，猶富強健時。","萬金何假藉，一醆莫推辭。","流水光陰急，浮雲富貴遲。","人間若無酒，盡合鬢成絲。"]', '["六十河南尹，前途足可知。","老應無处避，病不與人期。","幸遇芳菲日，猶富強健时。","万金何假藉，一醆莫推辞。","流水光陰急，浮云富貴遲。","人间若無酒，尽合鬢成絲。"]', '诗', 'shi', '', NULL, '六十拜河南尹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c8f0f7d-48ca-4579-b0aa-587acf829581', '重修府西水亭院', '重修府西水亭院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["因下疏爲沼，隨高築作臺。","龍門分水入，金谷取花栽。","繞岸行初匝，憑軒立未迴。","園西有池位，留與後人開。"]', '["因下疏爲沼，隨高築作台。","龙门分水入，金谷取花栽。","繞岸行初匝，憑軒立未迴。","园西有池位，留與後人开。"]', '诗', 'shi', '', NULL, '重修府西水亭院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e7a5f3-ec94-4e05-9db0-66d160541172', '與諸公同出城觀稼', '與諸公同出城观稼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老尹醉醺醺，來隨年少羣。","不憂頭似雪，但喜稼如雲。","歲望千箱積，秋憐五穀分。","何人知帝力，堯舜正爲君。"]', '["老尹醉醺醺，来隨年少羣。","不憂头似雪，但喜稼如云。","歲望千箱積，秋怜五穀分。","何人知帝力，堯舜正爲君。"]', '诗', 'shi', '', NULL, '與諸公同出城觀稼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01c0a4b6-2b04-4cef-9050-c5152317a032', '水堂醉臥問杜三十一', '水堂醉臥问杜三十一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞君洛下住多年，何處春流最可憐？","爲問魏王堤岸下，何如同德寺門前。","無妨水色堪閑翫，不得泉聲伴醉眠。","那似此堂簾幕底，連明連夜碧潺湲。"]', '["闻君洛下住多年，何处春流最可怜？","爲问魏王堤岸下，何如同德寺门前。","無妨水色堪闲翫，不得泉声伴醉眠。","那似此堂簾幕底，連明連夜碧潺湲。"]', '诗', 'shi', '', NULL, '水堂醉臥問杜三十一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf6918e-4a73-4458-afe9-b75dcb0d1cdc', '歲暮言懷', '歲暮言懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["職與才相背，心將口自言。","磨鉛教切玉，驅鶴遣乘軒。","只合居巖窟，何因入府門。","年終若無替，轉恐負君恩。"]', '["職與才相背，心將口自言。","磨鉛教切玉，驱鹤遣乘軒。","只合居巖窟，何因入府门。","年終若無替，轉恐負君恩。"]', '诗', 'shi', '', NULL, '歲暮言懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('114cf065-47e3-4799-8528-28f7096ac93d', '座中戲呈諸少年', '座中戲呈諸少年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衰容禁得無多酒，秋鬢新添幾許霜。","縱有風情應淡薄，假如老健莫誇張。","興來吟詠從成癖，飲後酣歌少放狂。","不爲倚官兼挾勢，因何入得少年場。"]', '["衰容禁得無多酒，秋鬢新添幾許霜。","縱有风情應淡薄，假如老健莫誇張。","兴来吟詠從成癖，饮後酣歌少放狂。","不爲倚官兼挾勢，因何入得少年場。"]', '诗', 'shi', '', NULL, '座中戲呈諸少年 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b220732d-1241-4a3d-bebd-062783fe694c', '雪後早過天津橋偶呈諸客', '雪後早過天津橋偶呈諸客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["官橋晴雪曉峩峩，老尹行吟獨一過。","紫綬相輝應不惡，白鬚同色復如何。","悠揚短景凋年急，牢落衰情感事多。","猶賴洛中饒醉客，時時䛏我喚笙歌。"]', '["官橋晴雪晓峩峩，老尹行吟独一過。","紫綬相輝應不惡，白鬚同色复如何。","悠揚短景凋年急，牢落衰情感事多。","猶賴洛中饒醉客，时时䛏我喚笙歌。"]', '诗', 'shi', '', NULL, '雪後早過天津橋偶呈諸客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('436e57e6-eb41-4a51-9427-f6d4cbe4058e', '新製綾襖成感而有詠', '新製綾襖成感而有詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水波文襖造新成，綾軟綿勻溫復輕。","晨興好擁向陽坐，晚出宜披蹋雪行。","鶴氅毳疎無實事，木棉花冷得虛名。","宴安往往歡侵夜，臥穩昏昏睡到明。","百姓多寒無可救，一身獨煖亦何情。","心中爲念農桑苦，耳裏如聞飢凍聲。","爭得大裘長萬丈，與君都蓋洛陽城。"]', '["水波文襖造新成，綾軟綿勻溫复轻。","晨兴好擁向陽坐，晚出宜披蹋雪行。","鹤氅毳疎無實事，木棉花冷得虛名。","宴安往往歡侵夜，臥穩昏昏睡到明。","百姓多寒無可救，一身独煖亦何情。","心中爲念農桑苦，耳裏如闻飢凍声。","爭得大裘长万丈，與君都蓋洛陽城。"]', '诗', 'shi', '', NULL, '新製綾襖成感而有詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07c8b2cb-4eee-4d3e-a9dc-1e3c48626beb', '早春雪後贈洛陽李長官長水鄭明府二同年', '早春雪後贈洛陽李长官长水鄭明府二同年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獻歲晴和風景新，銅駞街郭暖無塵。","府庭共賀三川雪，縣道分行百里春。","朱紱洛陽官位屈，青袍長水俸錢貧。","有何功德紆金紫，若比同年是幸人。"]', '["獻歲晴和风景新，銅駞街郭暖無塵。","府庭共賀三川雪，縣道分行百里春。","朱紱洛陽官位屈，青袍长水俸錢貧。","有何功德紆金紫，若比同年是幸人。"]', '诗', 'shi', '', NULL, '早春雪後贈洛陽李長官長水鄭明府二同年 白居易 shi');
